/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170925-8","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"そこら辺はここの駐輪場においては、どのように意識をされ、どのような形の駐輪ラックを設置されるのか教えていただきたい。","respondent":"桑波田交通安全担当課長","answer":"駐輪ラックの既に設置してあるところ、そちらのほうに区画線だけを引いて、そのスペースに置いていただくようにするものです。新設する６３台につきましては、こういった大型車にも既に対応できるように、設置幅の広いラックを設置して対応できるようにやっていくものです。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"どのようなことが予想され、あるいは、どのようなことを想定されているのか説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"今回、２カ所の歩道上に設置をしますけれども、まず、駅前ロータリーにつきましては幅４ｍということで場所を確保しております。自転車に関しても、この辺のところは、降りていただいて駐輪するようなご案内も、今後していくように考えているところです。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"２カ所ありますうち西大井広場のところ、先ほども冒頭にお話をしましたように、最近つくられている自転車は非常に頑丈にできております。昔の自転車と違って、そこらあたりに十分配慮しながら計画を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"６３台の設置で足りるのか、どういう方なのか、把握していらっしゃるのか伺います。もう１つは、その教訓はどのように生かしていくのか、また整備計画に反映させたのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"大きいものに対応できないものも多数ありますので、そういった方、キャンセル待ちの方は使用できるようになると考えております。歩道上に設置するのですが、また、それを拡大して周りの離れたところも６町会あわせてご説明をさせていただきました。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"１日１５０円かかるとなると、せっかくつくるのであれば、そういった現在の利用者の方のニーズを合わせていく必要が今後あると思うのです。当日利用だけというのは、ちょっと見直したほうがいいのではないかという気もするのですが、そこら辺についてはいかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"あわせて既設の駐輪場も当日利用がありまして、そういったところを既設の駐輪場の中の当日利用も一部定期のほうに変えてやるということで、そういったふうに当日をつくることによって定期の方もカバーするという考えで実施しています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"２時間枠とか、無料枠とかを設けるべきだと思うのですけれども、そこら辺は設ける考えはおありでしょうか。設けていただきたいと思うのですけれども、設けないというのであれば、なぜなのか、その理由も伺います。","respondent":"桑波田交通安全担当課長","answer":"料金につきましては、やはり区営の駐輪場ですので、通勤・通学でお使いいただく方に受益者負担という考えで使用料をお支払いいただくと。こちらは無造作に短時間としますと、本当に真に使いたい、無料ということは現在考えているところではございません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこの１点確認。何か少し歩行者と自転車をとめる方との事故がないような看板ですとか注意を促すようなことを少ししてほしいと求めましたが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"既設の駐輪場の中にも当日と定期がありまして、こういったものを改修することによって、キャンセル待ちは解消されると読んでおります。それと、注意喚起ですけれども、こちらについては、看板等を設置しながら注意喚起は図っていきたいと考えております。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"放置自転車に対しての今後の鉄道事業者との協力のあり方について確認をさせてほしいと求めました。改修していく際に、そういった方向で今後やっていくのかどうかという、全体の方向性を確認させてほしいと求めました。","respondent":"桑波田交通安全担当課長","answer":"いろいろ各種キャンペーンや広報活動を通じながら連携を図っておりますので、撤去活動とあわせて、その辺は連携を図っていきたいと考えております。差があるのですが、そういった全体的なものを来年度以降いろいろ調査しながら、どうあるべきなのかというのは考えてまいります。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"利用率が高いというような、今、データが入ってきているということでお聞きいたしました。定期利用、その辺のフレキシブルに対応していただきますように、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたいのは、この増設、６３台とありますが、通勤の方々を対象としたものとして考えているのでしょうか。そこをお聞きしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"定期に入らない、本当に毎日ではなくても週に何回かぐらいしかお使いいただかないという方もいらっしゃいますので、そういった方にもお使いいただけるように考えて計画しています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"結局そこの対策がされていないから流れてきてしまうということがあるわけではないですか。それから、全体の状況の責任をどういうふうに考えて、放置自転車への対策を考えているのかということをお聞きします。","respondent":"桑波田交通安全担当課長","answer":"ジェイタワーの前だとか、こういったところもやはり放置しているということで、地元の方のお声もいただいております。鉄道事業者も含めまして、そういった問題の共有ですとか、話し合いの場を設けながら対策等も今後も進めていきたいと考えております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"そうなったときに、なぜあそこを締め出すのですかという話です。自分たちの店に来ているお客さんに対して、自転車対策をなぜとらないのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"そういったものはやはり店舗の顧客の方ですので、その辺のところはお店もなかなかすぐにだめだということは言えないような心境的にはあると思います。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"あそこは３階でしたか、屋上まで入れると３階、それ自体をもうちょっと大きくするとかということは可能なのでしょうか。６３台でオーケーとなるのか、もっと将来的には、あと２００台、３００台という対応をしていかなければならない現状なのか、そこを説明を求めました。","respondent":"桑波田交通安全担当課長","answer":"とりあえずは、今、６３台設置することによってキャンセル待ちの方はお使いいただけるようになるというふうに読んでおります。今後、新しいマンションの建設等があれば増えてまいりますので、いろいろな区内の駐輪場の需要等も考慮しながら検討していきたいと考えております。","id":"exchange-013"},{"speaker":"いながわ副委員長","kind":"質問","question":"何点かお伺いしたいのですけれども、有人ではなくて無人のそういった感じのものがここにできるというイメージでいいのかどうなのかということが１点。","respondent":"桑波田交通安全担当課長","answer":"精算するときに精算機にお金を入れていただいて解除されて引き抜くというようなものを入れる予定です。そういったものもありますし、現在実施しています幅を広げることによってスペースをとって出し入れしやすくするようなものがあります。","id":"exchange-014"},{"speaker":"いながわ副委員長","kind":"質問","question":"自重が重いので、自転車もだんだん変わってくる中に対応できる駐輪場に早急にしたほうがいいと思いますので、その辺について教えてください。ご答弁を。","respondent":"桑波田交通安全担当課長","answer":"この写真で入れさせていただいていますこの手前のほう、４ｍと書いてあるこの植栽のところに１台設置するように計画しております。そういったものも含めまして、今後また新しく増設ですとか改修をする際に、そういったものに対応できるように改修していきたいと考えております。","id":"exchange-015"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"公園前の歩道で２カ所端のほうに精算機をつくるというのですけれども、端は端でいいのですけれども、これは１００ｍぐらいあるのですか。僕はわからないですが、そんなにないか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"公園前歩道につきましては、２つ合わせますと全長で６６ｍほどございまして、その手前側のほうの１個と、奥のほうは、この中間点あたりにつけるように計画しております。","id":"exchange-016"},{"speaker":"西本委員","kind":"確認","question":"この地図の中で確認だけです。西大井保育園はここか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"地図が間違っておりまして、申し訳ありません。地図でいきますと、現在は、「森前」と書いてありますこちらのほうに移転しています。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"先ほど、質問で述べさせていただきました。地域ぐるみでという意味での放置自転車対策を心がけて、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","agenda":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今後も新たな標識が増えたり、道路が新設されたら、こういった条例改正が必要になるということなのか伺います。これからも頻繁にありそうなことなのかどうか伺います。","respondent":"多並道路課長","answer":"今のご質問のとおり、必要が生じれば、もちろん条例改正が必要です。全部で７０ほど標識がありまして、その中で寸法に関するものということですので、影響としては大きくはないかと思っているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"つくり直す場合に、どこの予算で、誰がつくり直すのですかということ。この目的はどういうものをもっての目的があって、品川区にとってどういうメリット、デメリットがあるのか説明を求めました。","respondent":"多並道路課長","answer":"その標識が寸法で縛っているもののうち、うちの区道に関するものが先ほどご説明した内容です。それが逸脱するということができない場合があるので、そういうものを全体的に参酌して可能にする、そういう内容です。","id":"exchange-020"},{"speaker":"いながわ副委員長","kind":"質問","question":"区民生活にどうこうというものではなく、先ほどちらっと話が出たのですけれども、ここにサイズが書いてあるではないですか。新たに標識番号をつくって、また狭いバージョン用といいますか、そういった標識をここに追加をする感じになるのか尋ねました。","respondent":"多並道路課長","answer":"今おっしゃった形でやるとしますと、条例改正ということで、寸法を変える形で……。","id":"exchange-021"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の追加にあらわれる今の実態として、狭隘な道路に面した戸建て住宅の建替えが進んだ結果ということでよろしいのでしょうか。伺いたいと思います。","respondent":"鈴木建築課長","answer":"今現在のところですけれども、全体のうちの７３％ということですので、木密地域の防災性の向上が進んでいるです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"意見","question":"当初の見込みと比べて６,７００万円増えたということなのですけれども、一見すると、かなり大きな差額に思えるのですけれども、なぜこのような差額というか、予想より差が出たのかということを具体的にお知らせくださいとの意見を述べました。","respondent":"鈴木建築課長","answer":"過去３年間、平成２６年、平成２７年、平成２８年の平均を見ますと、１件当たりの整備費が約８０万円です。これまでの今年度の平均が約１００万円で２０万円ぐらい見込み上がっているというところと、これも４月に上がっているというところも影響しています。","id":"exchange-023"},{"speaker":"筒井委員","kind":"意見","question":"そういったことが過去３年間のデータを見ると、予想はできなかったということでよろしいのかということと、やはり今後の工事にあたり、１件８０万円ではなく１件１００万円ぐらいだという見積もりで今後事業を行っていくのか、この２点をお知らせくださいとの意見を述べました。","respondent":"鈴木建築課長","answer":"過去の３年間あるいは４年間の平均をとってやっているのですけれども、１件当たり１００万円前後の想定で、整備を進めていくということでの予算増額補正です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"補助２８号線、補助２９号線も含めると、その上でのこの補正予算の成り立ちになっているのでしょうか。その上で今回の金額で今のところはやれるのかというところの見通しはいかがなのか尋ねました。","respondent":"鈴木建築課長","answer":"これはその後、契約ということになりますけれども、おおむね１２月ぐらいまでの見通しはついている。２、３月分について、今年度しっかりやっていきたいというものです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"ここはいずれ整備しますと決まっているものがあるではないですか。それも１年ではなくて数年にわたっての計画が出てくるのではないかと思うのですが、そういう見方はいかがなのか尋ねました。","respondent":"鈴木建築課長","answer":"やはり１件当たりの規模ですとか、区内の二項道路の３割ぐらいの拡幅が進んでおりますので、要求をさせていただいているというものです。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"それと最後に確認は、お金の流れを、歳入のところは所管ではないということなのですが、この必要ですというお金が補正がかけられました。国の補助金ということで申請をするということと、決まってくると入ってくるという、そういう流れでよろしいのか尋ねました。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、歳出分、増えた分について、都と国から歳入分が入ってくるというものです。","id":"exchange-027"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"やはり区民の方々が間に入っているわけですから、今後もその場に応じてしっかりやってほしいと求めましたので、よろしくお願いいたします。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","agenda":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"Ａ３の書類のほうの２番の説明会のことで、もう少しお話ししたいと思います。出席者は７７名で、どのような方にどういう形でこの説明会を案内をされての７７名だったのかということをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"こちらですが、地区内の権利者ということでございまして、土地所有者、それから借地人の方々に対しまして、ご案内の通知を差し上げまして説明会を開催したです。","id":"exchange-029"},{"speaker":"新妻委員","kind":"質問","question":"ここの地区内の全員の方にご案内をしてということでよろしいのでしょうか。それはポスティングか何か、また、書面か何かでご案内をされたということか尋ねました。","respondent":"稲田都市開発課長","answer":"この地区内の権利者の方、それから借地人の方に郵送でお知らせをしております。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"ご案内はされていなかったけれども、周辺の方も参加されたということでよろしいのか尋ねました。","respondent":"稲田都市開発課長","answer":"そのとおりです。","id":"exchange-031"},{"speaker":"大沢委員","kind":"意見","question":"全員で７７名ということですけれども、説明あるいは今までの平成１８年からの時系列を追いながら、お答えできなければ結構です。なぜこういうふうな話が出てきたのか、どのように分析をされているのか、聞かせていただける部分があればいいですし、なければ答えなくて結構ですとの意見を述べました。","respondent":"稲田都市開発課長","answer":"私の考えですが、説明等はこのようにやってきているところですけれども、引き続き丁寧に説明は行っていきたいというふうに考えております。","id":"exchange-032"},{"speaker":"大沢委員","kind":"確認","question":"「個々に」か、「個別」という単語が出ていて、この別にも「個々に」あるいは「個別に」ということは説明をされてきたのでしょうか。もう１回、確認をお願いします。","respondent":"稲田都市開発課長","answer":"事業者におきましても、個別に説明をしたり、また、区におきましても、原案説明会を開催前後ですが、いろいろとご心配等が来ておりまして、区や都におきましても説明はしています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"資料についてお伺いしたいのですが、地区内の方が何件何人、地区外の方からは何件何人だったのかお伺いしたいということが１つです。これは第１６条第１項ではない理由をお伺いしたいのと、１０月１０日に行われる予定の説明会は、都市計画法何条に基づくものなのか説明を求めました。","respondent":"稲田都市開発課長","answer":"都市計画原案の説明を行いましたときに、意見書等で出てきたものの数字ですけれども、全部で３４通の意見が出ております。第１７条に基づきまして１０月１０日に実施するものですが、これは広く区民の皆様方に案内をして、広く意見を聞いていくというものです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"どのような内容だったのかということをざっと教えていただきたいのと、１項を読み上げますけれども、市町村は云々とあって。対象者をわざわざ第１６条第２項として、先ほども伺ったのですけれども、なぜ第１６条第１項でやらなかったのかということをお伺いします。","respondent":"稲田都市開発課長","answer":"第１６条第２項のときの説明会におきましては、先ほども申しましたけれども、高さの関係、それから風の関係等々が出ているです。しっかりと住民の皆様に説明をしてくださいというところで、１６日に、事業者による開発計画の説明会を行ってきたです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"７日、８日のときに、地区内の関係権利者だけを対象にしたのかの理由がよくわからなかったので教えていただきたいというのが１点です。要旨で書いていますが、住民の方がどんな影響を受けていると区は考えているのか、そこら辺はどのように捉えておられるのか伺いたいと思います。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"このような中では、地権者、当事者への説明が最初というのは、特に問題はないと考えております。この説明が一度もなされないまま進められるということは… こちらを安全に安心なまち、そしてにぎわいのあるまちをつくっていく、西口の駅前にふさわしいような地区にしていくというところでやるものです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"それともう１つは、原案と案、私が伺ったのは、原案が案になれば、より決定に近づくわけです。区民、利害関係者の方も入れるべきではないですかということを伺ったので、答えるよう求めました。","respondent":"稲田都市開発課長","answer":"区でやる説明会が、先ほどもご説明してきましたが、事業者による近隣への説明。第１７条に基づいて１０月１０日に説明して、広く区民の皆様にもご案内して、そこできちんと意見を言っていただくというふうなことでやっております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、まちづくり、近隣住民に区が責任をもって説明をするというのは１０月１０日が初めてなのではないですか。それで間違いないのですかということを伺ったので、それはお伺いしたいというのが２点目です。","respondent":"稲田都市開発課長","answer":"その後ですが、予測との違い等で対応をしていくというふうな形でやっておりますので、地域の皆様のご不安等に対してはご説明をして解消していくです。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"実は私も４月の説明会には参加しましたけれども、個別に事業者が近隣の住民の方に、数人のグループなどにも説明しているという話も伺いました。ですから、そうしたこともやってほしいと求めましたが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"１０月１０日、説明会を行いまして、また公告・縦覧をして、意見を十分に皆さんから聞いていくという体制です。引き続き、地域の皆様等への丁寧な説明を十分にしてくれというところで指導も区としては行っていきたいというふうに考えております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"１１月に都市計画審議会を開催すると、これは一旦白紙にしていただきたいと思うのですが、いかがでしょうかというのが１点。具体的に出した意見書は、案にどのように反映されるのか、そこは伺いたいと思います。","respondent":"稲田都市開発課長","answer":"４番、今後の予定ですが、１１月に区の都計審、それから１２月に都の都計審を予定しています。これはあくまでも予定ではありますが、この予定に沿いながら進めていけたらいいというふうに考えております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"しっかりと変えなくてはいけない案件があると思いますので、意見書は案に反映させてほしいと求めました。長い期にわたるまちづくり、大崎のまちにかかわってくる大問題ですので、ぜひスケジュールありきで進めていただかないよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、地区内の関係権利者、すなわち土地所有者、借地人の方が２７名いらっしゃるということなのですけれども、今回の再開発に賛成の方は何人いらっしゃるのか、それで、その賛成された方が準備組合を結成されたのかということをお伺いいたします。","respondent":"稲田都市開発課長","answer":"現在、仮の同意率というところでいきますと、２７名のうち２４人が同意をしているというような状況があります。まだ仮という状態です。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"仮ということですけれども、２７人中２４人が賛成をされているということです。同じ大崎地域に住む区民の方ですから、やはり良好な関係をぜひ保っていただきたいと私としては考えておりますので、区のご見解をお知らせください。","respondent":"稲田都市開発課長","answer":"周辺の皆様方には丁寧な説明、引き続き丁寧な説明をして、この計画のご意見等を伺いながらやっていきたいというふうに考えております。今後、基本的には、このような形で説明会としてはこれをやっていくものです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも周辺区民の納得が得られるようなご説明を引き続き何とぞよろしくお願い申し上げます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"やはり青い地域を考えての中の１つだと思っているので、そういう将来にわたるビジョンについてはどのような考え方をして進められているのでしょうか。お聞きします。","respondent":"稲田都市開発課長","answer":"そういうところで住宅機能をもって、今回、まちづくりを進めていくです。準備組合で検討している段階ではありますが、具体的な取組みは、まだこれから進められていくです。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"そこの進め方については、どのようになっていたのでしょうかということが１つ。その上で、南地区、東地区、北地区の開発を進めていきたいと思うのですが、その辺のお考えはいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"今もしていますが、今回この大崎三丁目地区におきましては、ＪＲ東京支社のほうにも計画等を十分に説明しております。鉄道事業者が対応するというところにはなるかと思いますけれども、安全な対策がとれるよう、ＪＲ等々と協議をというふうに思っています。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"この説明資料の中の２番の(1)、８月７日、８日のことの認識でよろしいのでしょうか。これは大もとの根拠は第２項ですか、第１６条第２項がそうなっているので、そこの法的なところの関係性をもう一度確認させてください。","respondent":"稲田都市開発課長","answer":"第１項が公聴会等を必要に応じてですけれども、先ほども申し上げましたが、事業者、国による説明等も行ってきております。説明もして話を受けるということで、１０月１０日に行うものは、広く区民の皆さんからご意見を伺うというところでやる予定です。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"準備組合の方々が権利者の方々に、どういう条件ですか、どういうお考えですかということを細かく聞いていると聞いております。そこら辺をもうちょっとわかりやすいように区民の皆様方に知らせる方法を今後とっていくべきなのではないかと思いますが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"権利者説明会を法にのっとりながらやっていって、第１７条に基づく説明会もこの内容です。今後もより一層、地域の皆様には説明会の進め方等におきまして、わかりやすいような説明には努力していきたいと思います。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった意味で、そこは１０月１０日の前にしっかり区としてもっと早くやるべきだったのではないですかということなのです。お伺いします。","respondent":"稲田都市開発課長","answer":"説明会、説明会におきましても説明をして意見をいただき、ご心配やそういうものに対しても十分にこたえてきている。変更する必要があるというところにおきましては、取り入れていきたいというスタンスで臨んでおりますので、問題ないと思います。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"変更する必要がある場合はきちんと変更していただきたい。もしこの品川区の大崎駅のこの１４９ｍ、３９階建て、堂々と説明していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成１９年から組織をつくりながらして、地元の皆さんの自発、発意に基づいて行われるのが再開発であります。しかるに、この件に関しては、自民党・子ども未来としては願意に沿うことができないので、これに対しては不採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"新妻委員","kind":"意見","question":"平成１９年から準備組合が立ち上がって、この地元の当事者の方も２７組中２５人が加入をしており、ご説明いただいたとおりであると思います。よって、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"やはり、やはり周辺の方も含めて計画段階から早期に意見を伺いながらしっかりやっていくということがまちづくりの基本だと思います。採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"いながわ副委員長","kind":"意見","question":"今回の陳情に関しては、説明しているということで、不採択にしてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"良好な区民関係維持のためのご努力はしていただきたいということで、引き続き、丁寧な説明をお願いしたいと考えております。結論としましては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"そうは言っても、高層ビルが建つのはどうなのだろうか、まちづくりをつくっていくのが最も好ましいことではないかというふうに非常に感じました。今回の陳情を契機に、まちづくりは何だろうというところまで深く考えていかなければならないのではないかというふうに感じさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-05","title":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","agenda":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"かなり心配されている区民の方々がたくさんいると思うのですけれども、せっかくですから、陳情に至った思いを直接伺いたいので、できれば審査の前に私は陳述を聞きたいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"ですから、前ではないということです。今、安藤委員の言ったことには反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"この陳情を受けて、その議論をするということで、さらに説明が必要だというときにお願いするという形になると思うのです。なので、事前に聞くということは、この陳情、流れ、仕組みに関してちょっとおかしいのではないかと思っているので、大沢委員と同じように思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"２項目目の対処法というのがあるのですけれども、ミサイルが着弾した場合の対処法とは何か、具体的に伺いたいと。伺いたいと思います。","respondent":"川部防災安全担当課長","answer":"東京都から示されたときの消防、警察と連携した避難の実施ですとか、そういったものが着弾時の措置としては想定されているところです。２つ目の訓練はいかにですけれども、これも先ほど防災課長が説明したとおり、まずは訓練以前に。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"どういった措置を考えているのか、もう一度お伺いしたいのと、もう一度そこら辺をお聞かせいただけますか。訓練するということか尋ねました。","respondent":"川部防災安全担当課長","answer":"今申し上げたようなＪアラートが発動したときに、どういう措置を一人ひとりがとればいいのかというようなことをお知らせすることを想定しております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今、やるべきことで最大の危機は、このケースですと、米朝両国の軍事的緊張が今エスカレートしてしまっている。厳に慎むべきだと思いますし、エスカレートしてしまうということにつながりかねないと私は心配しているのですけれども、いかがか尋ねました。","respondent":"川部防災安全担当課長","answer":"まず１点、確かに直撃してしまえば相当な被害は避けられませんし、人間の力ではどうすることもできないこともあります。やはり区としての大きな責務にあると思いますので、今後そのあたりを肝に銘じて対処していきたいと、このように考えております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば９条を変えてしまうとか、非核平和都市品川宣言を持ちながら政府に批准を求めるということも言わないとか、私は。そこに注力していただきたいと思うのですけれども、そちらのほうに力を入れてほしいと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"その１つの手立てとして、それが可能なのかどうか、今お聞きしたいと考えております。これが３点目で、以上３点、ご答弁をお願いします。","respondent":"川部防災安全担当課長","answer":"先ほど来、お話が出ておりますＪアラートが発動した場合の対応ですとか、そういったものがわかりやすく記載されている部分があります。当初はまずは周知というように考えてはありますが、今後の訓練の実施方法等々について研究していきたい、このように考えております。","id":"exchange-064"},{"speaker":"西本委員","kind":"確認","question":"確認だけです。この陳情の文章の中の下から５行目、これは品川区というより国の評価ということかもしれませんが、失敗という認識なのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"状況だけお聞かせ願いたいのですけれども、避難訓練を実施したのは秋田県ということで認識をしておりますけれども、それ以外に避難訓練をやったという情報なりは行政のほうでお持ちか尋ねました。","respondent":"川部防災安全担当課長","answer":"正確には政府と自治体の連携訓練ということだと思うのですが、島根県ですとか、各所で政府と自治体連携の訓練は既に実施されているところです。ほかにも最近では、東京都千代田区の小学校でＪアラートが鳴ったことを想定した避難訓練が行われたと、これは報道で認知をしています。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"となると、特別区ということで絞り込んでお伺いしますけれども、今、千代田区の小学校がＪアラートが発令されたという想定で訓練を行った。それのみで認識してよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"私のほうも直接各区なりに当たったわけではないのですけれども、今現在、報道されているというところでは、その１件のみかと思います。自治体として、例えば何々区としてＪアラートが発動したときの訓練を行ったというようなことは今まで掌握はしてございません。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、先ほど来のご答弁の中で、まずはＪアラートについて、区民に周知がまず第一義、初段の段階だということで、先ほどのご答弁の中では、まだ全ての部分でしっかりとした対策に対する整備がまだできていないように感じましたけれども、それについてコメントをお願いします。","respondent":"川部防災安全担当課長","answer":"「北海道地方から太平洋に通過した模様です」というような地域的なことをより具体的に文言を改めまして政府の対応としたところです。まず国の対応自体も、検討しながら、このように考えております。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"確かに陳情者の１から４番については、国の危機に関することですから、今の課長の答弁があった。となると、これはまだ、これをさらにブラッシュアップする課題あるいはそのものに対する懸念が数多くあるというふうに認識してよろしいか尋ねました。","respondent":"川部防災安全担当課長","answer":"いろいろとやり方を研究、検討していかなければいけないということは確かなことだと思います。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"こうした生の意見を伺う機会はしっかりと保障していくといいますか、それがやはり議会改革にもつながることだと思いますし、私はぜひ積極的にこうした機会があれば受けていくべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"西本委員","kind":"意見","question":"私も、今回の質疑の内容で、現状、それから課題、これからしなければならないことが、対応していくだろうということも含めて理解した上での結論が出せるかと考えていますので、意見陳述は必要はないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"いながわ副委員長","kind":"意見","question":"国民保護計画があるということを区民の皆様に知っていただくということが大切なところだと考えていますので、それを今後やるという話も先ほどされておりましたので、特に意見陳述を設けるに至らないと私は思いますとの意見を述べました。","respondent":"たけうち委員長","answer":"ご意見が分かれましたので、意見陳述の実施について、挙手にてお諮りしたいと思います。","id":"exchange-072"},{"speaker":"大沢委員","kind":"意見","question":"ほかの部分については、他の１項目、２項目、４項目については、既に区におきまして行っているということです。したがいまして、この陳情については、願意に沿い難い、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"新妻委員","kind":"質問・要望","question":"結論としましては、不採択でお願いいたします。この周知が必要であるというご説明がありましたので、そのことをしっかりと行っていただきたいという思いを込めますが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから万全の被害予防や被災者救援の対策が求められるのですけれども、人為的に引き起こされるものですから、逆に。区長もこれだけの危機を目の前にしているわけですから、みずから首相に今こそ対話に踏み切るべきだということを米国政府に説いてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"ぜひＳＮＳを含む、ホームページは見なければ見られないわけですから、発信をするということは非常に必要だと考えています。今いきなりこれをやると、まだ時期尚早なのかという部分がありますので、陳情の内容に関しては不採択でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に２項目目です、区議会だよりや掲示板等々、いろいろな媒体を使って徹底した周知を行っていただきたいと考えております。ということで、採択とまではいきませんけれども、この陳情者の思いを汲みまして、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"ただ、そもそもどういう訓練が必要なのかということが、まだ国として定められているわけではないのではないかというふうに思っています。本当にいいのですかというようなことがありまして、避難する経路がどうなっているのかという細かい準備がやはり必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"損害賠償額は保険からまかなわれているということを確認させていただきましたが、年間で見ると、この事故の件数は減っているのでしょうか。それとも毎年同じぐらいの事故が発生してしまっているのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"年間によってばらつきがあろうかと思いますけれども、昨年が、車の事故が４件、作業中の事故が２件ということで６件でございました。今年度はすでに、今、車の事故が２件、作業中の事故が２件ということで、そういった意味では、少し増えているような状況です。","id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"これは修理費だけなのですけれども、けがとかはいかがだったのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"けがの状況ですけれども、当日、救急車を呼びまして病院に運ばれたですけれども、その日のうちに退院した。しかしながら、重傷には至らなかったですけれども、胸の部分を打ったというお話を聞いておりますけれども、全治１カ月ということを聞いてあります。","id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"この治療費とかはどこで、ここには計上されないのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"その理由といたしましては、通勤の途上だったということで、会社のほうの通勤災害のほうでまかなわれるというお話をされておられました。そのような中で、私ども、示談をしたです。","id":"exchange-081"}]},{"id":"topic-07","title":"平成２８年度指定管理者による管理に対するモニタリング・評価","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"自転車の駐輪場のことでお伺いします。定期が少ないから当日を多くしようとか、逆に定期が足りないから当日を減らしてというような、そういうことは日常行われているものなのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"そういった改修工事も実施しておるところですけれども、そういったバランスを見ながら、各駐輪場のほうで実施しています。","id":"exchange-082"},{"speaker":"新妻委員","kind":"質問・要望","question":"かなり大きなところですけれども、人が周辺に増えたせいか、当日の利用枠が非常に少ないことが見受けられるのです。置く場所はありますので、定期のところをちょっとずらして当日枠を増やしていただく対応をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"ここは定期利用の利用率が非常に低い状況にありますので、その分、当日も多いという状況があります。この辺は指定管理者とも、そういった人員の関係等もありますので、その辺はよく調整させていただきながら検討していきたいと思います。","id":"exchange-083"},{"speaker":"安藤委員","kind":"確認","question":"そこら辺はどうなっているのかと、そこを確認したいのと、これは原因は何でしょうかというのが２点目です。それと、使用料と委託料の関係なのですけれども、お伺いしたいと。","respondent":"桑波田交通安全担当課長","answer":"大型車への対応が増えてきたことによって、やはり自転車の置く場所的に狭くて、使えるような状況が影響して年々下がっているという状況だと思います。そういったことと関連して、現在、駐輪場を広げるような作業を実施しています。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"すごいことだなと思ったのですけれども、毎日来庁して何をやっていらっしゃるのかお伺いしたいと思います。修繕費の出どころは、そうなると、自分たちでやりくりしているということなのか尋ねました。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"よろしくないことだと思いますし、また委託料につきましても、必要な数だけは指定管理者にはお支払いしてやっているところです。当区の係のほうにお届けいただいて、いろいろな検討を重ねていくというようなことで… 管理運営委託料も同様になっております。修繕のお話ですけれども、この指定管理料の中で組み込まれた形で指定管理者がこの予算の範囲内で行っているものです。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問・要望","question":"これらの意見や要望を住宅管理に反映させているというふうにあると思うのですが、具体的にはどのような例があるのでしょうか。お伺いしたいと思います。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"その後、時間が経過すれば、お金が課金されていくという状況になっております。本来必要な人が使えなくなるということがありますので、現在のところ、考えていないです。 日常的な生活に絡みます生活音に関してのトラブルであるとか、あとは、自転車や駐車場の利用に関してのご意見や苦情等が挙げられます。掲示板等に、それに関しての注意喚起の掲示を貼るであるとか、そういった対応をしております。","id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"１分でも、入れたら出すときに１５０円かかってしまうという、それは何か工夫できないのでしょうか。いかがか尋ねました。","respondent":"長尾住宅課長、桑波田交通安全担当課長","answer":"それが長期的になってくる、また福祉的な観点の対応が必要である、区の住宅課も協議しながら適切な対応がとれるように連携して動いているところです。高齢のひとり暮らしの方への対応というところですけれども… 今年度にかけまして、上層部のほうも改修していきますので、放置の関係も改善されていくものと見込んでおります。","id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"最近は１５０円要るのだと思って使っているのですが、可能であるならば、そのぐらいの配慮はしてほしいと思うのです。そこら辺はある程度わかる可能性はあると思うので、そこら辺の考慮はしていただくことはできないのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"５分間無料だったということは把握がないのですけれども、それを使うために持ってきていますので、その辺は注意して使っていただければと思います。","id":"exchange-088"},{"speaker":"いながわ副委員長","kind":"確認","question":"これは、最終的に品川区の所管がそれを確認して、この総括シートに何か書くという感じで流れとしてはいいわけですね。この接遇に関するテストとは何なのですかという。","respondent":"桑波田交通安全担当課長","answer":"１年間の指定管理者の業務報告ということで、そういったものを冊子になっているのですが、こういったものでいただいております。こういったものは利用者への対応ですとか、個人情報の取扱いですとか、サービス向上に齟齬がないように努めるような内容のテストになっております。","id":"exchange-089"},{"speaker":"いながわ副委員長","kind":"質問","question":"要は、テストに１回合格してしまえば、もういいのですねという話にしか見えないのです。その中で１回テストをやって、１年間何もなかったら、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"これは管理員の方が新しく採用になりまして、どこかの駐輪場へ行く。事前の教養で実施されているものでありまして、いろいろな共有についても、逐一やっているところです。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132633?Template=document&Id=4212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":70739,"voices":260}},{"id":"h29-20170925-9","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を96件整理しています。","topics":[{"id":"topic-01","title":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"今までもそういったものがあったということの確認と、あと、２００円や３００円という額の算定の仕方について伺いたいと思います。","respondent":"有馬学務課長","answer":"ですので、６,０００円を３０日で割ると１日当たり２００円ということで、配偶者は２００円となっております。それを３０日で割ると１日当たり３００円となるものでございまして、子どもは２００円から３００円に引き上げとなります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今回配偶者のほうが引き下げられて、子どものほうが引き上がったというところで、今までに品川区において、この公務災害補償を受けた方はいらっしゃるのか、また対象となる方が何人ぐらいいらっしゃるのか伺いたいと思います。","respondent":"有馬学務課長","answer":"これは以前、平成１３年度までは都条例ということでしたが、その後１件も公務災害に該当しているというものはありません。学校医等につきましては延べで２７０人ほどですけれども実数といたしましては２１５名の方が該当する学校医、薬剤師として働いているということです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"先ほどの説明の中で、大変申しわけないのですけれどももう一度説明していただけないでしょうか。経験年数が１０年から１６年未満と１６年以上ということについては、メモできたのですけれども、それ以降の説明のところを説明を求めました。","respondent":"有馬学務課長","answer":"アの配偶者の２００円というところはよろしいでしょうか。","id":"exchange-003"}]},{"id":"topic-02","title":"第６３号議案 品川区立図書館条例の一部を改正する条例","agenda":"第６３号議案 品川区立図書館条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、現在の大崎図書館は区もご存じのとおり地域の名士の方の邸宅跡を図書館にしてほしいという願いから建物計画などを。現在、この大崎図書館でいろいろ行っています読み聞かせなどは、いつ頃から行っているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"申しわけございません。読み聞かせの開始の記録については、開館当時からおはなしの部屋を用意していますので、開館のときから行われていたものと思われます。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"開館のときから行われていたということで、活発に読み聞かせなどを行っていたと思うのです。やはり子どもたちが日ごろ読書に親しみを持つことを気にかけている区の損失になるのではないかと思うのですけれども、この点いかがか尋ねました。","respondent":"横山品川図書館長","answer":"地域の方が交流するような場所を検討するという形で今進めてきているところでありますし、子どもの事業についても力を入れていく予定です。おじい様、おばあ様、大崎地区については子どもも大人もみんなで楽しめるような施設というコンセプトで進めてきている次第です。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それだけやはり地域の方々に利用されている図書館をなくす理由は何なのか伺いたいと思います。この多目的室は図書館専用のものになるのか、もしならないとすると、貸室のような扱いということであれば使用が有料になるのかも伺いたいと思います。","respondent":"横山品川図書館長","answer":"産業支援交流施設、ＳＨＩＰが開設したことに伴いまして、北品川五丁目に用地の確保の見込みがついたので移転という形をとらせていただいております。空いたスペースについてはどのように地域の方と運営していくかについて、これから検討を進めさせていただこうと思ってあります。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、地域の方が求めているのは、現在地に残してほしいということなのです。以前は品川区も改修で予算組みをしていたと思うのですが、移転に変わった理由というのは何なのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"その間、先ほどご説明しましたように北品川五丁目に新しい用地が取得できる見込みがあって。大崎駅西口方面に２拠点をあらたに設けて３拠点で支えるということでは、結果的には大崎地区の図書環境については向上するものと思ってあります。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"新大崎の閉架書庫が３万点ありますけれども、合理的に考えて移転にしたというところをもう少し詳しく教えてほしいと求めました。そして、この分館というのが、本館、いわゆる普通の図書館とどう違うのか、これは図書館法に基づくものなのかも伺いたいと思います。","respondent":"横山品川図書館長","answer":"こちらも全て新・大崎図書館もしくは平塚書庫のほうに移転する予定でございまして、今現在もそうですが、書庫からお出ししてお貸し出しするものです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"最初に分館について、図書館法に基づくものなのかということをお聞きしたので、基づくということでいいのかどうか確認させてほしいと求めました。そしてこの間、補助２９号線道路を進めるために行われているということがありますけれども、改めてそこのところを確認させてほしいと求めました。","respondent":"横山品川図書館長","answer":"それから、また北品川に予定している大崎図書館にも子どものコーナーをつくる、もっと小さなお子さんからご利用できるような施設ということで。区としては基本的には東京都に協力する姿勢ですが、今後の状況を注視していくところと聞いております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"定義づけというのでしょうか、法令上の位置づけがどうなっているのか、今ひとつよくわからないので改めて伺いたいと思います。これら３施設が開設されていく中で、それに合わせて廃館になっていくのか、どういったスケジュールで何が行われるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"今後のスケジュールにつきましては、来年６月に新しい移転先の大崎図書館が開館する予定です。その間、芳水小学校跡の図書施設の開設予定である平成３１年１月まで、西口の図書環境を支えていくような予定です。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"この大崎図書館では危険性があるということなので、どういったことか具体的に伺いたいと思います。現在、大崎図書館は平成３０年３月末で閉館というと、利用者の方にはそういったことをもう十分お知らせされているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"今、館内でお問い合わせにお答えできるようスタッフにいろいろなお答えをするような文言というか、統一的にお答えできるよう準備をしています。ご了承いただいた段階で、区としてはパブリックに公表できるということなので、こちらについて周知していきたいと考えています。","id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"この大崎図書館を廃館にして、老朽化に伴って廃館だというふうに主張されているわけですけれども、その点についてもう少し聞きたいと思います。その年限が３０年ということで、あった事例というのはどの程度あるのか、まずそこについて伺いたいと思います。","respondent":"横山品川図書館長","answer":"申しわけございません。具体的にお答えすることはできませんが、区の方針としまして、その現場現場で状況に応じて判断させていただいているところです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"きちんとした答弁を求めたいと思いますので、資料を用意してください。委員長、取り計らってください。","respondent":"つる委員長、横山品川図書館長","answer":"公共施設全体のことについては、所管がまた違うと思います。図書館に関してのことであれば、品川図書館長がお答えできると考えております。では、図書館のことだけでお答えしますと、年次年次で工事および補修に当たっているところです。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"なぜ地下の書庫の部品がないような状況まで放置されてきたのか、どういうふうにそれを見てきたのか、区民は納得しないです。そのところで、そういう経過を図書館としてはどういうふうに見ていたのか尋ねました。","respondent":"横山品川図書館長","answer":"３０年を超えた施設については改修、６０年については建てかえという原則はありますが、古い施設が多くあります。そして、結果として、部品等がなく補修がもうかなわないというところまで使っていたというふうにご理解いただければと思います。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"図書館は区の財産なのですから、区民の方にしっかり利用していただきたいということで、この大崎図書館はとりわけ利用がされていたと。だからここは閉館するしかないのだというのは、冗談ではないと区民が怒るのは当たり前だと思いますけれども、そう思いませんか。","respondent":"横山品川図書館長","answer":"考え方の違いだとは思うのですけれども、それを取りかえる場合には、施設の建てかえ規模の改修が必要になります。ご理解いただければと思います。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"今、品川区は、そういう指導を他の公共施設でも全部しているではないですか。では、なぜ図書館だけきちんとやらなかったのか尋ねました。","respondent":"横山品川図書館長","answer":"それは皆さんに使っていただきたくて大切にだましだまし施設を補修して使ってきたところです。老朽化についてはかなり進んでいる状況でございましたので、今回、このような判断をさせていただいたところです。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"ですからそれに応じた適切な維持管理は必要だし、３０年しかたっていないのに使えない、こういうことで済ますわけにはいかないではないですか。利用者の方々、図書館利用者、あるいは近隣住民、そういう皆さんにどういう説明をしてこられたのか、それについて１つ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"問い合わせに対して答えているというのは説明会にならないのではないですか。説明会だというふうに認識されて答弁されたということか尋ねました。","respondent":"横山品川図書館長","answer":"説明会という形で説明したことはございません。ただ、地域の町会長の集まりであるとか、地域を代表する方の場において、今の状況をご説明するということはしています。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"先ほども申し上げたように利用者の方々、大崎図書館を利用しておられる方々、そして近隣の住民の皆さんに説明会をしたのかということを聞いたのです。それはしていないということで先ほど答弁されたというふうに認識していいのか尋ねました。","respondent":"つる委員長","answer":"そのとおりに聞こえますが、確認しますか。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私は、やはり地域の住民が、特にこの地域は、地域の住民がつくってほしいと、しかも土地まで提供してくださっています。だからこそ、広くなっても現在地から８００メートルも先まで行かなければいけないようなところにつくっても、そういうふうには思わないか尋ねました。","respondent":"横山品川図書館長、本城教育次長","answer":"委員ご指摘のとおり、大崎の皆さんの熱い思いについては私も何度も足を運んで受け止めているところです。今度は新たに地域の方のお声もいただいて… 先ほど来、当初から経緯などを何度もご説明しているところではありますけれども、先ほどご説明させていただきました産業支援交流施設。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"長く使うために改修を行いながら、６０年間なり施設をきちんと維持しようと、そういうことでやってこられたではないですか。今後どうするのか改めて聞いたら、会員制のごく一部の人しか利用できないような施設に、そのことについて区の認識はどうなのか尋ねました。","respondent":"横山品川図書館長","answer":"１点目の説明会につきましては、先ほど来ご説明していますように、公表するようにご用意させていただいているところです。２点目のＳＨＩＰの開設につきましては、ＳＨＩＰの開設によってビジネス支援の本を動かすということはご説明させていただいておりません。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"近隣の図書館に行かなければいけない、そういう空白期間があることについてどう考えているのかについて伺います。自分たちの要求を押し通すためにそういうふうな無理を強いていただかなくてはいけなくなるということなのか、区の認識を伺いたいと思います。","respondent":"横山品川図書館長","answer":"地域の皆さんのお声につきましては、先ほどご説明しましたように町会長の会議であるとか、考え方について受け止めているところです。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ここから北品川５丁目に移転しますよ、大崎駅西口に取次所ができますよという説明、それは説明とは言わないではないですか。先ほども何回も言っているけれども、地域の要望が高まってつくった施設をなくしてしまうわけですから。","respondent":"横山品川図書館長","answer":"説明会についてなのですが、区の方針は議会のご審議を経てご了承を得た後、そのことについて皆さんにお諮りするのはこの議会だと考えています。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"ボタンを１つ、区民との関係ではかけ違えたと、そこはやはり認めていくべきだと思います。そういうふうに指摘をしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"まず確認が１点と、私も坂の多い地域だなと、こうした坂がたくさんある地域というのはより一層親しんでいただくための努力が必要だと思います。それから、分館ですから本館との間をオンラインで、分館で見られるようになっているのかということの３点をお聞きします。","respondent":"横山品川図書館長","answer":"ですのでご不便はおかけしないのですが、そういう意味での連携を他の地区館以上に、一体で運営する予定になっております。本館については館長がおりますが、分館には副館長に当たる者が施設長として赴く予定で、より連絡も強化して一体で運営する形を進めしています。","id":"exchange-025"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。その上で今、非常に借りやすい環境が生まれるのではないかと思うので、この辺のところをより工夫をしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"委員長、ほかになければ質問したいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"この地域は住民の要望がたくさんあったと、図書館がない地域だったので図書館をつくりましたと、そういう紹介もあるのです。","respondent":"横山品川図書館長","answer":"新・大崎図書館でも行いますので、こちらについては同等以上、より充実した形で子ども向けの事業を実施します。一般の図書環境につきましては、分館として図書館法上の図書館ですので、そういう意味では全く同等の機能を果たす形で予定しています。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"おはなしの部屋と児童室がどう違うのかよくわからないのですけれども、そこについてはどういうふうに維持されるのか、そこを伺いたいです。それはついていたのだけれども、今度２つに分かれたところでどのくらい確保されるのか、同等なのか、それを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"それだったら同等の機能なんて言えないではないですか。その辺を指摘をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"相当地域の方からも要望がありましたし、私どもも近い議員にしても、区長にしても相当な英断・決断があってやっと本日議案が出てきたのだと思います。当然３０年前にできた経緯もあって、今すでに議論した内容について出てきていますので、それも委員会運営上考えて運営していきましょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"それは同等の機能ということはいまだにはっきりできないという状況ですし、しかも説明会もしていないというこういう点は、やはり賛成はできないです。反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今ある施設の定員数を教えていただきたいのと、今度は６人ということなのですが、その辺が２つ目です。この病児保育の場合は、１人当たりの保育室の面積の基準はどうなっているのか、改めて説明を求めました。","respondent":"佐藤保育課長","answer":"武蔵小山の駅前に定員が、今年度４名から８名に定員を増やした医療機関がございまして、全部で今２つの医療機関で実施をしております。実施スペースですが、観察室として大体３.３平方メートル以上の施設が必要ということになっております。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"そして病児保育ですから必ずしも同じ年齢とか乳児に限らないと思うのですが、０歳から５歳までいろいろな子どもが親御さんの就労状況等によって違ってくると思うのですけれども、そういういろいろな異年齢にある中で保育士が３人に１人という考え方で配置をするということでいいのか尋ねました。","respondent":"佐藤保育課長","answer":"６０平方メートルを予定しておりますので、６人定員ですので大体１２平方メートルぐらいあるという形で施設としては十分要件を満たしております。２点目ですが、どちらかと言うと看護に近い面がありますので、児童おおむね３名に１名以上の保育士を配置しております。","id":"exchange-034"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"あるときはサポートするような、結構病児保育はトラブルが多いですから、その辺の対応というのはどういうふうにお考えなのか。病児保育施設が開設したことは、非常にいいことだと思って高く評価するのですけれども、その３点についてお伺いしたいのですけれども。","respondent":"佐藤保育課長","answer":"１点目のキャンセルの関係なのですが、どういったことができるかということを検討したいと考えているのですが、検討する素材がありません。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"私はわからないのでお尋ねしたいのですけれども、そういう契約上の、そういった開設期間の契約というのが私はわからないのでお願いします。それから、開設後の補助については今お話があったように看護師と保育士の経費というか、それは委託料で持つというイメージでよろしいか尋ねました。","respondent":"佐藤保育課長","answer":"医療機関からも１０年以上、２０年近くやりたいというお話がありましたので、適切な年数を設定して長期的に開設していただくように求めてまいります。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今回、今後も増やしていきたいということですが、具体的な方針として今の段階で言えることがあれば伺いたいと思います。現在の利用状況を教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"３施設ぐらいは必要な状況だと認識しておりますので、今後できるだけ早い時期に医師会等と連携して、病児保育を進めていこうと考えております。２点目の実績ですが、平成２８年度ベースですと２施設で大体８００人ぐらいのご利用があります。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","agenda":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方の意見も聞きながらどうしていくべきかということをしっかりと考えていくべきだったと思いますけれども、いかがでしょうかと思います。先に図書館が決まって、移転の方針を決めて補助２９号線道路の打診があったということなのか、その点についても伺いたいと思います。","respondent":"横山品川図書館長","answer":"先ほどご説明させていただきましたように区で統一したご説明ができるようにマニュアルを用意してご説明させていただいているところでもあります。２点目の、図書館部局としましては移転を決定した後に行財政改革特別委員会等で検討しております話について伺ったところです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"そして、やはりそうではなくて利用者の方々の願いはこの場所に残してほしいということですから、これは区の姿勢としてどうなのかと思います。利用者の意見を計画段階から聞いていくといったことが必要だと思いますけれども、このお考えを改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方に意見を聞いてほしいということでして、そうしなかったために今こういった反対運動、廃止しないでくれということも起きていると思います。しっかりと利用者の方に広くお知らせできる方法として、他の方法も考えてほしいと求めましたが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"地元の代表でいらっしゃる町会長・自治会長にご説明するとともに、従来行っていますカウンターでのご説明、また広報しながわ等でのＰＲであるほか。よろしくお願いします。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり現地での整備を求めているということ、現地での存続という住民の声を区として取り上げてほしいと求めました。補助２９号線道路の関係でも、実質廃館ということになっていく点もどうなのかと、ぜひそういったところを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"区は議会で都のほうから補助２９号線道路の関係の話があって、ここの表現のところをどういうふうに理解しているのでしょうかというのが１つです。協力していくという形をとりたいということはどういうことを意味しているのかということを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"区が議会で、都のほうから補助２９号線道路の関係の話があって、そういったところに協力していくという形をとりたいというふうにおっしゃった。私は、そうではないのですかと聞いているのです。","respondent":"本城教育次長","answer":"今ご指摘があった部分についてが教育部局の責任でお答えしたことではありませんので、繰り返しになりますが、私どもからの答弁は差し控えします。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"保留しなくちゃいけなくない。関係の部局の担当者をぜひ招いて、午後から調整していただいたらやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"しかも先ほどの説明には、わからないので質問したら担当ではないので答弁できないということであるのだから、この請願審査できないです。だから呼んでいただきたいというお願いを委員長にしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"補助２９号線道路の関係の話があって、区はこの打診を受け止めて協力をしていきたいという形をとりたいというふうに答弁しているのです。ですからその関係の答弁をできる方に来ていただいて、委員長として判断してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"提案","question":"しかし、さきほどの答弁は差し控えたいということなのですから、それが現時点での教育委員会の見解なのだと思うのです。ですから、それ以上のことは聞けないので、関係の担当者に来ていただく、そういう計らいをしていただきたいというお願いなのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"移転が決まれば空き地はできるわけですから、それをどうこう、答弁がございました。このまま進めていくべきだと、議案を通したのだから、必然的にこの請願の答えなんか出ているでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"ですからそこをきちんと聞いて、そうではないのだという具体的な事実を示していただければ納得するかもしれません。それがないのですから、ここに触れざるを得ないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"渡部委員","kind":"意見","question":"誰が聞いてもわかりますよね。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"私の質問は全然解明されません。渡部委員がおっしゃったけれども、その見解とは違うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"だから、同じです。協力していくという形をとりたいというのはどういうふうに区は評価をしているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"大事な図書館行政の１つである、運動があってあの図書館ができたという、他の図書館にはない経緯があります。こういう理解を私はするのですけれども、教育委員会の理解とはどういうことか尋ねました。","respondent":"本城教育次長","answer":"もともと図書館長から再三ご説明させていただきましたように、大崎図書館の移転自体につきましては、何回も説明いたしました。そういう意味で、補助２９号線道路と結びつけた移転の判断を私どもはしていないということをご答弁申し上げたところです。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"そういう問題の１つだということを理解して、やはりきちんとやってほしいと求めました。ですから、私は実現できるようにあらゆる力を尽くして頑張っていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"終了していいのですけれども、次に行く前に発言していいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"平成２６年からいろいろ始まっている中で、私どもの会派としてもこの件については地域の方々からの要望等もいただいて、そして芳水小学校の分館。何とかこれが形になってまいりまして、先ほどの議案となりましたので、この請願に関しましては本日結論を出す、そして不採択で取り扱いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"移転しなければいけない理由、そうしたものが明確に示されましたし、説明を聞いていて理解もできました。ということと同時に、今まで以上にサービスを向上させるという対策も先ほど伺いましたので、この請願に対しては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"先ほど来の質疑の中でそれぞれいろいろ質問をさせていただいたことが採択する理由ですので、改めて言いません。その理由は明確にするべき、それが付託された議員の責務だというふうに思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"松永委員","kind":"意見","question":"移転先付近にもＳＨＩＰが近くにありまして、連携や効率化を考えますと移転する必要があると結論いたしました。そのため不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのときに地域の方々の要望を踏まえ、趣旨採択という形で議会としてのそのときの委員の１人としても考えを述べさせていただきました。地域の方々の要望に対応したことで実現しているということもありますので、移転をするという形で、この請願は不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-05","title":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","agenda":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"私もこの待機児解消には保育園設置が大切だと思います。","respondent":"大澤待機児童対策担当課長","answer":"当該予定地の１キロメートル圏内において、そのうち５００メートル以内の方は４５名でありまして、保育需要としましては非常に高い地域です。川崎市として不正な請求を受けたこと、あるいは不正な疑いで調べたことはないということを確認しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"補助金の不正についてはないということですけれども、そうするとこの川崎市で補助金の不正が係争中だということは勘違いだということなのでしょうか。補助金の不正はないということを改めて伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"当事業者は川崎市内にある保育施設の元職員１名から雇用に関して訴訟が起こされておりまして、合わせて書面による説明もいただいております。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"雇用についても今保育園では大変だということですので、そういったところもしっかりと配慮してほしいと求めました。こういった住民の声もまた大切ですので、引き続き住民の方の理解を得られるように努力してほしいと求めましたけれども、いかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"具体的に次回が１０月下旬、その後隔週での実施を考えているということです。ハード面、運営面も含めて調整に努めて、地域と連携が図れるよう今後も開園後も含めまして事業者への支援・指導をしてまいります。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"もしこの保育園が開設されたとすると、地域の住民の方との関係も子どもたちの成長・発達に影響を与えると思いますので、良好な関係がつくれるように区としても力を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"こんの委員","kind":"確認","question":"幾つか今のご説明と重なる部分もあるかもしれないのですが、確認も含めてお聞きしたいと思います。区としてはどのような立ち位置で、また区としてはどういうふうに説明の場に臨み対処していくというのが本来行われるものなのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"戸別訪問や説明会など具体的な実施方法や周知範囲について法的な定めはございません。保育所の新規開設のご提案があった場合、区が事業者に対しまして、近隣環境を踏まえて説明などを行うように指導しております。","id":"exchange-065"},{"speaker":"こんの委員","kind":"質問・要望","question":"決まったルールはないといっても、いわゆるこういうふうに近隣の方から説明を求められて、事業者としての説明がきちんと住民の方へのご納得いく合意を得ていくようなことができない場合は、区としてはどのような対応をしていくのが本来、こういう場合にはどういうふうに対応していくのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"事業者が戸別訪問により実施が適当であると判断しまして、２月から４月にかけて近隣１９件を対象に３回にわたって戸別訪問をしております。","id":"exchange-066"},{"speaker":"こんの委員","kind":"質問・要望","question":"結局説明が欲しいという要望で区が間に入り、きちんと説明会が行われて同席もされたということですから、区としてはどう評価されているでしょうか。その説明の仕方なり、内容なり、住民の方が思ってらっしゃる説明というのは、区として、どうゆう評価をされているのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"当初、２回の説明会を行って事業者としては２回で説明会を終了する予定だったのですが、区のほうから継続して説明会をするように指導しております。引き続いて今後も調整するように、話し合いについては継続するように要請をしています。","id":"exchange-067"},{"speaker":"こんの委員","kind":"質問","question":"その説明会での説明の仕方等で区が口を挟むということは、例えば、その場で説明をするということはあるのでしょうか。いわゆる説明の仕方で、そこはこういうことではないですかというふうに、その説明会の中で区が説明をするという場面はあるのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"基本的には事業者が説明をする説明会ではありますけれども、例えば先ほどの区内の待機児童の状況ですとか、区が答えるべきご質問に対しましてはお答えをしております。","id":"exchange-068"},{"speaker":"こんの委員","kind":"質問・要望","question":"で業者がやはりこの地で保育園を運営させていただきたいという区民の方への説明と、やはりここは業者まかせにだけはしてはいられないというのが１点と、それに対してはいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"委員おっしゃるとおり、近隣住民の方のお気持ちも大変大切だと認識していますので、できるだけ住民の方の要望には応えられるように話はしています。これからもしていきます。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"５回ですか、そういう中でこの事業者の姿勢というのはどのような状況なのか、区としてどういうふうに評価しているのかを改めて伺いたいと思います。そのあたりの考え方も伺っておきたいのと、この際教えていただきたいと、この辺についても教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"事業者としましては近隣の方との検討会の中で妥協点を見出していきたいということを言っておりますので。それははっきりと入園の際にも入園説明会の際にも事業者が伝えておりまして、二度とこういうことがないようにということで申し上げております。","id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"あるいはオートバイということでいいのかどうか、自転車以外の車両のことを言っておられるのかを確認したいと思いました。品川区も入って、ここも含めてどのような姿勢で臨んでいこうと思っておられるのか、その辺を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"そのためにも地域に受け入れられる保育園となるように、区としましても事業者としましても丁寧に説明しなければいけないと考えています。今、説明の方法についてその方法や範囲に国も都も明確な基準は定めていないのですが、その辺のことは今後検討していきたいと考えています。","id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の考え方というのをはっきり打ち出していくことが重要なのではないかと考えていますので、その辺の意思の確認をして最後に伺います。必要性があってそういうふうにしていきたいという考え方が表明されたわけですから、どういう内容かというのを一定お聞かせほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"まだ具体的には検討してございませんけれども、説明会として開催をしてほしいという要望があった場合は、まだ検討段階ではあります。そして、近隣の方に理解を得ることですが、これは最大限、区としましても努力を続けてまいります。","id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"区がご近所の皆さんへの説明会によるアプローチというか、それについて本当にそこが一番基本だと思うのですよね。しっかりと理解していただけるような姿勢で、まず第一線に立ってやっていただきたいということと合わせて要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"陳情要旨の１番、２番、３番についての説明をいただきまして、そういう状況なのかということでわかりました。南委員やこんの委員の質問を聞いていましたので、説明会をこういうふうにやって検討会も行うという話を伺いますと、通常はどうなのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"説明会の回数としては、今まで区内で私が知る限り一番多かったのは５回です。この件に関しましては今後も継続していく形ということですので、恐らく最高回数になるのではないかと考えています。","id":"exchange-074"},{"speaker":"渡部委員","kind":"質問・要望","question":"やはり近隣の地域の方々に愛される施設になってほしいというものであるから、では、そうしたら全て要望を聞いていかなければいけないのかと言ったら。２、３でいただいた部分に関しましては、そちらのほうで審査をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"この陳情の要旨につきましては都が認可主体であるということと、キッズ・スマイル・プロジェクトの適格性については承知をいたしました。３番に関しましても今の状況等も伺いましたし、毎回の課題となることかもしれませんけれども、今回の陳情に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"こんの委員","kind":"確認","question":"先ほども確認をさせていただきましたけれども、それから事業者としても住民の方との妥協点もその中で見出しているという姿勢も確認ができました。これについては差し止めてほしいというところでは、なかなか難しいのかなという、一方でそういうことも感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは事業者、ご近所のみなさんに理解していただけるようにさらなる努力をしていただきたいということを意見として付していきたいと思っています。態度としては、陳情者の皆さんには申しわけないとは思うのですけれども、不採択というふうにしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"松永委員","kind":"意見","question":"不採択でお願いいたします。３番に関しても今後説明会を丁寧に行っていくということもありましたことを踏まえ、私たちの会派は、今回の陳情に関しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３番についてはこれまでも区がかかわってきたということは理解しましたが、最大限努力していくというような今後の方向もお話しされていました。今後もやはりこういった問題では調整、ぜひとも先ほどお話があったような意気込みで相互の理解を得てよりよい関係に努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-06","title":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","agenda":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","exchanges":[{"speaker":"南委員","kind":"確認","question":"ですから、区としては先ほど答弁されたような足りているという認識にいるわけですから、改めて確認したいのです。平成２７年度には３万８,０００円で、平成２９年度にはいろいろプラスされてそれを超える額となっているのですが、その辺の認識はいかがか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"平成２９年度、今の年度途中でも突然足りなくなって困ったというようなこともございませんので、一定確保ができていると理解しております。","id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、５対１で基準どおりだからいいということにはならないわけです。基準だからいいのだというふうには、５対１としているからいいという認識でいらっしゃるのかどうか、ここについても伺いたいと思います。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"宿舎借り上げ支援につきましては品川区はかなり柔軟に対応しておりますので、こちらの活用が増えていくような状況です。経験年数による加算を加えない７万４,０００円でも７割以上は格差が縮まっていると考えてよろしいのではないかと… １歳児が５対１の割合で、それ以外は国基準で言いますと、公立保育園で言いますと大体４６２名ぐらいの保育士が必要になります。","id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"一般企業からやはり一定の割合での格差があるという事実はあるわけですから、品川区は特に今、私立保育園を多く開設するようにしているわけですから。子どもにとっても保育園に喜んで来てもらう、登園してもらって安心して育っていただくという条件整備は欠かせない最低限の条件ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"こんの委員","kind":"質問","question":"そうするとどのように捉えていますかとお聞きしたいのですけれども、報道されているほどの実感がないのが現状です。それはどのように、いわゆる、これだけ区としてはしているけれども実感がないということについて区としてどのように捉えていらっしゃいますか。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月に区内で開設する事業者で今もう募集を始めている事業者の初任給の平均が２１万６,０００円で、平成２８年から比べると２万１,０００円上がっておりますので、それなりの成果が出ていると認識しています。","id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"は２番は既にもう５対１になっているということですので、私立保育園などは運営してくださっているという理解でいいのでしょうか。ここの陳情の内容とは違いますが、もう区としてはきちんと手当てをされているということか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"給与額など改善された額について個人別に調査をかけまして今集計中ですので、その集計が出ましたらまた改めてご報告させていただきたいと思います。全事業者がそれでやっていただいております。","id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"引き続きお願いをして、ここに書かれている保育の生活の中での１歳児の動きというのも想像できますので、合わせてその点もお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"都の補助金により３万８,０００円アップしたところからどういう形で７万４,０００円になっているのかというところをご説明ほしいと求めました。小規模ですとか認証の配置というのも５対１ということになっているのか、そのあたりもお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"小規模の保育士の配置基準は１・２歳児に対しておおむね６人に１人で、園としてプラス１名というのが配置基準になっています。認可とは保育士の配置の計算方法が違います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"都や国にも求めてほしいと求めましたし、区独自でもやっていただきたいと思うのですけれども、伺いたいと思います。次の報告を待ちたいとは思いますけれども、この調査の中には認証や小規模も入っているのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"調査につきましては認可、小規模、認証の全園を対象に実施しております。認証の配置につきましては、認証保育所そのものは東京都の施策ですので、区として配置基準を変えるというのは今のところ考えてはおりません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"それは制度上もできないということになるのですか。これは都が担当という話ですが、何か工夫してできるという余地はあるのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"認証の配置基準について区で制度変更できるかどうか、今わかりませんけれども、恐らくできないと考えております。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"認可、認証での保育の格差と言いましょうか、差が出てきているということになると思うのです。認証についてもぜひ引き上げていくというところを考えて検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"渡部委員","kind":"意見","question":"結論を出します。２番は品川区は５対１でもうずっとやってきていますから、もうこれで十分かどうかは別問題としまして、今回の陳情に対しては不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問・要望","question":"１番はきちんと処遇改善、それに対して職員の方にどのようにお金が流れているのかのチェックもきちんとしてくださっていることがわかりました。２番はもう既にされているということですので、残念ながらこのご要望は全て区としてはかなえているということの理解でありますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"それから２番の人員の配置基準なのですけれども、５対１は都基準なのですけれども、やはり最低基準を見てもっと引き上げは必要です。したがって、これらの陳情内容については支持できる内容だと思いますので、採択をしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"松永委員","kind":"意見","question":"１番に関しては区独自の賃金加算ということでキャリアアップや宿舎借り上げなどの対策を行っているというところです。２番に関しても６対１から引き上げてくださいということで、今品川区では５対１で行っているということで、そうした理由から不採択をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１番はさまざまな賃金加算などをされていることも伺いました。２番のほうは５対１でされているということで、了解をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"待機児ゼロに平成３０年度４月でなる見通しができつつあるというお話だったので、それについて具体的に教えてほしいと求めました。認可保育園が何園できて、他のものについてもどのくらいできて、需要見込みが幾つでどのようになりますというところを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/154236?Template=document&Id=4922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":64492,"voices":301}},{"id":"h29-20170925-5","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"総務委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"視察","agenda":"視察","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ここの校庭は人工芝ではないのですか。最近人工芝の張り替えとかがあるのでどうなのかと思ったので、その辺を説明を求めました。","respondent":"小林施設整備課長","answer":"躯体だけでいくと２割か３割かそこら辺、すみません、今の時点でお答えできるのはその程度あります。今検討中です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１点、工事の時にそういった水質の部分まで管理をされているのかどうか、そこを聞かせていただきたいのが１点です。今日伺ったら、くれぐれも注意をして走らせていただきたいと思うのですが、いかがか尋ねました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"プールの水質に関しては、当然最新のものにして、一番メンテナンスのかからないものにするなど工夫して採用しております。それと３点目の児童の動線ですが、工事中はそういうラップをなるべく避けて計画をしておりますので… 特別支援教室ですけれども、３階に普通教室が並んでいるところの中で１教室使うという形になります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５ページの給排水設備工事のところに「太陽熱利用設備」とありますが、こういったものは普通に設置されるものなのかどうか。ぜひ新しい施設に関してはエコを重視して取り組んでいただきたいと思うのですが、ちょっと具体的に説明を求めました。","respondent":"小林施設整備課長","answer":"太陽光につきましては、今のは電気のほうなのですけれども、これは屋上に１０キロワット程度の発電能力のソーラーパネルを設置する予定です。これも屋上に設置します。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までもどこかで設置されていたのかどうか、費用がどのくらいかかるのか、わかったら教えてほしいと求めました。給食の調理室も地下１階というところではいろいろ配慮が必要かと思うので、その辺がどのように対策がとられているのか、説明を求めました。","respondent":"小林施設整備課長","answer":"それとあと、非常用発電を今回この城南小学校でも設置をしますので、７２時間の稼働に耐えられる燃料も保管をします。もぐっているところの部分については、そこを空調を通して空気の入れ替えをするというようなことをしております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"温水にしてほしいという希望もあるので、やはりそういうよいところはぜひほかにも活かしてほしいと思ってちょっとお聞きしました。アリーナのところは、やはり特段の給排気の考えを持っていていただきたいと思うので、これはお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"そして、今日、視察現場で埋蔵文化財発掘をやっていましたが、あの費用というのは別の課から出ているでしょうか。その辺をちょっと説明を求めました。","respondent":"篠田学校計画担当課長","answer":"は総工事費に関してのご質問ですけれども、今回建築費が約４９億円となっています。それから、埋蔵文化財の経費ですけれども、こちらは教育委員会の予算のほうで実施しているものです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと見解をお聞きしたいのですけれども、この間ちょっと中学生に聞いたら、私立は体育館にエアコンがついている。やはりエアコンは、あくまで今後も区としては導入をしない方向で行くのでしょうか、説明を求めました。","respondent":"篠田学校計画担当課長","answer":"私どものほうも検討しているところではありますけれども、学校の体育館の施設に関しましては空調設備等、導入をするという形にはなってございません。ですので、今後状況に応じまして、場合によってはそういう対応をとれるようにということで、今行っているところです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区はやはり教育が本当に進んで先端を行っていると思うのですが、やはりこういう子どもたちのことを考えて、また地域の人のことを考えて、やはりそれなりの準備、また設備というのを整えていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日、その方針は次の計画でも続けるというようなことを伺ったのですけれども、その辺についてはいかがなのでしょうかというのが１つです。私の図面の読み方が悪いのか、どのように避難経路を想定されての設計なのか、その辺について説明を求めました。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"１点目の雨水利用ですけれども、これは外構のほうで雨水タンクを設ける予定で計画をしております。今のご質問の雨水利用というのも一つの手だと思います。 それから一番左のほうの校長室、２階の図面見ていただくと職員室からおりていくような階段があります。こちらのほうと、あとは通常の昇降口とありますので、３方向で外に出られるような形での設計となっています。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"さっき伺えばよかったのですけれども、その辺はこの図面からはちょっと読み取れないのですけれども、工夫はされているのか伺いたいと思います。","respondent":"小林施設整備課長","answer":"それを見ても当然わかりません。１階だとか昇降口だとかいうところにパネルで、どのくらい消費していますよというような装置・パネルを設置して、見える化を図っております。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いつも議会から要望しても、「いや、設置をしないのです」というような話ですけれども、何をそれほど拒んでいるのかなと。もう時代がこういう時代の中で、地域の方たちも、特に災害時のことも心配をしてそういうような要望を常に出されているのかなと思うのですけれども。","respondent":"篠田学校計画担当課長、小林施設整備課長","answer":"仮にお子さん方が増えても、多目的室ですとか、そういった様々な形の部屋を転用して教室等に対応することを考えてありますので。今のところ建設段階では設置はしていないといったことで、それに対応できるような形で… ちょっと補足します。今の備蓄倉庫なのですけれども、地下１階に約４０m2ほどの倉庫を現在計画しております。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"提案","question":"災害時に言われているのが１つは冷暖房の件ですけれども、以前にも提案をしていますけれども、よりよいものをつくってほしいと求めました。これは要望で終わりますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"先ほど確認すればよかったのですけれども、先ほど城南小学校のあたりは地下で水が出るとおっしゃっていたかと思います。一応の対策はしても、実際稼働させてみると何か結構かびの被害が出たりということを私自身も経験していますので、その辺どうなのか説明を求めました。","respondent":"小林施設整備課長","answer":"水位が高いのですけれども、当然設計の中ではその止水だとか防水だとか断熱だとか、そういうのを含めて計画をしております。それを循環させて、湿気をなるべく外に持っていくというような空調をつけたりだとかして、検討して設計を今回進めたところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"特別支援教室なので、この横長のずらっと教室が並んでいる動線の中で、できるだけ真ん中にしてほしいという希望が結構出ているのです。だから、もうこの段階なのですけれども、その辺が具体化されているのかどうか、１点お伺いします。","respondent":"篠田学校計画担当課長","answer":"特別支援教室に関しましては、まず教室の仕様は普通教室と同じものという形で考えてあります。ただ、これは学校運営上、実際に建物が開設されてから改めて整備をするのですけれども、基本的な考え方はそういった形で運営されることと考えます。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"もう一点、車椅子利用の児童の方のためのルートはどうなのかなという説明をしてください。エレベーターはあるのですけれども、その辺のバリアフリーの考え方を説明を求めました。","respondent":"篠田学校計画担当課長","answer":"一般のお子様に関しましては正門を入ってから階段を上がって２階の昇降口という形になりますけれども、その昇降口がある２階のバルコニーといったところがあるのですけれども、そこからエレベーターで上に上がれるような形での位置づけとなっています。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"８ページの躯体工事の改築工事のほうの入札なのですけれども、これは一般競争入札で３者で入札で、２者が辞退をして１者のみということ。１者入札になっているということについての区の見解と、１４ページのほうの給排水衛生設備工事のほうですけれども、この無効の理由を説明を求めました。","respondent":"立川経理課長","answer":"辞退理由ですけれども、１者が都合によるということでございまして、もう一者が予定価格を超過しているです。現在、オリンピック・パラリンピックが２０２０年に開催されるということがあって、区としては大変ありがたいと考えています。","id":"exchange-016"}]},{"id":"topic-02","title":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","agenda":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そういう意味で、駐車スペースというのはもう少し何か工夫できないのかと思うことがあるのですが、いかがでしょうか。ちょっとご見解を説明を求めました。","respondent":"溝口公園課長","answer":"そういった中で駐車場ですが、やはりこれだけの運動施設を維持しながら、新たに駐車場を整備していくというのはなかなか難しいのが現状です。自転車等を使っていただくなど、そういったことをしていく中で、皆さんに快適にご利用していただけるようにしていきたいと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"あそこはなかなかいい場所で、お子さんたち、家族連れが散策するというところで、天王洲が日曜祭日などなかなか賑わっているような状況になってまことにうれしい限りなので、何かいい方法がありましたら、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"この間、区の施設ではないのですが、人工芝にしたらとても上が暑いと。そういう選択肢があるのかどうか、どのくらいのランクのものを選んでいるのかというあたりを、わかったら説明を求めました。","respondent":"溝口公園課長","answer":"いろいろな人工芝の種類がありまして、芝生の長いものから短いもの、そういったものによっていろいろ変わってくるものと考えています。使用実績におきましては神宮球場とか、皆さんにスポーツを楽しんでいただく施設にしていきたいと考えているところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今、老朽化に伴いというようなことでしたが、今までの人工芝よりもグレードを上げたと理解してよろしいのでしょうか。どれぐらいでまた張り替えの必要性が出てくると考えられたのか、その辺の見込み、計画があれば伺いたいと思います。","respondent":"溝口公園課長","answer":"人工芝が設置されてから１５年以上経過しているということで、使い方によってもいろいろ耐用年数は変わってくると考えております。ですけれども、今回も大体同じような１５年、または２０年ぐらいは使えるような形の人工芝を選んで、今回施工するものです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"もう１個、この透水性ＩＬＢ舗装が２７m2と、図面で見るとここだけということなのですが、これはどういうもので、どういう目的でこういう舗装をここだけするのか説明を求めました。","respondent":"溝口公園課長","answer":"ベンチ等そういったものを今回新たにスタンドベンチを設置するところも出てきている現状ですので、それを復旧するところだけをＩＬＢ舗装として直すということで、必要最小限のところだけを施工するという形での工事を予定しています。","id":"exchange-021"}]},{"id":"topic-03","title":"第７０号議案 書架・カウンター等の買入れ","agenda":"第７０号議案 書架・カウンター等の買入れ","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"カウンターは大体イメージがわくのですけれども、どの程度の規模か書架について教えていただきたいのが１点です。芳水小学校の分館についてはここに含まれているのか、いないのか、説明を求めました。","respondent":"立川経理課長","answer":"書架について説明いたします。続きまして、分館につきましてはまた別途提案するのですけれども、今回は新大崎図書館に関連する書架・カウンター等に限定されるものです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっとイメージがわかないので、既存のところでいうとこの程度という規模があったら教えてほしいのです。特別な新しいタイプの書架ではないということなのか尋ねました。","respondent":"立川経理課長","answer":"イメージとしましては、１フロア１,５００m2、そうした中に書架を配置していくです。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"２７ページのところで、そちらのほうが利用しやすいのだったらそちらを選んでいたのかどうか、その辺をちょっと詳しく教えていただけますか。","respondent":"立川経理課長","answer":"いわゆる新しい図書館のレイアウトに合わせて、もう既に製品を選定した上で棚割りというのを確定します。ですから、入札に際しましては全てメーカーとかを特定した段階で、それで金額勝負してもらうです。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜなら、大崎図書館を現地でそのまま残してほしい。北品川の地域に新しい保育園を求める意見がたくさんあるのと、充実をするといった意味で、この議案に対して賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"吉田委員","kind":"意見","question":"大崎図書館の移転については手続き的にそもそももう少ししっかり地域の人たちの意見を聞いて、手順を踏むべきだということで、疑問を持っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人件費についてなのですけれども、様々な職種の方がかかわっているわけですけれども、この積算をしていく段階で、最低賃金のところがきちんと保証されているといった根拠というのは、区はどのように把握をされているのか、１点教えてほしいと求めました。","respondent":"立川経理課長","answer":"予定価格を算出するに際しましては、国が示します設計労務単価の最新のものをまず確認いたします。予定価格につきましては、国・都が示しました労務単価に沿って適正な価格ということで決まっているところです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"確認","question":"当然のことと思うのですが、そこの根拠はそうなのですが、区としてどこの段階でその辺がきちんと価格を積算するところで使われているか。そこのチェックというのは、区も同じことをやって確認して正しいと評価をするのか、そこのところを説明を求めました。","respondent":"立川経理課長","answer":"入札に際しましては、いわゆる積算の内訳というものを出していただいておりますので、当然その辺をチェックしまして、いわゆる労働者の賃金、下請けの支払いにつきまして適正であるかどうかというのを事前にチェックしています。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"そこで、１つここに書かれている会社が直接する部分ではなくて、一次、二次、三次とか下請けに出す場合の最低保証のところは、どこでどう把握するのかも説明を求めました。","respondent":"立川経理課長","answer":"下請けがある契約につきましては、いわゆる工事全体の施工体制台帳というものを出していただきまして、そこでそれぞれ下請契約の金額等をこちらに提出していただいておりますので、当然その積算についてもチェックしています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"きちんと行っているかどうかというチェックを、やはり事業者任せではなくて区のほうでしていただくような仕組みにしてほしいと思っています。一般区民の方の貸し出しの利用料というのは、どこと比較して決められているのかわからなかったので、わかったら説明を求めました。","respondent":"立川経理課長、松山高齢者地域支援課長","answer":"そこについては事業者のほうに働きかけをまた強めていっているところです。契約制度の中でどういった工夫ができるのか、そういうことにつきましては当然研究していかなくてはいけない課題と考えております。 委員お尋ねの一般区民の利用料についてですが、こちらの施設の位置づけについて、今検討を図っているところですので、また利用料につきましては、決定次第お示しさせていただこうと考えています。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"何か非常に違和感を覚えるのですが、これはどういうふうに我々などが理解すればいいのでしょうか。全く同じ額もあるというのは何か不思議な気がするのですが、これに対して我々はどのように思ったらいいのか尋ねました。","respondent":"立川経理課長","answer":"入札金額につきましてはご覧のとおりです。接近している理由ですけれども、そうした積算に使うソフトが同じだった場合には、同じ金額になることもあり得るのかなと考えているところです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"以前も聞いたことがあるのですが、区としてはこの予定価格を出すにあたって、どのように積算して、入札予定価格を決めているのですか。ちょっとそれだけ説明を求めました。","respondent":"立川経理課長","answer":"予定価格につきましては設計事務所が設計をして、そこで金額をある程度出しています。","id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"最後に１点だけ。資本金がかなり違っても同じだというのは、一般の区民から見ても非常に違和感を覚えますので、それだけちょっと一言言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"この図面で、私たちはいろいろな場面でユニバーサルベッドを求めているのですけれども、そういう設備があるのかどうかということが１つです。２階からの非常口というのは、１階の非常口が、どこから出るのか教えてほしいと求めました。","respondent":"小林施設整備課長","answer":"だれでもトイレの備品関係のお話ですけれども、ここについては委員のおっしゃった多目的シートについては設置をする予定です。ほかにオストメイト、洗面所、あとベビーチェア等を設置する予定です。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"では、１階のテラスはそこから出られる窓ということですよね。一般的に掃出し窓というか、そういう感じに理解してよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"はい、そのとおりです。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"確認","question":"すみません。６ページの図面を見ますと、これはソーラーパネルなのかどうか、確認させてください。","respondent":"小林施設整備課長","answer":"別途電気工事の中で、屋上にソーラーパネルの設置を予定しております。","id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、これ、ソーラーパネルは建物の中のどの部分にソーラーパネルによる電気供給をするのか。わかる範囲で結構ですので説明を求めました。","respondent":"小林施設整備課長","answer":"通常ソーラーパネルを設置しますと、電気照明の補助等に使っておるところが一般的です。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"毎年このように意見書を出していますけれども、何とか恒久的になるような方向がとれればいいと思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"平成１４年度、区の認識はどうなのかというところをちょっと、区のその辺の認識をひとつお伺いしたいです。","respondent":"伊東税務課長","answer":"マクロ経済の認識ですけれども、先日１月とか４月時点の調査によりますと、地価のほうは若干上昇傾向にあるというような調査結果があります。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に中小、小規模の事業者の方々には本当に厳しい中頑張っていただきたいというところにおいては、この願いを届ける機会ではあるのかと受けとめました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"漠然としているので、職場によって多い順に１位から５位ぐらいまで、職場とどのくらいの人数がいらっしゃるのか教えてほしいと求めました。やはりこの辺がわからないので、ぜひお願いいたします。","respondent":"黒田人事課長","answer":"教育ですと教育支援相談員が２４名ですとか、学校の専科の指導員が３５名など、そのようなところが多いです。それからあと、清掃事務所の資源回収監視員とか清掃リサイクル指導員を合わせて３６名おりますけれども、こういったところが多い職場となっています。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれの職場はわかったのですが、職種はどのような職種なのか尋ねました。","respondent":"黒田人事課長","answer":"専門職員のほうは５５の職種がございまして、無資格者という形に分けてございまして、非常勤の職として１３ほどあります。保育士資格を持っていなくても補助という形で、無資格者ということで非常勤として雇用している場合もあります。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"正規職員とほとんど同じ仕事をしていて、均等待遇の対象者になってよい立場の人は何％ぐらいいるのですか。専門非常勤は１,４００円、一般非常勤が１,１４０円で、１０年間据え置きでいる理由がわからないのですが、その理由を説明を求めました。","respondent":"黒田人事課長","answer":"職によっては３時間ということもございまして、基本的な認識として、一般職員と全く同じ勤務というものはございません。３類で１,１０７円ということありますので、説明の中で申し上げましたが、報酬の水準については適正であると認識しているものです。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"正規職員と非正規職員が決定的に違うのはどの辺か教えていただきたいのと、例えば今回最低１,５００円以上にすることを求めると書かれているのですが、そのところも説明を求めました。","respondent":"黒田人事課長","answer":"いわゆる時間には換算できない仕事も担っているという意味では、同じ労働条件というのはなかなか比較は難しかろうと考えているものであります。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"なかなか仕事の中身が時間では言えないという、それは専門的なところを担っている正規職員ならではのところは当然あると思うのですが、正規職員と大体同じぐらいの時間数を働いている方々は、この１,３００人のうちどのくらいいらっしゃるのか尋ねました。","respondent":"黒田人事課長","answer":"先ほどの答弁を少し繰り返しますが、同じぐらい働いている方はいないというものです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２０１６年の正規職員のところで、東京都の春闘共闘キャラバンで自治体に求めた数字を集約している報告書、２０１６年正規職員数２,５６３人。お伺いすると、やはり還元をするべきであると思うのですが、その辺はいかがか尋ねました。","respondent":"黒田人事課長","answer":"プラス３１人ということで、当然人件費の部分が変わってまいりますので、そこで下がってくるということはあろうかと思います。今、経験を若い職員に伝えるということもしていますので、そういった中で正規職員と非常勤職員の役割分担で業務を担っていると認識しているものです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"退職者と新規の差はどうなのですか。退職した分、採用がされているのかどうかというのを私は今ここで述べたので、比較するのだったら同じように比較してください。","respondent":"黒田人事課長","answer":"退職の人数につきましては手元に数字がございませんが、基本的には事務事業見直しをしまして、そこに必要な人数を採用しているですし、そういった中でいろいろ工夫を図って事業を執行しているというものです。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"ちょっと自分で知識が足りないものですから、今のご説明に加えて伺いたいのですけれども、請願の中に学校事務非常勤職員というのも出ています。学校事務非常勤職員というのはどういう仕事で、どれぐらいいらっしゃるのか教えていただけますか。","respondent":"黒田人事課長","answer":"いわゆる学校事務につきましては、いわゆる都の職員が学校事務でおりますので、区の関係につきましては非常勤職員を置いて、学校のそういった事務を行うということで、平成２９年４月１日現在で５２名ほどいらっしゃいます。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"どう聞けばいいですかね。例えば５年以上継続している人とか、そういうのがわかりますか。","respondent":"黒田人事課長","answer":"基本的に任用は１年ごとですので、繰り返し任用しているというところについては把握してございませんので、お尋ねの件についてはちょっとこちらでは承知していないです。","id":"exchange-049"},{"speaker":"須貝委員","kind":"質問・要望","question":"この最低賃金は、地域別に賃金改定しているわけですから、区内で働く非常勤職員の方の最低賃金も私は自然と上がってくると思います。ですが、やはり非常勤職員の方も少し我慢をしていただいて、民間がその賃金を出せるような時期まで辛抱していただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ副委員長","kind":"質問","question":"それと、常勤の方の給与も時間で割り返してみると、この非常勤の方たちとそんなに変わりはないということ、それはよくわかりました。具体的にはそれはどういう背景で、平成３２年度とおっしゃっていましたけれども、もう少しわかりやすくお願いします。","respondent":"黒田人事課長","answer":"この法律は本年５月１２日に公布されまして、地方公共団体における行政需要の多様化等に対応して、法改正したです。この辺につきましては、説明の中でも申し上げましたが、現在２３区全体で検討を進めているというものです。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"すみません、もう一点だけ。専門非常勤職員の内容をわかりやすく教えてほしいのと、フルで１週間は働けないけれども、この低賃金で使うというあたりも聞かせてください。","respondent":"黒田人事課長","answer":"あくまで専門非常勤職員につきましては職を規定してございまして、先ほど申し上げましたように５５の職務があります。報酬額につきましては、その職の専門性が高い者については報酬額の設定も違いますので、そういった中で職種に応じて設定しているというものです。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"戸籍のところと税務のところだけだったのですが、もうちょっと区民と接点のあるところはどのようなものがあるのか教えていただきたいです。そういうことだと、この１,４００円が妥当であるとお考えでしょうか、お尋ねします。","respondent":"黒田人事課長","answer":"介護認定調査員も専門非常勤職員ということでございまして、様々な職場で専門性があるものについて職を設定しているものです。１類の職員の初任給を時間で割り返しますと大体１,３８０円ですので、１,４００円という報酬の設定については適正であると考えています。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"時間に直すと適正ということですが、様々な待遇の面で大きな差がある中で、この時給だけ比較して妥当であるというのは、私は違うと思います。この賃金が非常に安いという訴えが届いていますので、このことはしっかりお伝えをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"先ほど聞き忘れました。一般非常勤は１,１４０円が最低額とお聞きしたのですが、１,１４０円というのは最低ということだと思ったのですが、その辺はいかがか尋ねました。","respondent":"黒田人事課長","answer":"例えば１,５００円の設定をしていますし、これはちょっと勤務日数から割り返していますので少し端数が出ますが２,６１５円ということで、それぞれその職に応じて設定しているというものです。","id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"意見","question":"結論を出すでお願いします。平成３２年４月から新しく改正された法律が施行されるということで、今回の請願については不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私も勉強したことがありますが、先ほどの議論の中であったとおり、なかなか難しい問題をはらんでいるということがあります。どこまで反映されるかというところで、反映をしていただきたいということを望みまして、この請願に関しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大事な区政を支えてくださっている非正規職員の待遇改善、均等待遇というところをもう少しきちんと実態を調べて検討していただきたいと思うのが１点。賃金、時給ですから、妥当な金額であると思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（し）委員","kind":"意見","question":"それと、給与体系等については法改正があったのと、それに伴って区としても検討をされていくということ。正規職員の給与がマイナス改定をされている時に、我々としては今回のこの請願に関しては不採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"須貝委員","kind":"意見","question":"結論を出すということと、先ほど申し上げましたが、東京都内の最低賃金が今度時給９５８円に改定されます。おのずと品川区で働いている非常勤職員の方の賃金も上がってくると思いますので、それまでは我慢をしてほしいということで、今回は不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"この趣旨はとても理解するのですが、今売り手市場というのでしょうか、労働者のほうが足りないという中では大変厳しい状況があるのも実態なのです。なので、最低賃金を１,５００円というこの金額がちょっと厳しいかなと思っておりまして、趣旨採択ということで主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858885?Template=document&Id=2086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":41488,"voices":223}},{"id":"h29-20170926-6","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"区民委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"人数について把握しているのかを伺いたいのですが、それと公益財団法人品川区スポーツ協会、それぞれ品川区からの天下りは現在何人在籍しているのか。人数を伺いたいと思います。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"区のＯＢ職員という捉え方ですけれども、１名です。 文化振興事業団につきましては、ご質問にあった管理職ということで言えば、４名です。 スポーツ協会におきましては、区のＯＢ職員ということに関しましては、８人です。管理するところでは、非常勤、常勤含めての数字です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ１人、４人、８人と、管理職のＯＢということでよろしいのでしょうか、確認させていただきたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"大変申し訳ございません、管理職ですと、２人です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"私は、区民の理解も得られないし、やめるべきだと思うのですけれども、その点いかがでしょうか。２つの部と３つの課に分かれているので、誰にまとめてその考えを聞いたらいいのか聞きにくいので、３つの課それぞれに伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、例えば公益財団法人は公益性が高く、独立性も高い。そこもご説明ほしいと求めました。","respondent":"安藤文化スポーツ振興部長、堀越地域振興部長","answer":"決算もそうです。しっかりコンプライアンスと申しましょうか、法令順守のもとに運営しているということで、それで問題ないと考えています。 私どもで何かルール化等について答える立場にはございませんので、評議員会等を経て、しっかりとチェックを果たして運営されているです。そういった意味で、適切かつ公正に運営されていると認識しています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"年間の決算と予算についての中身であって、そこは少し違うのではないのかなと思いますので、改めてお伺いしたいと思います。いずれにしても、チェックする側とされる側が、このような関係を続けているというのは問題だと思いますので、この点は改善を要望したいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"理事会の理事については、評議員が決定するという決まりになっています。それと、決算と人事の理事のほうです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"それならば、業務の１つなのですから(6)として書けばいいではないですか。それと、スポーツ協会も書いていないから、その他区長が必要と認めた業務は入っていないのですかという質問。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"例えば創業支援の支援メニューで、あるいは同時に、武蔵小山創業支援センターでは女性の創業支援などに取り組んでおりますので。… 政策等と連携するような場合には、その他区長が必要と認めた業務ということで、連携の業務をお願いする場合があるので入っております。… 指定管理業務の概要としましては、区と連携した形でやることはありますけれども、こちらの総括にはそういった形で載せていないということです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"それと、地域振興部長にお伺いしたいのですけれども、あえて伺いますが、ビジネスクラブの利用率はすばらしいではないですか。その施策に対する利用率の評価を部長としてはどう考えているのか、その辺についてお伺いさせてください。","respondent":"池田スポーツ推進課長、堀越地域振興部長","answer":"平成２８年度につきましては、かけっこ教室や子ども向けの教室などいろいろなことをやっておりまして、事業自体は区民の方に喜んでいただける形でどんどん増えている状況です。 ですので、まとめますと２点あって、貸しホールとしての評価は非常に高いということ。区からもしっかりと申すことは申して、かつ連携するところは連携してやっていきたいと思っているところです。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"あえて部長に伺ったのは、部長はいろいろな課の部長ですから、利用率の数字が区民に評価されている。もう一つ新しく質問をするならば、今日の本題とは違うかもしれないけれども、どう考えていくのかということを答弁していただければ幸いです。","respondent":"堀越地域振興部長","answer":"答えになっていないかもしれないのですけれども、きゅりあんもそうですけれども、基本的にはこれは非常にいい結果が出ていると思ってあります。","id":"exchange-008"},{"speaker":"塚本副委員長","kind":"確認","question":"予算額が余りましたということで、これは平成２８年度だけではなくて、平成２７年度や平成２６年度もそうだったのか。平成２８年度になって、そういうことに至ったということなのかということを最初に確認したいです。","respondent":"鈴木文化観光課長","answer":"基本的には、毎年少し余裕が出た場合には、返還というのは継続しております。すみません、今、手元に資料がないので具体的な額はお答えできませんが、毎年度、余裕が出た場合には返還ということでお願いしています。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"意見","question":"それに対して、指定管理料の返還になるのか、あるいは利用料を下げるという考え方も、運営の中ではあるのではないかと思うのです。利用料を下げるのか、指定管理料を返すのか、使用料に対して下げていこうみたいな考え方は出てくる部分はどう考えておられるのかお願いいたしますとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"これは最初に提案いただいたときに、予定する５年間の毎年の指定管理料の提案をいただいておりますので、基本的にはその額になります。それから、単年度で利潤が出たのでそれを使用料を下げるところに還付するという仕組みにはなっていないところです。","id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"このようにいろいろしている中で、なぜお神輿の写真を使ったのかをお伺いします。それと民泊について１点、生活安全担当課長にお伺いしたいのですけれども、全てがよしという形ではないと思うのです。","respondent":"鈴木文化観光課長、菅生活安全担当課長","answer":"年１２回の予定の半分を実施しているのですが、最初の写真の３回で、五千件程度。１万から１万２,０００件のアクセスをいただいたということで、その中で特に注目度の高かったお祭りの写真を載せさせていただいたです。委員ご指摘のとおり、企図している者が実際に民泊に泊まることも想定されておりますので、そういった問題があるのかなと考えております。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう一点は、あえて生活安全担当課長にお伺いして、このような課題がありますということを何点か答弁していただいたのです。それを伺って、課長はどのように思われるか。","respondent":"鈴木文化観光課長","answer":"先ほど口頭でご説明しましたように、９月８日に国の連絡会議がございまして、課題への対応についてもある程度の方向性は示されております。都への要請なり、意見調整も含めて、しっかりと対応したいと考えております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"伺いたいのは、同性同士のダブルルームを拒否しないということを確認しているのかどうか、そこを伺いたいと思います。品川区内の４８施設は、同性同士のダブルルームは拒否しない、ウェルカムだということを確認しているのかどうかご質問したいと思います。","respondent":"鈴木文化観光課長","answer":"先ほどご報告した区内施設の状況です。観光振興協議会と国の調査の中で把握した情報でございまして、ご質問のＬＧＢＴ等の対応の可否については、これまでまだ調査をしておりません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"こういうことになっていますよ、拒否してはいけませんよということをお伝えすることが必要ではないかと思うのですけれども、お伺いしたいと思います。品川区としてこのような事業を進めていくわけですから、２点、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"旅館業法に違反ということが判例的に確定しているわけではございませんが、考え方として、やはり対応が必要ということは区も理解しております。皆様からも意見をいただきながら、今後、区内でしっかりとした対応ができるように情報共有や対応を検討したいと考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひいろいろ取組みを進めていただきたいと思うのですが、１点だけ。先ほどの答弁ではその辺がはっきりしなかったので、その点だけ確認させてください。","respondent":"鈴木文化観光課長","answer":"区でも人権を担当する所管がありますので、そこから正式に区でこのようにと言うのは、私の範囲ではないのです。ただ考え方としては、委員もおっしゃったように、そのことだけでの拒否というのは適切ではないと区でも認識しているという意味で申し上げました。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"旅館業法を取り扱う課ともよく確認、そこは確認してほしいと求めました、これは要望です。規制緩和ではなく、しっかりした安全ルールの確立が必要だと思っているのですけれども、その点についても区の問題意識をお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"今回の住宅宿泊事業法の規定では、以前の旅館業法よりもかなり条件等が緩和されて民泊事業が実施できるようになっております。の条例制定等も手続きがありますので、現実的には、民間が通常の事業として実施するほうがスムーズに移行できると考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"その点について、区はどのように考えているのか。区としての条例は考えていないというお話ですから、そういう住民の不安や旅行者の安全確保についてどのようにお考えなのかお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"防災面、衛生面については、具体的に今検討しているガイドラインの中で規定を予定しているそうです。区もそれに準じて、しっかりと区の権限の中でできることについては対応したいと考えております。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"観光を楽しめるように、レインボーフラッグを掲げることや、宿泊施設との調整や理解を広げていくことを求めていきたいと思います。旅館業法などの規定に適合した許可制をしっかり堅持したルールの整備こそ必要だと思いますので、そこを踏まえていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"田中委員","kind":"意見","question":"区内で事業開始に向けた準備を行っているという部分なのですが、地域の方からは不安の声が上がっているのです。事業者が民泊を始める前に、近隣住民への説明がどのように行われるとか、そのような具体的なことは何か決まっていますかとの意見を述べました。","respondent":"鈴木文化観光課長","answer":"先日の説明会では、それから近隣の方への説明についても、そのような指導をするというところは方向性として聞いています。政省令にしてもガイドラインにしても今検討中で、そのような項目については認識をして、検討しているというところまでの報告だったので。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"住民の方たちが納得するようなちゃんとした説明と、民泊が行われる前にきちんと話し合いがされる場、住民の方たちの意見が聞ける場というのは必ず用意してほしいという要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"去年、私が電話でヒアリングしたときには、ＬＥＤの電球が幾ら、設置費用が幾ら、維持管理、撤去代が幾らということを伺っているのです。もっと具体的な内訳を書いてほしいと思います。","respondent":"鈴木文化観光課長","answer":"昨年度は事業を実施した後で、この４事業はこれから実施で、契約手続なり手配をしています。その辺は、今後、実施しまして、報告のときには詳細な内訳についてもご説明ができるようになるです。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"シナモロールの切手について１点だけ伺いたいのですが、これは１,５００円で１,０００シートだから、１５０万円ではないですか。切手は１０枚だから８２万円ではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"それから区の考え方としては、観光大使、協力してＰＲしていただくと区では考えております。これは、区がその事業の中でシナモロールを使ってもらってＰＲしていただくという考え方です。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"一応予算額がついているので、何となく大体幾らくらいというのはわかっていると思うので、次からはそこら辺までを書いてほしいと思います。なるべく情報はいっぱい欲しい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどのシナモロールの切手販売も、今回の体育の日の事業についても、報告事項ではなくてその他として扱う。それぞれしっかりやっていただきたいとは思うのですけれども、何だかなという思いが。","respondent":"本多委員長","answer":"最初から報告事項に上げられるような委員会運営に努めていきます。ほかになければ、以上でその他を終了いたします。","id":"exchange-024"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"現地でそのようなことは言いませんけれども、要するに安全のルール化、条件をどのように整理しているのか、その点について伺いたいと思います。具体的には、正副にお任せいたしますけれども、調整していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問","question":"平日であったり、そのようなところをどのように取り組んでいるのかを細かく、世代や対象をどうやっているのか。当初の想定から、いざ実際やってみてが違うと思うので、そういうものが取材できたらいいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/552438?Template=document&Id=2792#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":38240,"voices":84}},{"id":"h29-20170926-7","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","agenda":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、品川は、促進係数も１.５になっているということですけれども、そういうのも含めて、補助金が何床で幾らになるのかも教えてください。それからあともう一つ、介護予防拠点併設と書かれているのですけれども、この介護予防拠点というのはどういうものなのかについても説明を求めました。","respondent":"大串福祉計画課長","answer":"先ほど最初の資料でもご説明しましたが、今も一宮市で特養を運営している法人です。メインになるのは、健康運動指導士を講師として行う体操教室を今のところは計画しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総事業費、総建設費というのでしょうか、それがわかったら教えてほしいと求めました。区がこの道路がないために買えないと言ってきたものが、法人だったらなぜこういうことができたのかについても説明を求めました。","respondent":"大串福祉計画課長","answer":"売却金額につきましては、申しわけありません、非公開ですので、私からはお答えしかねます。いわゆる西側のほうの前面の道路に接するところですが、幅としては６メートルです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"補助金として併設加算というのがつくと思うのですけれども、これ以外のところでは加算がつくようなものは併設されないのでしょうか。例えば、認知症対応のデイサービスだったりとか、そういうふうな併設加算がされるようなものがほかにはないのかだけ、確認をお願いします。","respondent":"大串福祉計画課長","answer":"今委員からありましたようなデイサービスとかそういった施設の併設は、今のところ考えていません、スペース的に少し厳しいといったところです。やはり９０床とるということで、そちらのベッドを確保することに法人のほうでも注力したところかと思います。","id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど道路の確保で法人の努力と言われていたのですけれども、区は努力できなくて買えなかったのかなというふうにも聞こえるので、そういうのは区が道路を確保することはできないのか、伺いたいと思います。","respondent":"大串福祉計画課長","answer":"金額、これに対してどういった活用ができるか、その中でどのような形で購入ができるかというところで区のほうとしては対応せざるを得ない。それを買う、あるいは活用するに当たっては、もうワンステップ、ツーステップあるということで、なかなか難しいところです。","id":"exchange-004"}]},{"id":"topic-02","title":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６１ページなのですけれども、障害者グループホーム連絡会がつくられて年５回開催されたということなのです。区の職員もここにかかわっているのかについて、まず説明を求めました。","respondent":"中山障害者福祉課長","answer":"これは知的・精神全ての区内グループホームの世話人に声をかけて実施しているものです。区の職員としましては、一応、係長を行かせています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そしてまた、ぜひ質の向上につなげていただけたらなと思いました。いろいろなところから社会福祉法人が入られて、すごく広がったと思うのですけれども、そういうところでの交流はあるのか説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"従来からの５法人につきましては、交流会というか、担当者会議、事業所会議みたいなものを継続してやっております。新しく入った法人につきましても、定例の事業所連絡会ということで加入していただいて、意見交換、情報交換を２カ月に１回開催しております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"されていないところがあったり、それから、認知症のデイサービスの利用率がこれだけ少ないことを区としてどう捉えているのか。今後どういう取り組みを考えられているのかもあわせてお聞かせいただけたらと思いますとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほども説明の中で触れたとおりですが、認知症デイの取り組みについての課題抽出ということで、実際に会議を持ちました。この辺を含めまして、第２回以降の認知症に関する検討会の中で掘り下げていければなと思っています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうことでこの額になっているのかという仕組みなのですけれども、要綱とかそういうのがあるのか、どういうふうにしてこの額が出てくるのか。そして、もし全くの民間だったら、これがないまま介護報酬だけでやるのか、その辺も説明を求めました。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"先ほども少し説明で触れたのですけれども、身体機能がある程度しっかりしている方は、認知症があっても要介護度があまり重く出ない傾向があります。それ相応の対応はどの施設もやっておりますけれども、これが現実に起きていることなの… 私からは、障害者福祉施設の管理委託料の考え方についてご説明いたします。人数であったり、そういった幾つかの指標があるのですけれども、その指標をもとに民間に対して区を通じて１０分の１０の補助金が出てあります。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう基準で出ているのかということでは、要綱とかあるわけではないですか、その辺の仕組みを教えてほしいと求めました。そこのところでは、基本的に平成２７年と平成２８年は変わらないと考えるのか、職員の待遇の部分についても説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"それと、報酬改定等も含めた法人とのヒアリングの中で、区のほうでも必要に応じて支援できるところはしていくということです。質の向上・人材確保につきましては、区のほうも各法人向けにさまざまな支援を行っているところですし、今後もそれは継続して行っていきます。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"幾ら委託料を出すよという協定になっているという意味でしょうか、その点、１点お願いします。その協定の中の委託料の計算の仕方が、何を基準にしてどういうふうに決まってくるのかを、わかる範囲で教えていただきたいのが１点です。","respondent":"寺嶋高齢者福祉課長","answer":"それから、それは各施設のほうできちんとした対応をして、各職員として給料として還元されるような対応をとっているところです。法人によっては１桁台のところもまだまだありますので、この辺はどういった取り組みをしているのかも、人材確保・定着に努めているところです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、離職率は、１４.８％になってしまった、２.７％も上がったというのは、区としてはどう捉えているでしょうか。そういう点で言えば、離職率が２.７％も上がってしまったことに対して区としてどう捉えているかをお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"その辺は当然認識を持った上でやっている、当然この仕事に働きがいを持ってやっていると言っております。例えば、送迎とか配食サービスの実施とか、そういった個別の事業について加算をして給付金額を決めていくといった内容です。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"資格のきちんとした人の配置に向けた支援も必要かと思うのですけれども、この介護福祉士の資格取得の支援は区としてはあるのか１点お聞かせください。それともう一つ、ショートステイの全体の需要は区としてはどうなってどう捉えられているかについて説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"２つ目のショートステイですけれども、緊急ショートなど、この場合の対応が１つ必要だということがあります。これは、デイとヘルプで対応ができているという数値なので、この数字が高い・低いについてはあまり問題ないという認識を持っております。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、先ほどの賃金にしても、２１万円台というのは、やはり１０万円くらい差があるという数字になると思うのです。そういうところもぜひ区のほうからも求めていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"簡単に２点だけお聞きします。ここだけ特別に入所者の平均年齢が８９歳ということだったのですけれども、ここだけなのか、その辺の感覚をまず。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘のとおりここにしか書いていないのですけれども、ほかの施設については実際には上がっているという認識です。原因は分析していないのですけれども、ここの施設が結果的に下がったので、こういう記載があったと認識しております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それからもう一つだけ、５７ページ、品川児童学園です。肢体不自由児への対応や保育園等との併用利用というのが出てきて、昨日もたしか出ていたので、この辺もう一回説明を求めました。","respondent":"中山障害者福祉課長","answer":"Ｃｏｍｐａｓｓは少し違うのですが、通園について言うと、ほかの幼稚園あるいは保育園に通っている方がご利用できない状況になっております。例えば週２日の療育を受けられる、そういう機会を確保していく必要がある、事業者とも共通の認識を持っているところです。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"福栄会がこういうコメントを出していること、グローが今後はやっていく、その辺の引き継ぎ関係は十分とれているのか。場所としても、あの場所ではできないですよね、その辺はどう考えているのか説明を求めました。","respondent":"中山障害者福祉課長","answer":"昨年度１年間かけて、その引っ越しが終わった後の１年間は、福栄会とゆうゆうで引き継ぎの作業をこの間やってきました。平成３１年度に新しい施設に移ったときに速やかにそういったことができるよう、運営事業者とクラス編成の持ち方について話を進めているところです。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"１０ページですけれども、昨年度比で５００万円の光熱水費を削減したとあるのですが、職員の方々の負担はあったのかどうかを１つ教えていただきたい。そしてもう一つ、今回のこの省エネ診断については、どこが発案というのでしょうか、きっかけとして行うことにしたのかを説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"ランニングコストが５００万円、実際７,５００万円程度のものが７,０００万円ぐらいに下がったということを、改善点として上げたという内容です。したがって、大きな施設であればこのレベルの機械室はあると思いますけれども、施設規模によって違ってくると思います。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２５ページで、すごく正直に書かれているなと思ったのですけれども、そういう状況もあるのかなと思うのです。先ほど、それ以上に区として人材確保の支援を進めていく体制、今後どうされていくのかというのを伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"経験のない職員の方を法人の経営方針にあわせて１から研修をしていくというやり方が効果的だと捉えている法人もいますので、全くの新しい方をとる。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"人材確保のための賃金アップを国に求めるとか、介護の改悪をストップさせるとか、そういった立場に立ってほしいと求めました。そうすると、児童発達支援ほぼそれの利用率になるのか尋ねました。","respondent":"中山障害者福祉課長","answer":"すみません、ご説明が足りませんでした。児童発達支援のうち通園の部分の利用率になっております。","id":"exchange-019"}]},{"id":"topic-03","title":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","agenda":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その順位をつけるに当たって明確な点数になっているのかを教えていただきたいのですが、そういう点数表があって、高い順番から順位が決められるのか。５番のところの応募資格なのですけれども、築５０年とか６０年とかで地震が来たらつぶれそうというところも入るのかについても説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"ただ、点数では判断できないご本人の生活状況等もありますので、そちらも加味しながら行っているものです。それから３点目、築年数あるいは壁などにかなり傷みがあるですとか、そういったものも考慮の対象になっております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補欠登録者は単身が２０人と２人用が１０組ということなのですけれども、ここのところでは１年間で何人ぐらい入れたのかを教えてください。単身用だと２万５,６００円までの、丸々２万５,６００円の助成が出ている方は何人ぐらいとか、どれぐらいあるのかについても説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"それから２点目ですけれども、大井林町の入居人数ですけれども、平成２８年度は９名の方が入居されております。全額、要は上限まで助成を受けている方がどれくらいいるのかというご質問だと思いますが、ほとんどの方が対象になっているかと思います。","id":"exchange-021"}]},{"id":"topic-04","title":"後期高齢者医療制度保険料","agenda":"後期高齢者医療制度保険料","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その財政安定化基金というのは、東京都広域連合で幾らたまっているというのがわかったら教えてほしいと求めました。剰余金は８４億円、保険料抑制のために、平成２８・２９年度のときは使われたということで考えていいのでしょうか、それが１点です。","respondent":"三ッ橋国保医療年金課長","answer":"一方、剰余金に関しましては、現時点で見込むことは困難です。例えば、平成２７年の決算が終わらないと剰余金がはっきりしませんので、そちらに関しましては現時点では剰余金を見込むことが困難となっております。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１万３,６９２円という形ではなくて、平成２８・２９年度と均等割・所得割、それほど大きく変わらなくて済むと考えていいのか。一番初めのページの２つ目の保険料率算定時の設定条件というのがありますけれども、これがどういう中身なのかについて説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"やはり低所得者に対するもの等さまざまなものがありますので、特例対策は実施していくものと考えております。国の制度施行時の特例措置については、現在２０％ですが、今後、平成３０年度は廃止の見込みとなっております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとも、国が０にするのだからと東京都までなくしてしまうとか、そういうところまで話し合われているのかどうかを１つお聞かせいただきたい。そういう軽減措置が平成３０年度から国のほうでなくなっていくと、東京都は一体どうするのか、その辺の見通しを説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"与えないよう現行制度を継続するようにということを、はっきりしたものが出ていないのですけれども、国に対してはそのように言っているところです。その部分がまだ実際公表されておらず、取りまとめ中ですので、またわかり次第お伝えできる段階でお伝えしていきたいと思います。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっとですかね、７５歳以上ですから、継続できるようにお願いしたいと思います。それはぜひ要望いたします。","respondent":"三ッ橋国保医療年金課長","answer":"次に短期証ですが、短期証の方は、平成２９年８月１日現在で６０名になっております。滞納者数は平成２９年５月末現在で１,２０５名となっております。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そういう中で、均等割の上がりが２００円と。それぐらいに今回もなっていくのか、そういうのは今の時点ではわかりますかとの意見を述べました。","respondent":"三ッ橋国保医療年金課長","answer":"この１人当たりの平均保険料率につきましては、増加する要因と減少する要因、剰余金とこの基金以外にもさまざまな要因があります。したがいまして、今の段階では広域連合が算定できておりませんので、またわかり次第お伝えする予定です。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も上がってほしくないという思いで、幾らかなということで質問してしまいました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地下１階と言いながら地面から入れるところなのか、その辺のところがわからないのですけれども、なぜ地下１階なのか。もう一つは、今まで使われていた上大崎１－３－１２そのものもどんな状況なのかよくわからないのですけれども、その点について説明を求めました。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"１つは、再開発事業の中で公共公益施設の設置というものがありますので、在宅介護支援センターほか公共公益施設が入るということで。アクセス等はあれですけれども、少なからず駅からのアクセス等も含めて… この在宅介護支援センターの移転の後なのですけれども、今、上大崎シルバーセンター１階の洋室に在宅介護支援センターが入っている状態なのです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"補助金もたしか税金投入が１００億円を超えたと思うのですけれども、そんな中で何で地下１階しか出さないのかという思いがするのです。本当に地上からそのまま入れるようなところへ要求はできなかったのか、その思いだけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"現在の在支から目黒駅前の開発ということで、利便性とか、面積も大変広々となって、在支の役割を十分に果たしていただけるものだと期待しております。利用者のお声はどういうふうに聞かれて、相談しながら進めることになるのでしょうか、そこの確認だけ。","respondent":"松山高齢者地域支援課長","answer":"３月１日に受け付けを開始しまして、一般の方々向けには３月１０日から受け付け開始を考えています。ですので、そのスケジュールで逆算しまして、町会と近隣の方々にはご説明をしようと考えています。","id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"今の２０平米の部屋を内装をして、しつらえて、そこはまた地域の方の交流の場に使っていただけるということで部屋について、どういう仕様、使い勝手のよさにするかという、地域の方の町会等の声は聞いて何か反映させる方向性があるのかどうかだけ確認します。","respondent":"松山高齢者地域支援課長","answer":"今の部屋はかなり手狭で、部屋自体の工夫、間にパーテーションを入れるとかそういった部屋ではなく、２０平米ほどです。机・椅子は用意して、空調などもきちんと整備した上で、使い勝手のいいような形では考えたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"手狭で引っ越すということなのですけれども、今度のところの広さだけ説明を求めました。","respondent":"寺嶋高齢者福祉課長","answer":"新しく移転する先の在宅介護支援センターの床面積は、現在の資料では１４８.０５平米となっています。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374035?Template=document&Id=3488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":65913,"voices":110}},{"id":"h29-20170926-8","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"建設委員会","time":"午前１０時００分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","agenda":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと確認したいと思います。ちょっと具体的に教えていただきたいのと、緊急時の二方向避難というのはどんなふうになっていらっしゃるのか説明を求めました。","respondent":"稲田都市開発課長","answer":"次に、住居数をお知らせいたしますと、全部で９４０戸の予定です。１Ｋが１００戸、１ＬＤＫが２４０戸、２ＬＤＫが３００戸、３ＬＤＫが３００戸というような予定で現在やっているです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"組合からの提案があって、というのをちょっとお伺いしたいのと、伺ったのは１２０名の定員だということですけれども。都市開発課としての見込みをお伺いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"１２０名となったのは、保育課の判断なのですか。ほかのところから引っ張ってくるというのは、そのあたり都市開発課としての判断はどうだったのかなというのもお伺いしたいというのが２つ目です。","respondent":"稲田都市開発課長","answer":"在宅介護のほう、保育もそうなのですけれども、所管と協議をしながらこのような形でやってきたです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"所管とどんな協議をしているのかというのをお伺いしているのですけれど。まちづくりなわけですから、最終的には……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それは今回幾らで、それは同様に、この公共施設との関係は何かあるのかというのを、２点目、お伺いしたいと。それをお伺いしたい。","respondent":"稲田都市開発課長","answer":"これとは別に都市計画道路補助の１５９号線を整備するこの開発の中で、都市計画道路を整備するということで、これは別途出ているものです。区の権利床ということです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと聞いたのでお伺いしたいなと思いますのと、これは今回の公益施設ということもあるから、そこに対応して幾らというわけではないのかどうかと。そこはちょっとはっきりしなかったので、お伺いしたいなと思います。","respondent":"稲田都市開発課長","answer":"公共施設管理者負担金の、区としてこの組合に充てている補助金の総額が、９億９,８２１万７,０００円、約１０億円です。地域貢献施設ではこういうものをつくっていきましょうというところでやってきたものですから、補助金は関係しているというものではございません。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ、確認します。この地域のここの場所の駐輪対策、自転車の対策がどうなっているのかというところを確認したいと思います。","respondent":"稲田都市開発課長","answer":"この開発の中で、一般の方、ここに住んでいる方以外が使える駐輪場の台数が２１５台あります。その中で、保育施設に１０台、在宅介護施設に１０台ほど割当てがあるということで進めております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"では、これは保育施設のところに１０台とかではなくて、決まった場所に。駐輪場がどこの位置になるのか尋ねました。","respondent":"稲田都市開発課長","answer":"表記がないのですが、資料の右上のこの平面図を見ていただきますと、区画道路２号というのが、左上のほうに書いてあります。その下のＡ棟１階平面図というものがありますが、この１階の部分で、これが駐輪場です。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"その辺の融通策があるのでしょうかというのが１点です。災害時にいろいろな地域の方々が利用される部分もあるのだろうなと思うのですが、備蓄についてはどう考えたらいいのか尋ねました。","respondent":"稲田都市開発課長","answer":"再開発組合等々と協議をして、ではこれぐらい、あれぐらい。では、これでいこうかというようなことで決まっていくという状況です。","id":"exchange-009"}]},{"id":"topic-02","title":"平成２９年度ウォームビズキャンペーンの実施","agenda":"平成２９年度ウォームビズキャンペーンの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"室温１９度ということを目途にということなのですけれども、部屋によっても違うと思うのですけれども、そのためには大体エアコンは何度ぐらいの目安になるのかと、どのように呼びかけをするのでしょうかということをお伺いします。","respondent":"小林環境課長","answer":"ただ、その設定する、感知する場所によって１９度が適切かどうかというような判断は多少変わってくるかというふうに思っております。部屋の中にある温度計を見ながら、１９度に細かく調整していくということが必要なのかなというふうに思っているところです。","id":"exchange-010"}]},{"id":"topic-03","title":"シェアサイクル事業の開始","agenda":"シェアサイクル事業の開始","exchanges":[{"speaker":"横山委員","kind":"質問","question":"２点目なのですけれども、こちらの区内のモデル周遊コースのようなものは想定されているのでしょうか。それを例えばパンフレットですとかホームページ等で周知・告知していったりするということなど、何かお考えがありましたら説明を求めました。","respondent":"今井土木管理課長","answer":"そういうことを検討していく内容です。今後、自転車を活用した検討を進めていきたいというお声もありますので、一緒に検討を進めていく内容だというふうに考えております。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"先行自治体との比較ですとか、そういったところも、うまく広域化とともに進めてほしいと求めました。こちらも、うまく周知のほうを連携して進めていただきたいということで、ご要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"持ち運びしていくのですかという形をどう考えられているのですかということ。何となく観光と絡めてと言っておりましたけれど、もう少し分析等々が必要ではないかなと思うのですが、いかがか尋ねました。","respondent":"今井土木管理課長","answer":"ただし、今、東京都環境局の補助金がありますので、このうち２分の１は都の補助金で進める予定です。それから４点目の設置ポートですけれども、デメリットもご説明できませんので、検討してまいります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"１点目のコストの件ですが、これはドコモのほうでもうけがなかった場合、品川区は補助するということはあり得るのでしょうか。これから開発するにせよ、予測を立てながらやっていく必要があるのかなと思うのですが、その辺の考え方はいかがか尋ねました。","respondent":"今井土木管理課長","answer":"次にポートの設置場所ですけれども、今、自区内の検証は今年度で終わらせようと思っています。これは広域連携をして、どのような場所に設置していくのがいいかというのも、ほかの連携している区やそして東京都とも確認しながら進めてまいります。","id":"exchange-014"},{"speaker":"西本委員","kind":"確認","question":"再度、確認です。１点目だけ、お願いします。","respondent":"今井土木管理課長","answer":"現在の時点では、広域先行自治体も含めて、運営費というのは、なかなか補助というのは難しいという状況です。中国なども含めてありますので、まずは社会実験という形で進めながら、状況に応じて対応していくものだというふうに考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"確認","question":"どれくらいの自治体で実施実績があるのかお伺いしたいのと、あと料金設定ですけれど、これは消費税別ということですかねという確認と。お伺いしたいと思います。","respondent":"今井土木管理課長","answer":"２３区以外でも横浜市など既に進めているところですが、先ほど申しました都心６区に加えて、大田が導入いたします。私どもも種々検討いたしましたけれども、今後広域連携していくという中では、私どもの判断で先行自治体と同じ料金ということで決定いたしました。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"実施規模ということで１８箇所ということでありますけれど、それともさらに１８箇所から順次拡大していくというふうなのか、お伺いしたいと思います。私も使っていますけれど、使ってくるとだんだん充電が短くなったりするのですが、これはどういうシステムなのかなというのをお伺いしたいと思います。","respondent":"今井土木管理課長","answer":"それから、もう一つ充電ですが、充電のほうも、再配置とともに業者であるドコモ・バイクシェアのほうが充電というのも行います。フル充電したときには、区内の今の面積を考えますと、一定の期間は十分ご利用いただけるというふうに考えております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。区としては、どの辺を一番ターゲットに考えているのかと、そこら辺をお伺いしたいのですけれど。","respondent":"今井土木管理課長","answer":"ポートを置ける場所、または置いていただける民間企業等にお声をかけまして、ビジネスユースも考えていく範囲には入っております。日常利用につきましては、まずは日常というのは、今後ポートを増やしていった中で活用されていくものだというふうに考えております。","id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"利用料金の中の１日パス１,５００円で、これはこの専用のカードの発行ということでの５００円なのか、ちょっと確認をしたいと思います。どういう成果があるのかというのを検証してほしいと求めましたが、例えばちょっと所管が違うので要望だけしますが、。","respondent":"今井土木管理課長","answer":"実は他区ではもう既に実施されているのですが、利便性を高めるために有人窓口で購入する場合の発行手数料が５００円かかるという形になっております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"自転車のデザインや形というのは、この写真のとおりなのでしょうか。広域ということで、それは全て統一ですということで、よろしいのか尋ねました。","respondent":"今井土木管理課長","answer":"ご質問いただきましたとおり、ドコモのシェアサイクルは全てこの赤い自転車です。２９年度は自区内運用ですので、平成２９年度は、品川区で運用していますということがわかるようにしてまいります。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"では、形はこれということで、多い荷物を運ぶにはちょっとかごが少ないのかなという。最終的にはこのドコモ・バイクシェアがお考えになることかもしれませんけれども、その点、ご見解はいかがか尋ねました。","respondent":"今井土木管理課長","answer":"かごも、もしかしたらもう少しいいものになるかもしれませんが、現状ではこういうふうな形で進めていくものです。ほかの広域連携になりますと、３０年度以降の自転車のときには、看板のような形で運用されていくものと考えております。","id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"何点かお伺いしたいのですけれど、品川区としては財産になるものなのですかということが一点と、しながわ」と書いてあるわけですよね。どういうストーリーというか、地図を広げるわけにはいかないですから、そういったがばっというのを取りつけられるものもあってもいいのではないかな。","respondent":"今井土木管理課長","answer":"私の説明に不備があったと思いますけれども、こちらのほうはドコモが購入することに対して、品川区が補助するという形になります。見えるところにつくような形での使用を検討しているとは聞いておりますので、あくまで広域連携の中で活かしながら取り組んでまいりたいと思います。","id":"exchange-022"},{"speaker":"いながわ副委員長","kind":"意見","question":"この赤いドコモのシェアサイクルはそのままにしておいてくださいなのか、それとも乗る前にしっかり注意をするのかどうなのかとか、その辺というのは何か対策というのは考えられているのかなという１点だけ説明を求めました。","respondent":"今井土木管理課長","answer":"もちろん放置自転車禁止区域にとめているものは、これは撤去の対象になります。可能性としてはほかの自治体で行われておりますので、それも含めての運営というふうに考えているところです。","id":"exchange-023"}]},{"id":"topic-04","title":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","agenda":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"やはりいざ事故が起きてしまった場合などは大事だと思うので、そういった周知といったこともぜひこの中にあるといいなと思うのですけれども、いかがか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"自転車シミュレーターといったものも実際現場のほうに置きまして、こういったところを実際に乗ってもらって、自転車の安全性を確認してもらう。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"加入できますよということで、周知できるようなブースなどを工夫できれば、ぜひお願いしたいというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-05","title":"本日は防災対策に関することのうち、地域防災計画の改訂","agenda":"本日は防災対策に関することのうち、地域防災計画の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、やはりそういったところも大きく章立てをしてつくっていっていただきたいのですけれども、いかがでしょうかというのが１つです。コンビナートの火災ですとか、区内で起こり得る被害想定というものをどこまでされているのか、そこら辺についてはどうか尋ねました。","respondent":"古巻防災課長","answer":"検討経過のところで記載させていただいている中で、備蓄の関係で、そういったあたりはまずは予防対策になるのかなというふうに思います。コンビナート関係の事故に関しましては、こちらの中で想定をして、計画の中に反映していくというふうに考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは当然新ルート計画を今国が進めている状況で、この航空機の大規模事故というのは一体何を指しているのか、ご確認したいというのが一つあります。それから質問のもう一つは、区としては何か改善していくという計画やお考えはあるのかないのか、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"対策を記述するですので、そちらの羽田関係の状況とは切り離して考えていきたいということで、ご理解いただければというふうに思います。区としても耐震助成などを進めているですので、そのあたりは十分対策を考えて区としても進めているというふうに認識しております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"今落下という話もありましたが、この航空機の大規模の事故というのは墜落事故が含まれているということでよろしいのかどうかをお伺いします。そのように修正していく必要があるのではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木建築課長、古巻防災課長","answer":"やはりこの平成１２年を境にしたところでも数棟被害が出たというところで、この建物の耐震性能をチェックできるチェックシートが公表されております。今後この助成のあり方等々については、東京都等の動向も踏まえながら… そういった構成にかかわる部分につきましては説明がちょっと薄い部分があるかとも思いますけれども、そのような形でご理解をいただければと思います。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと現実的ではないのではないかという思いもありますので、そこら辺はちょっと私もさらに研究して要望もさせてほしいと求めました。シンプルに伺っているのですけれど、先ほどの想定の中には墜落事故も入っているのですよねという確認だけなので、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"区内で墜落事故がというのはちょっと考えづらい部分もありますけれども、墜落をするということも当然可能性としてはあり得るというふうには思います。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"町会の人がやるのですか。２－３で男女共同参画の方々に意見を伺いということなのですが、情報収集されているところもあるので、それらはまとめられているのか尋ねました。","respondent":"古巻防災課長","answer":"多様化する避難というところでの、避難所における発災時初期の対応が重要であるというようなお話でございましたけれども。ですので、今現在行っております個別計画の作成の支援の中で、さまざまな資料をつくってご説明をしていきたいというふうに考えているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"これに入れ込めるのかどうかわかりませんが、現状を踏まえながら、実際必要なことをまず見直しを図っていただきたいと考えています。なので、この初期の体制を何とか研究を進めていただきたいと思うのですが、最後にお聞きしたいと思います。","respondent":"古巻防災課長","answer":"やはり非常に必要なことであるというふうには認識しておりますので、基本的な考え方については、さらにそういった部分をきちんと職員間においても認識が進むような形で進めていきたいというふうに思います。","id":"exchange-031"},{"speaker":"新妻委員","kind":"質問・要望","question":"促進をしていただきますが、促進ができているのかどうかというのは、区はどうやって確認をしていただくのでしょうか。そこをお聞かせほしいと求めました。","respondent":"古巻防災課長","answer":"区は認識をしていますので、まずマニュアルに関しましては、計画の中に項目でありますとか考え方を明らかにしていきたいと思います。避難所連絡会議の中で、現在マニュアルの作成の状況がどうなのかとか、そちらの中で防災課のほうで把握していきたいというふうに考えております。","id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"水と備蓄とトイレがあれば生き延びていかれるわけですから、このトイレの確保というところもしっかりと周知をしてほしいと求めました。そういう具体的な各それぞれのご家庭でのトイレを確保するということの必要性もあわせて訴えてほしいと求めましたが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"ペットの訓練については進めていきたいというふうに思っておりますので、そういった訓練が進むようにしていきたいと思います。そういった中で、ご家庭でのこういった備蓄の考え方でありますとか、十分提案できるような修正をしていきたいというふうに考えております。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"表記のことで伺いたいところなのですが、２－３とありますが、２－１の１番目の「『受援計画』を地域防災計画に追加する」。２－３で「意見を伺い、計画へ反映する」というのですけれども、この計画なるものはどのようなものか。","respondent":"古巻防災課長","answer":"検討結果の２－３の「意見を伺い、計画へ反映する」の「計画」につきましては地域防災計画のことです。特に意図があって計画というふうに縮めたものではありませんけれども。","id":"exchange-034"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"確認というか、どういうイメージかだけ教えていただきたいのですけれども、１－３、黒丸「円滑な災害対応に向けた災害対策本部の再編を進める」。それはこれから議論されるのかもしれないですけれども、今の現段階でのイメージを説明を求めました。","respondent":"古巻防災課長","answer":"そのところで区の災害対策本部ときちんと連携をとった形で復興のフェーズが進んでいくようにというような意味合いでこちらに書かせていただいている…ちょっと説明がうまくいっていなかったでしょうか。","id":"exchange-035"},{"speaker":"いながわ副委員長","kind":"質問","question":"何か多少リンクして、立ち上がったときには災対本部とこの復興本部の人というのは、兼務することになるということでいいのですか。要は、密にするというのは、当事者がやっているわけですから、密も何も、何かぴんとこなかったので質問させていただいたので。","respondent":"古巻防災課長","answer":"体制としては若干オーバーラップする部分もあると思うのですけれども、業務としては少し切り分けて考えていただいたほうがいいかなと考えています。ただ、中でそういった形で記述をしていこうというふうに考えております。","id":"exchange-036"},{"speaker":"いながわ副委員長","kind":"質問","question":"それを加える、推進するために設置すると書いてあるということは、要は今はないわけではないですか。まちの復興ですから、これは危険な建物ですよと貼ったりする業務は、ここの本部を中心として指令が出てやるというイメージでいいのか尋ねました。","respondent":"古巻防災課長","answer":"震災復興本部の設置についても現行の計画の中できちんと記載があるものですので、忘れないようにきちんとここで連携について記載すると。","id":"exchange-037"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"その人たちの役割というのは何なのですかというのは、恐らく書いてあるのですけれど、あまり明確になっていない。その人たちの役割というのは何なのですかといったときに、わかりやすい計画にしていただきたいなと思いますが、いかがでしょう。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"わかりやすい計画にということは当然意識しておりますので、震災復興マニュアルにつきましても、今後改訂をしていくというような形になろうかと思いますので、中できちんと明確にしていくということを意識してまいりたいと思います。復興本部というのは、将来に向けた防災に強いまちづくりをしていくということで、もう数年単位の事業になろうかということになります。","id":"exchange-038"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはり自転車をどう位置づけるかという計画、そこら辺についても、調査をぜひ深めていかれたらなという思いがあります。防災まちづくり、やはりふだんからの防災コミュニティというのですか、ある程度の時間はしっかり確保していただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問","question":"中越市民防災安全士会がありまして、これは事業として市がお金を出しているのだと思いますけれども、ここら辺の取組みを少しお伺いしたいと思います。長岡市の資料の後ろのほうです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"新妻委員","kind":"確認","question":"火事があったときには危険だという認識があった中で、なかなかそこが進められなかった現状といいますか、そこを確認したいなと思います。それと、自転車レーンの整備、自転車の走行にあたっての道路整備がどのくらい進んでいるのかというのをちょっと確認したいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132633?Template=document&Id=4214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":56952,"voices":148}},{"id":"h29-20170926-9","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"学校改築事業の進捗","agenda":"学校改築事業の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１階のところで、左側に広場門というのがあると思うのですが、改築したときにこの広場門は生徒が使えるものになるのかどうか伺いたいと思います。普通に考えると、１階に教室があったほうが校庭にも出やすいですし、２階から教室があるという考え方も教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"かなり広いスペースを体育館が占有するということになりますので、教室を入れることができないということになります。教員がすぐ飛び出していってすぐ対応するなど、それと同じような形で保健室等を１階に置くことで、教室等については２階以上に設計しているものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、生徒の通学の際に正門と北門からだけになるという考えでいいのか、改めてお聞かせほしいと求めました。これはそうするとどういった活用の仕方になっていくのか、イメージが湧かないものでご説明ほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"これからの検討課題ではあるのですけれども、そういった形で命名をしまして、子どもたちに親しみを持って使ってもらう。運用面については学校の中でさまざまなあろうかと思うのですけれども、こちらのほうは今後学校運営の中で検討していくことを想定しているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今計画として、４校を示していただいたわけですけれども、今後の計画がどうなっているのかという学校改築の全体像を伺いたいと思います。今ある小中一貫校６校でしたけれども、何か私的には施設見学させていただいたときも、そういうことも含めて伺っておきたいと思います。","respondent":"篠田学校計画担当課長","answer":"そういった部分でどういった対応ができるかということを考えたときに、そういうことも踏まえまして、今回１８クラス規模としたものです。対応できるものに関してはエコスクールの設備をできるだけ入れていくことを考えてありますので、一応方向性としては想定しているものです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"もちろん保育園もそういうスタンスでやっていただきたいと思っていますけれども、学校の対応というのは、よろしくお願いしたいと思います。そういうのがちょっと心配かなと思って取り上げて質問したので、ぜひ安全性が担保されるようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"普通は校舎と別にというのでしょうか、その際、ここの空調というのはどういうふうに考えていらっしゃるのか。後地ステップの上がそうなるのですか、この図面でどう見たらいいのかというのを説明を求めました。","respondent":"篠田学校計画担当課長","answer":"現在のところ、当初から冷暖房の設置というのは今のところ学校の仕様にはございませんので、当初から冷暖房を入れる予定は今のところございません。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認です。今後もそういう考え方で区の改築される学校を整備していくということでいいのか、３点確認ですが、お願いいたします。","respondent":"篠田学校計画担当課長","answer":"ご説明申し上げたとおり配管だけは通しておくという状況ですので、状況によってはその配管を活かして冷暖房が設置できるように設計しております。それから、最後の体育館の風の吹き抜けにつきましては、説明が不足しておりまして申しわけありません。","id":"exchange-006"},{"speaker":"こんの委員","kind":"確認","question":"参考までに進捗状況を一つだけお伺いしたいのですけれども、今、いつ頃完成になるのでしょうか。ちょっとこれだけ確認をさせてください。","respondent":"品川庶務課長","answer":"大井第一小学校の人工芝ですけれども、秋ごろを今予定しております。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"もう間もなくということで、例えば、校庭で行う授業は全部体育館でやっていたということだったのでしょうか。その辺を説明を求めました。","respondent":"品川庶務課長","answer":"人口芝の工事をしている期間ですけれども、基本的には体育館等を利用しておりまして学校内でいろいろな工夫をしながら体育等を行っているものと考えております。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"城南小学校で出た埋蔵文化財は、学校の中で展示室みたいなものをつくって、今後展示するということでよかったのでしょうか。同様に、鮫浜小学校はこれからプロポーザルということですけれども、想定としては何クラスと考えているのかというところもあわせて説明を求めました。","respondent":"篠田学校計画担当課長","answer":"今後なかなか現在の形での説明会、今のところ想定していないものです。鮫浜小学校の学区域内で多数の大きな建物が建つ見込みはないのですけれども、再開発等があるとそちらのほうの選択がなかなかできない。","id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"区内の児童などにも機会があれば見てほしいなという思いで質問をしまして、それがその学区域、さまざまな地域で起こり出しています。だけど、それなりに考えて進めていかないとならないのかなという思いはずっと持っていますので、そのような考えで進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"特別支援教室が２階ですけれども、教室をここに置いたお考えを伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"後地小学校の特別支援教室につきましては、こちらの図面では２階の真ん中あたりに今、実施設計において考えているところです。特別支援教室ですけれども、基本的に設置に関しましては他の学校もそうなのですけれども、普通教室の並びの中でと考えているところです。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"意見","question":"ちょっと外れる場所にあったりする所もあるので、今お話になったようなコンセプトで他の児童と交流できるような形でつくっていただくのは大変ありがたいので、ぜひそのお考えで進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"４階にないと思いますが、実際どうなのかということ、どういったものになるのか伺いたいと思います。今回場所がちょっと変わりますけれども、前回と比べて広くなるのかどうかということと、運用上の変更点があるのかどうか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"申し訳ありません。スペースが２階にあるけれども、３階にないというのは。","id":"exchange-013"},{"speaker":"松永委員","kind":"確認","question":"１点だけちょっとお伺いしたいのですけれども、確認でトイレについてなのですが、その他は全部洋式化という話をされておりました。そこで、その割合と誰でもトイレのような設備はあるのか、確認だけさせてください。","respondent":"篠田学校計画担当課長","answer":"基本的には和式に関しまして、必ず学校に最低一つは和式を置くような形で、今回も基本的に一つ設置するような方向で考えているところです。それから、誰でもトイレですけれども、逆に言うとバリアフリーのトイレを設置することを予定しているものです。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問・要望","question":"特別支援教室の前にはなく、１階だけということですか。和式については、フロアごとに全部一つずつつけられるのか、再度質問させてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"ハンディキャップがある子どもたちに対応することもあるのですけれども、そういうことを想定して１階に設置しているものです。１階に一つ入れるということを考えてありますけれども、今実施設計の段階ですので、まだ最終的な確定ではないです。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"５・６年生から家庭科なのか、それとも３年生でもあるのか、特別教室の配置との関係性についての考え方を伺いたいなと思います。そういう徒競走をするときに、運動会のシーズンですからあれですけれども、１・２年生ぐらいは５０ｍ走を一生懸命走っていいかなと思います。","respondent":"篠田学校計画担当課長、大関教育総合支援センター長","answer":"特別教室の配置の考え方です。場合によっては３階等に上げたほうが使いやすいため、いずれにしても、その辺の動線等も含めまして今後検討させていただければと思います。３階でいいのかなという状況もありますし、学級ではなく、それぞれの学年が使いやすい場所ということで今の形になるような状況です。","id":"exchange-016"}]},{"id":"topic-02","title":"学事制度審議会第１０回～１２回の報告","agenda":"学事制度審議会第１０回～１２回の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、第１２回目のところで学校選択制についてどういった意見があったのか、もう少し詳しくご説明ほしいと求めました。やはりできるだけ長く、例えば１カ月ぐらいはとったほうがいいのかなと思うのですが、これから１カ月間の延長ができるのか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"委員から２週間では短いというお話をいただいたのですが、その後できるだけ速やかにホームページ等にはその報告書をアップしていく予定です。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもと教育を充実させていくというためにも、学校選択制というのは中止したほうがいいと思いますけれども、改めて伺いたいと思います。多くの方に意見を求めていただければと思うのですけれども、説明会の開催をぜひやっていただきたいと思うのですが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"中間答申に関しての説明会ですけれども、そういった部分を含めまして、できるだけわかりやすいような形で中間答申を作成しているつもりです。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、わかりやすく記載するというお話でしたけれども、読んで理解するというのはなかなか難しいところがあると思います。説明会をやったほうがいろいろ質疑もできて理解が深まると思いますので、ぜひ検討してほしいと求めましたが、改めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"繰り返しになってしまいますけれども、わかりやすくつくりつつ、またリーフレット等も作成して、皆様方にお配りしたいと考えておりますので、説明会については今のところ開催する考えはございません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、少なくとも要旨でしか出せないのであれば、最低限そこは準備をしていただきたいと思っています。制限するという方向性が出てきているのは事実かどうか、その辺について伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"最初に議事録の公開のタイミングなのですけれども、もともと学事制度審議会に関しても非公開で出していただいてありますので、議事録の公開も要旨で行なわせていただいております。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"いろいろなやりとりの中で、そういう制限はしない方向で今までどおりということになっていくということで了解していいわけですか。そういう状況が今あると思うのですけれども、そのあたりの認識というのはどうか尋ねました。","respondent":"篠田学校計画担当課長","answer":"制度自体にそごがあって変えるといった考え方をしているものではございません。そういったことは今申し上げたような形にもつながっているところですので、きちんと対応されているものと考えているものです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと最後のところがよくわからなかったのでもう一度伺いたいのですけれども、そういうふうな捉え方をしているのか、もう一回お願いします。ですから、２０年やってきた中で、そういう事実があるのではないか。","respondent":"篠田学校計画担当課長","answer":"前回の学事制度審議会では、各ブロックを代表して町会長の４名の方に、今までよりも多い形でご参加をいただいているところです。それから、そういったブロック制によって遠くの学校に通うようなことがないような形での見直し等の考え方が整理されてくるものと認識しております。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"詳しくホームページに載せるから、品川区の目玉としての学校選択制ですから、品川区の教育行政を高めていくのだと思ってやっておられると思うのです。学校選択制を推進している側にしてみれば、やらないといけないのではないかなと思うのですけれども、その点についてどうか尋ねました。","respondent":"篠田学校計画担当課長","answer":"さまざまな形で区民の方へのアプローチというのはあると思います。パンフレット、リーフレット等によってわかりやすくご説明することで区民の皆様方にはご理解いただけるものというふうに考えているところです。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"私は反対だからやめてもらいたいと思うけれども、やっていくというのであれば、もっと堂々と区民に説明をするべきです。ぜひ説明会をやるべきだということを強調して終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"さあどうぞで、何の説明会ですかという話になるので、そういう人を惑わすようなことは一切やらないほうがいいです。最終答申が若干の変更となり、何らかの変更が加わることがあるかもしれないというのは、その確認だけ一つとらせてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"説明会の関係ですけれども、今委員からご指摘があったとおり、審議会の答申を受けるというのは事務局の立場として受けるものです。","id":"exchange-025"},{"speaker":"渡部委員","kind":"確認","question":"確認いたしました。町会の総務部長としても、そういう話は毎回していますので、そこはしっかりと申し伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"平成２９年度全国学力・学習状況調査の結果","agenda":"平成２９年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"やはり過度な競争教育につながるのではないかという懸念があるのですけれども、その点、どうされているのか。そして、この調査が実際どのように活かされていくのかというのがなかなか見えにくいのですけれども、今後の活用について伺いたいと思います。","respondent":"熊谷指導課長","answer":"あえて今年度からは整数で８０％ですとか、７８％のように過度な競争をあおるというようなことはしないということをうたっているところです。算数、数学部会等でこれらを活用して、次の教育要領に活かしていくということを今進めているところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"その中で、その上で全国学力テストをやっていくという意味がよく見えないので、そのところを伺いたいと思います。学び合いの教育によって教育効果があるというところでやっていくことが私はいいと思っているのですけれども、その点の考え方も伺いたいと思います。","respondent":"熊谷指導課長","answer":"６年生、９年生、普段の小テストとは異なる部分であろうかと思います。そういったことも確認することができますし、改善につなげていけるということで、乖離しているものではないと考えます。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"それから、５番のところで、東京都も全国もさらにそれよりも下回るこのパーセンテージをどういうふうに評価して見ていいかわからないのです。そもそも数字のレベルが全然わからないので、その辺について専門家から見たところの状況というのはどういうことなのかを改めて伺いたいと思います。","respondent":"熊谷指導課長","answer":"それから、決してそうではなくて、学習指導要領に基づいてきちんと適正に示された授業時数で行ったときに１００％とれるであろうという問題なのです。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"算数Ａと算数Ｂがどういうふうに違いがあるのかちょっとよくわからない中での質問なので、算数Ｂが５３％、数学Ｂが５１％。先生方としてつかんで、具体的に指導に活かすということはどういうことなのかなというのがちょっとわからないので教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"８月に返ってきているのですけれども、例えば６年の問題では、１年から５年までの問題が満遍なく出ているのです。中学校の場合は９年間、１週間前の問題ではなくて、十分活かせると考えています。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"秋田県も含めて、どういうふうに理解していいかわからないし、そういう意識を持っていける子どもを育てていくことが大事なのではないかと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"ですから、あまり数字がどうこうというのではなくて、今後の品川区の教育にどう活かしていくかだと思うのです。物差しにして何か考えていったりすることがあるのかどうか、そこだけ説明を求めました。","respondent":"熊谷指導課長","answer":"今年度、区の学力調査を導入いたしましたけれども、これはまさに今委員ご指摘のとおり経年で追っていくということを重視したものであります。それからどのように改善したのか、また課題は残ったのか、見取っていきたいと思います。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認を含めてですけれども、それと同時に、家庭の親御さんがしっかりこの結果を知っていくということも大事なのかなと思います。１人何冊ぐらい読んでいるのか、どれぐらい講読をしているのかというのが毎日どれぐらいしているのかというのがわかれば参考までに説明を求めました。","respondent":"熊谷指導課長","answer":"各学校には個人面談の際ですとか、また保護者会では個別に説明はしないのですけれども、全体で説明した上で。読んでいますと答えた子どもと学力の相関を見ますと、確かに読みますと答えた子どもの解答率が高いということが言えます。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問・要望","question":"読書についてですが、朝読、たしか朝１０分の読書時間というのは、今この活動はどうなっているのでしょうか。その何でもいいのは、たしか漫画系も含まれて、図書に触れる朝読という活動をたしかやっていたかと思うのですが、今どのような状況か尋ねました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"ボランティアの協力を得て、読み聞かせの会を月に１回から２回設けている小学校も多くなっております。その他、例えば、とにかく読書習慣が身につくよう子どもたちに対する働きかけを全校で引き続き続けているところです。例えば個人面談等で丁寧に説明していくということもありますし、それから態度表明ということで、そういったもので保護者の方に丁寧に説明をしながら。","id":"exchange-034"},{"speaker":"松永委員","kind":"質問・要望","question":"学校質問紙調査の結果概要についてちょっと伺いたいと思うのですけれども、３番、この差というのをちょっと教えていただきたいというのがあります。４番の「全く行っていない」という回答はあったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"校長先生が回答しているものですが、どうやって回答しているかと、副校長が確認してという教育課程の管理があります。ですので、小学校でほぼ１００％近くやっていますというふうに答えているわけなのですけれども、まだまだではないかなという校長の見取りであります。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"算数の中でも、数学の中でも、そういうものがあると思うのです。そういった点、そういう指導のやり方を、ここはこういうふうにしたほうがいいという指導はどのような形で先生方にしているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"月１回教科ごとに全教員が所属しております教育会の部会のほうでも今回の結果の分析は進めております。やはりどちらかというと、例えば若手の３年以内の教員が苦手としそうな課題は、研究授業の形で日々指導力を高めているような努力をしている最中です。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"区独自でそのようにやられているのでしたら、そういう積み重ねがきっとあると思うので、そういうものをリストアップしていく考えはあるのでしょうか。なければ、つくってほしいと求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"子どもたちはもっと伸びるのではないかということを、具体的なところを含めて、その教育要領の中にも示していこうということで動いているところです。それから、また教材等についても今教科と専門部会の中で検討して… 年間、各教科部会で協議内容を冊子にいたしまして、全校に配付して参考にするようにしております。その他、教育総合支援センターのほうで集めて、教員が教育総合支援センターで閲覧をできるようになっております。","id":"exchange-037"}]},{"id":"topic-04","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"毎年のように課題になっている原因は何だと考えているのか伺いたいと思います。これは今回新たにそうなったのか、またこれがもし移行された場合、変更される部分というのはどういったものがあるのか伺いたいと思います。","respondent":"横山品川図書館長、廣田子ども家庭支援課長、吉田保育施設調整担当課長","answer":"こちらの能力として、知識や資格があるだけではなくて、かなりの経験を要するという点があります。昔専門職がいた時代は１０年、発展途上と言えますが… 先ほどのご説明でも若干盛り込ませていただいたのですが、提供会員の募集の取り組みの評価というところを指摘されたところです。… 管理運営費が上がったところで説明を申し上げたところですが、こちらのほうの委託料等で対応いたしまして、処遇改善に取り組んでいる次第です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ昨年改善点として示された部分についてやられているということですので、しっかり改善できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"そして、図書館でも置いていて、こういうところにそういうものを置いておくということの考え方がどうなのかをちょっと改めて伺いたいと思います。それと、製品の販売を担っていただいていると思っているのですけれども、販売についてどういう位置づけであるのかということを伺いたいと思います。","respondent":"廣田子ども家庭支援課長、横山品川図書館長","answer":"３年に一度の定期点検がありまして、工事の金額で差が出るところで、主にひまわり荘の部分と施設全体の管理で差が出るものです。一定の支援員がどう対処したらいいかということについて相談に乗っていただくという心理職をイメージされ… 図書館においては地域事業に力を入れておりますので、地域とともにある図書館としてこのような施設のご紹介という形でやらせていただいております。","id":"exchange-040"},{"speaker":"南委員","kind":"確認","question":"臨床心理士についてですけれども、指定管理が福栄会ということなので、当然福栄会のほうからそういう業務に携わる方を派遣するという形になるのだろうと思っているのですけれども、ちょっとそこだけ確認して終わりたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"今現在、福栄会が任用した臨床心理士が来ているのですけれども、非常勤で毎日いないというところで、そのあたりをもう少し手厚くしたらいいというようなご意見をいただいておりますので、福栄会にはそのあたりについて派遣してもらうように申し入れをしています。","id":"exchange-041"},{"speaker":"こんの委員","kind":"確認","question":"南委員の質問と少し重なる点もありますが、確認を含めてお聞きしたいと思います。スーパーバイザーが要するにサポートする側のサポートというふうに今後なっていくのか、この辺のところを説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"年間１００件近くなってしまうのですけれども、時間の集中ということが多くて、相談内容でお断りするということは現時点では把握をしておりません。福栄会の中のことですので、相談に乗ることはできると認識しております。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"なので、ファミリー・サポートの提供会員が利用者の提供してほしいところに行ったときに、いろいろな家庭の状況が見えるではないですか。見てどうすることもできない、その辺というのは、そういったときの何か対応というのは今までされたケースというのはあるのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"実際に１対１でやることなので、意見、お話を聞くことはできるかと思います。そこでちょっとどんな意見が上がってきているのかというところは区のほうで把握しておりませんので確認しようかと思います。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"提供会員と利用者とも人間関係というか対応はどうですかとアドバイザーから聞かれることはあっても。子育て支援センターのほうは、そこに行く前の段階の方々をより早く見つけるという意味では大事かなと思うのですが、その点いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"一歩踏み込んでどんなことがありますかということが聞けるような場面ができないかというところを２カ所ファミリー・サポート・センターの拠点がありますので、どうやったらできるかについては、検討したいと思います。","id":"exchange-044"},{"speaker":"松永委員","kind":"質問","question":"他にはそういったことを受けられているのかということもお伺いいたします。大井図書館に関しては、１年目はトラブルが多いということで、現状普通どおりに営業されているということなのかについても伺いたいと思います。","respondent":"横山品川図書館長","answer":"２年目以降、指定管理者になれていただいたということで、大分落ち着いてきているという状況です。防火訓練、避難訓練につきましても、たまたま会社が全部１階ですので、その計画に基づきまして一定の水準に基づいて各館で動いているものです。","id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"その防火訓練というのはどういうものなのかということを聞いたのですが、図書館に関しても各館によって多分独自のマニュアルが必要ではないかと思うのですが、そういうものはあるのかどうかとの意見を述べました。","respondent":"横山品川図書館長","answer":"地域センターのほうで防火のマニュアル等をつくって、消防署にご協力いただいて毎年訓練を行うような状況があります。マニュアルにつきましても、簡易なものから詳細なものまでレベルは違うのですけれども、各館でそろえて運営をしているような状況です。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"図書館についても選書などは長年の経験が必要だということですとか、家庭あんしんセンターでは会員の方の負担が重いというようなお話がありました。やはり指定管理者制度というのが、そういった点で指定管理者制度を変えていくという検討も必要なのではないかと思いますが、いかがか尋ねました。","respondent":"横山品川図書館長、廣田子ども家庭支援課長","answer":"先ほど申し上げましたように１０年、２０年の経験というようなキャリアを積むこともなかなか難しい状況ということがあります。で区として運営については区の職員がしっかりと調整をするという形で… 母子生活支援施設であるひまわり荘を抱えておりますので、トワイライトステイと同時にやっているので、指定管理制度のほうが望ましいと考えています。","id":"exchange-047"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"本会議の場で待機児ゼロに向けて、平成３０年度４月の待機児ゼロの見通しがつきそうだという話がありまして、その具体的な数字、需要見込みですとか、認可保育園が何園何人分など、また施設についても、それでゼロになるという具体的なところを教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月の申込み予測ですが、０歳から２歳児の人数でご説明します。認証保育所の入園者等が６４１人で、この計算ですと待機児童は２人となりますので、０人の見通しがたちつつあるです。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、２人の待機児童が出る可能性があるということで、そこはゼロにしていってほしいと求めました。その姿勢を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"今の数字はあくまでも予測ですので、想定外の人数の増加とまた申込者数の偏り等がある可能性もありますので、今現在だけの計画ではなく、他の対応を含めて今後も検討して、平成３０年４月にはゼロを目指していきたいと考えています。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、それを確認したいのと、入所申請数が来年４月にかけて２,９４４人という数字でよろしいでしょうか。数字の確認を先にお願いします。","respondent":"大澤待機児童対策担当課長","answer":"今委員がおっしゃったとおりの数字です。","id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"来年４月にかけて入所申請数が２,９４４人というのは、減っていると認識していいのか、ちょっとそのあたりを教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"最新の申込者数の増加率が４.４％ですので、その４.４％を受けまして平成２９年度の申込者数に４.４％を足した数で出しております。","id":"exchange-051"},{"speaker":"南委員","kind":"確認","question":"ということは、過去は５％で、入所申請が横ばいあるいは若干微減気味というふうに認識しているということなのでしょうか。１,４０４人という数が見込まれるので、２,９４４人というふうに考えているということでいいのかどうか、その辺を改めて確認したいと思っています。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年度につきましては、なくなるであろうということから、今０歳から２歳の人数についてご説明をしています。年齢別の詳細な分析を今している最中ですので、それが出た時点で足りないところがあれば、また新たな対応について検討するです。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"４月時点で認可保育園１６園というところの中には、ちょっと確認したいのと、そういう対応をとっていくということで受けとめていいのですか。この２点です。","respondent":"大澤待機児童対策担当課長","answer":"昨日の話の続きとして、引き続き住民の方とは調整を図って、何とか４月にはご納得いただければというふうに考えております。そして、この他対応ですけれども、もちろん４月に間に合うように何らかの対策を講じてまいります。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"さらなるご努力をお願いしたいのですけれども、そこには、そういうことも覚悟して取り組んでいただきたいということを思っています。その点についての決意、それを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月にゼロを目指して今後とも努力をしてまいります。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"どのくらいの距離のところにあるのかとか、また何人ぐらいの方がそういう状況に該当されるのかとか、その辺がわかったら教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"その方たちには、できれば認可保育園等への編入を進めているということで、近くでは大田区の馬込に１園あります。そのほか、都内に６園ありますので、会社等の都合でそちらのほうが都合がいいという方はそちらに優先的に転園されることもあろうかと思います。","id":"exchange-055"},{"speaker":"南委員","kind":"確認","question":"建物の契約が満期になったことだということなのですけれども、契約の満期を理由にされるというのは、何か特別な事情とかがあるのですか。当初から平成３１年３月で終わりですよと言っていたわけではないのではと思っているので、その辺の確認をしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"当園は平成１４年の開園ですので、平成３１年では１７年が経過することとなります。近隣に代替地を探したけれども、どうしても見つからなくて、閉園せざるを得なくなったという事情です。","id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、そういう点でも強調して主張してきているところなので、やはり厳しく受けとめていただきたいなというふうに思っております。区はどういうふうに思っているのですか、そこを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"区として気を配らなければいけないのは、やはり今入っている方がどこにも行き場がなくなることだと思いますので、それについては東京都とともにきちんと転園先を確保できるように事業者のほうにも働きかけていきたいと考えています。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/154236?Template=document&Id=4924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":75669,"voices":169}},{"id":"h29-20170926-5","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"総務委員会","time":"午前１０時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 第５９号議案 平成２９年度品川区一般会計補正予算","agenda":"「議案審査」を行います。 第５９号議案 平成２９年度品川区一般会計補正予算","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今さら伺うのは大変お恥ずかしいのですけれども、改めて、当初予算と補正予算の考え方をもう一度、きちんと伺いたいのです。当初予算と、それに対して、どういうときに、どういう考え方で補正を組んでいくのか。","respondent":"秋山財政課長","answer":"先ほどもご説明させていただきましたけれども、それに対応する必要があったときに、ご議決いただいて執行するという考えです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１３ページの情報システム運営費追加分についてお伺いします。２０１６年にスタートして、どういったところで、いろいろな分野に広がっていくのかという大もとのところを教えていただきたい。","respondent":"仁平情報推進課長","answer":"この実施時期につきましては、いつからというのは、国から説明されていないところです。今回の旧姓併記の対応ということで、大きくその連携にかかわる部分としましては、こちらの連携の必要性が出てくるということです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと前は３億円という答弁をいただいているのですが、多分、この辺の費用がどんどん膨れ上がっていくと思うのですが、この辺の費用について。区内で漏えいとか個人情報が守られなかった、エラーがあったところがあったら説明を求めました。","respondent":"仁平情報推進課長","answer":"それと、エラーの件ですけれども、今のところ、情報連携等とマイナンバー関係のシステム、いろいろと改修しましたが、エラーは出てきていません。中には、例えば桁が１つずれてしまったということで、そういう情報は全国的に共有されている状況になっております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年の４月に総務省の統計局のサイトがサイバー攻撃に遭って、まだ、その辺も原因究明がしっかりされていないということを私たちは聞いているのです。そういった状況の中で、個人情報を守れないと私たちは思っていますが、この点についてのご見解をお聞かせほしいと求めました。","respondent":"仁平情報推進課長","answer":"国の行政機関と地方自治体の間で行うシステム自体は、閉塞した世界でやっておりまして、一般の方はそこにアクセスできない。この辺の取り扱いにつきましても、職員研修等を行うなど、職員の教育に努めているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"所管のところで運用ができる部分もあると思うので、補正を出すにあたっては、予算的な基準が何かあるのかどうか。そこのところを説明を求めました。","respondent":"秋山財政課長","answer":"額も考慮はしますけれども、そのときの補正の目的で判断をして、一律に何万円以下だから補正はしないということは考えておりません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"それからあと、地域資源活性化事業補助２,２００万円、根本的には観光地とか観光資源の整備や管理に予算を集中すべきではないかと私は思うのです。ちょっと違和感を覚えるのですが、その辺について、ご見解を説明を求めました。","respondent":"秋山財政課長","answer":"法人に対するということで、全ての法人ということではないのですが、私どもとしては、できるところは先に行っていくという考えです。経常的に今まで行われていたもののＰＲの経費ということで出しているものではないとご理解いただければと思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"これからも、私立の保育園でも幼稚園でも、申請をすれば２分の１が補助になるという考え方でいいのでしょうか。その辺、もう一回だけ説明を求めました。","respondent":"秋山財政課長","answer":"今回については障害者・児の施設を対象にした設置費を入れるということですので、障害者の施設についてはほぼ網羅できると考えています。その事業、イベント全体が活性化して、区の観光資源化に資するものという観点で補助をしています。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点お伺いします。決まっている範囲で、わかれば教えてほしいと求めました。","respondent":"安井選挙管理委員会事務局長、仁平情報推進課長","answer":"１８歳に選挙権年齢が下がったので、実際の記載台を６台ほど買って、１６校ぐらいでやったのです。さらに拡充して、多くの学校でやっていこうということで、それ専用の記載台を購入する予定です。ほかの部分もそうなのですけれども、法改正によってシステム改修等が必要になってまいりますと、各自治体で契約しているベンダーに改修を依頼する。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問","question":"それとも、一定のシステムの改修に関しては、もともとの契約の中に、例えばこういう軽微なものに関しては大枠の中に入っているのか。その辺の契約の内容も説明を求めました。","respondent":"仁平情報推進課長","answer":"パッケージ型の導入で対応できるのであれば、なるべく中身をユーザーに合わせた改造をしない、経費を抑えての導入を考えております。そうなると、最初につくった時点では想定されない部分、法の改正等に対応するのは年間の固定経費に入れていくのは難しくなります。","id":"exchange-009"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私が時代遅れなのかもしれませんけれども、旧姓を併記しないことによって何か起きるデメリット、何かその事例とか、これによってどう解消できるのか。そこを区民に説明するのに、こういうことが改善されるということを教えてほしいと求めました。","respondent":"仁平情報推進課長","answer":"区もそういう対応をとっておりますけれども、かなり広がってまいりました。うちの会社は対応していないとか、結婚すると口座名義が変更になってくるわけですけれども、旧姓でも対応してくれる銀行が増えてきました。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"マイナンバーカードに旧姓を併記するということ。今度は、希望すれば交換してくれるという話になると思うのですが、それはいつぐらいからスタートする予定なのか尋ねました。","respondent":"仁平情報推進課長","answer":"ただ、平成３０年何月からを目指しているというところは、まだ国から示されておりません。それはまだこれからですので、今のところ、確定の時期は示されていないところです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"この間の経費で８億円余、大事な税金を使って、区民の情報が守られないということにおいて、さらなるシステム改修はやめるべきであります。ほかの所管のところについては賛成をしておりますけれども、この情報システムの運営費、１点で反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"それに対して補正が２,２００万円ということで、当初予算と補正の関係はどうなのかということで、冒頭に質問させていただきました。反対なのはこれ１点なのですけれども、その点について見過ごすことはできないということで、総合審査においても反対とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"品川区総合戦略の取組状況","agenda":"品川区総合戦略の取組状況","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"２ページ目のところの基本目標２の５のところの項目で、品川区内の企業の付加価値額はどういう意味だか、よくわからない。この額を算定するというあたりは、どのようにされるのかを説明を求めました。","respondent":"柏原企画調整課長","answer":"経済産業省からの特定の調査が定期的にあって、一番下の欄外のところに付加価値額ということで、説明を書かせていただいてあります。例えば人がどれだけ雇われているかとか、給与の関係、品川区の経済力をあらわす１つの重要な統計値であると認識しています。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"これを毎年、国に報告をすると最初、ご説明があったのですけれども、報告をした後は、何か具体的にコメントとかが来るのか。先ほどは平成２９年度、平成３０年度に、今後、活かしていきますということだったのですが、国から何かコメントとかが来るのか尋ねました。","respondent":"柏原企画調整課長","answer":"３ページのところ、国際化への対応をさらに進めつつ…という、ここがこの事業に対して国の交付金をいただいています。現段階では、このことについても、何か国からコメントがあったりとかというところはございません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"それをどういうふうに今後、考えていくのかということ。何か具体的に、こういうふうに力を入れていくというようなことを考えられるのかどうか、お示しくださいとの意見を述べました。","respondent":"柏原企画調整課長","answer":"今の観光客、それから実際の宿泊者数の動きを見ながら、この辺は変更する必要があるのではないかというような捉え方をしております。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問","question":"平成３１年度に向けてのステップアップとして予算を組んでいくのか、現状があって、そこに合わせて来年度予算というのを組んでいくのか。その予算の組み方は、特にどこを基準にしてやられているのか、まず１点、説明を求めました。","respondent":"柏原企画調整課長","answer":"実際のところは、総合実施計画の事業をこの形でカテゴリー別にまとめたものが、この総合戦略ということになります。総合実施計画は、その平成３０年度に向けて、予算の考え方を持ちながら実施計画をつくっております。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"例えば、これだけ事業があって、これだけの人が利用してといったら、普通に考えたら、それだけ予算がかかってくるわけではないですか。平成３１年度目標数値を見る限り、予算になっていくと思うのですけれども、その辺はどのように考えているのか尋ねました。","respondent":"柏原企画調整課長","answer":"今ご指摘いただいたように、総合戦略、実施計画も含めてなのですが、大分、チャレンジングな数字だとは思っております。総合実施計画の中での予算の考え方というのを、６年後にはこうなる、想定できる範囲内には動いていると思っているのです。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"これはこういう仕組みでいいのですか。学識経験者の方たちが話し合う場、また、取り組んだことの成果だけをただ出せばいいということなのか尋ねました。","respondent":"柏原企画調整課長","answer":"例えば、こういった表示の仕方であるとか、皆様にお示しするときなどに、どういった形がいいのかというのは、検討は必要なのだろうと思ってあります。ですので、この表記の仕方、それからＫＰＩの持ち方というのは、これからの検討といいますか、研究は必要なのだと考えています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"今のところ、平成３１年度の目標として定めたところまでは、今のＫＰＩだけでやっていくということなのか。とりあえず今回はこの数値目標だけを点検しながら、平成３１年度までやっていくということなのか、その辺だけ説明を求めました。","respondent":"柏原企画調整課長","answer":"違うＫＰＩをプラスするだとか、そういった可能性、考え方は当然出てくると思います。もう少し事業進捗を見ながら、その辺は改めて検討しながらと思います。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"３年たっていく中で、ぜひ検討してほしいと求めましたので、そういうふうによろしくお願いします。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"平成２８年度、１１事業というところで、こういう事業をされたということなのでしょうか。急激に数が増えているのですけれども、全国自治体との連携事業数というところでとっていると思うのですが、そこの認識を教えていただきたい。","respondent":"柏原企画調整課長","answer":"そのほかには、２３区の区長会でやっている東北の六魂祭というプロジェクトがありましたけれども、それについてのＰＲ活動、参画というのがあります。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問","question":"もともと国が言っている総合戦略の目的に沿うべきというところもあるだろうとも思うのです。最後にそこだけ、お考えをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"地方創生であったりとか、その主な自治体といろいろなところでの事業連携であったりとか関係性を強化していくというのは今後必要だと考えています。こういったところで、どんなことができるかも考えながら進めていきたいと思ってあります。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３ページの基本目標、品川区内で宿泊施設というのは限られると思うのです。施設が限られている中で、どういうふうに目標数値を上げていくのかどうか、お聞かせほしいと求めました。","respondent":"柏原企画調整課長","answer":"キャパシティーの考え方、そういったところも見ながら、この値というのは考えていくべきだと思ってあります。ですので、もう既に目標値は超えているのですけれども、単純に増やせばいいというところではないというところで検討をしています。","id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後の３ページの一番下、もう平成２８年度、おそらく２０万人に到達するであろうと考えているのです。今現在、わかっている時点でどれぐらいを目標にしているのかを教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"このバスターミナルの部分につきましては、正直に申し上げて、今ご指摘いただいたとおり、想定以上の動きになっている部分があります。これも今後の数字の動向を見ながら、平成２９年度の動向が多分中心になると思いますけれども、数値は決めていきたいと思ってあります。","id":"exchange-025"}]},{"id":"topic-03","title":"新公会計制度導入に伴う予算書の新様式","agenda":"新公会計制度導入に伴う予算書の新様式","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"最初の資料、原則１課１目に組み替えるということで、この辺はわかりやすくなると思うのですが、原則とありますけれども、例外はどんなものがあるのか尋ねました。","respondent":"秋山財政課長","answer":"健康課から、同じ事業が３カ所にばらばらになって出てくるということもありますので、複数課１目という形でやろうと今のところ考えています。小学校という横軸で事業を行っていますので、その辺については、複数課１目的な形になると考えています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"それと、複数課１目というと、現行の表記の仕方と変わるのか変わらないのか。その辺も説明を求めました。","respondent":"秋山財政課長","answer":"これは新しく組み替えている最中ですので、これ以外がないのかと言われると断定はできないのですけれども、あまり増やしたくないとは思っています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"複数課１目だった場合の表記についてはいかがか尋ねました。","respondent":"秋山財政課長","answer":"基本的には、新しい方式で表記はします。各事業の後ろに所管課の名称が入るということは変わらず、見た目は１課１目と同じ形になろうかと思います。","id":"exchange-028"}]},{"id":"topic-04","title":"全国シティプロモーションサミット","agenda":"全国シティプロモーションサミット","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"プログラムが示されたということですが、時間などはまだ決まっていないのかということと、それから、今後のこれらについての広報の仕方、それから、２日目の先進事例講演、セミナーの内容というのはまだ決まっていないのか、その辺を説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"キーワードで全国シティプロモーションサミット２０１７、それをキーワードに検索をしていただきまして、一番上に出てまいります。それを機に、実際にこの時間帯、このセミナーという形でご案内ができると考えておりますので、そちらでご案内をしてまいりたいと考えております。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう９月末ですので、求めている人に情報が届きにくいと思いますので、その辺のスケジュールをもう少し詳しく教えていただけますか。もう９月末の段階ですので、教えてほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"実際に広報につきましては、その広報が出る時点では明らかになっている形の想定です。今、それから、１２時１５分から１３時までの時間を各区長のパネルディスカッションという形で設定をさせていただいているところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"それから、もう一つ、連携企業等のＰＲブース、それから、それぞれの自治体からも募ると伺っていますが、今の申し込み状況などがわかれば説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"現在、ブースに関しましては、企業、それから参加自治体でもう固まっているような状態でございまして、これから、どこをどこに配置という具体的な話に入ってまいりたいと考えています。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"きっと品川区でこういうブースが持てるということについては、結構、期待していらっしゃると考えています。都外の自治体の人たちにも来ていただくような仕掛けをしてほしいと求めましたので、これは要望にとどめしますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"１カ月前になったということで、幾つか伺いたいのですけれども、どれぐらい申し込みがあるのかどうか。もう一点、区内見学ですけれども、ホームページで拝見すると有料になっていたのですが、この全５回の中で、有料でやったところはあるのか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"それから、特別区の全国連携プロジェクトにつきましても、具体的な展開事例という形で、全国の皆様にご紹介をするような考えとなっております。多岐にわたりますので、この場でご説明は割愛しますけれども、いろいろと企画しています。","id":"exchange-033"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"せっかく遠くから来ていただくわけですから。ここをお伺いしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"広報の予定についてですけれども、これから実際に、私どもから直接ご案内をするという形。それから、前回の坂井市に参加された自治体であるとか近隣の自治体を対象に、スピーディーに展開をしてまいりたいと考えております。","id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問","question":"今のに関連してなのですが、そもそもシティプロモーションサミットの企画をいつまでに決めるという計画があったのかと、その案内もいつごろまでに出すという、もともとどういうスケジュールがあったのか説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"もともとはお盆明けごろに周知、ご案内をスタートという形で考えておりました。ただ、実際に講座の中身の調整の部分で、なかなか調整がつかなかった部分もございまして、今になってしまったです。","id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問","question":"１カ月を切っている中で、１カ月先の日程は、固まってしまうではないですか。どうやって、１カ月半の遅れを取り戻して、なかなか厳しいのではないかと思うのです。","respondent":"木村報道・プロモーション担当課長","answer":"直接ご案内するのですけれども、ご案内、プッシュをしていくという形の部分。実際に２３区内でも、そういうつながりがありますので、そういう部分でお願いをしてまいりたいと考えているところであります。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"予定も決まっているかもしれないではないですか。いろいろと工夫をしていただいて、１つでも多くの自治体の方たちに参加してもらえるような工夫をぜひやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"庁舎型勤務職員の勤務時間の弾力化の実施","agenda":"庁舎型勤務職員の勤務時間の弾力化の実施","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"目的のところに勤務時間内に恒常的な業務が発生している職場等とあるのですが、窓口の延長はわかるのですが、あと地域センターとかにおいて、恒常的に超勤になってしまう職場は、どういった職場で、どんな業務があるのか、もうちょっと丁寧に説明を求めました。","respondent":"黒田人事課長","answer":"先ほどご説明しましたとおり、地域センター等の地域の会議も基本的には６時とか７時から開始で、９時というようなところもあります。朝、遅目に出てくることによりまして、１日の勤務時間をできる限り正規の勤務時間に近づけたいと考えているものです。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"実情に合った勤務体系を設定していくところにおいては、職場の意見で、それぞれ職場に合った組み立てを職場の皆様の総意で組み立てていくのかどうか。そこのところを説明を求めました。","respondent":"黒田人事課長","answer":"シフトの考え方の設定ですが、わかりやすいようにということで、遅出は１時間ということに設定するという形で計画しております。そういった意味では、各職場の実情を勘案して、制度として運用するものですので、少しわかりやすい形に整理するものです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"意見","question":"そこを心配しているのが１点。多分、組合と協議がされていると思うのですが、組合から出されている意見があったら聞かせてくださいとの意見を述べました。","respondent":"黒田人事課長","answer":"庁内に実施の周知をしておりますが、少数職場ではシフトを組まずに、超過勤務で会議に対応するというようなことも今後もあろうかと思います。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つの勤務形態で済むのだったら人員は十分だと思うけれども、後ろに引っ張ってきたりしたら、必ずどこかが手薄になるのです。だから、ぜひ、その点においては、必要なところには職員の配置もしていくといった考えを持っていただきたいのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"１０月からは試行という形で、年度末は繁忙期ですので、なかなか繁忙期にシフトを組むと支障が出るというところもあります。シフトの時間を変更したら、労働時間を縮減して、労働時間の適正化を図っていくところにまず取り組んでいきたいと思っているところです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１０月試行ということなので、十分、具体的な職場の意見を聞いていただきたい。その姿勢がないと、職員の健康を守るというところにはならないと私は思うのですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"区民サービスや要望への対応を所管しているところでは、こういった勤務時間の弾力化も使いつつ、さまざまな工夫を図って長時間労働を縮減していくというところに取り組んでまいりたいと考えてところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"しっかり仕事をきちんと認めて、足りないところは人手を配置するという考えをぜひ持ってほしいと求めました。最後ですが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"平成２９年度は定数の中で３人増ということで、超過勤務時間が月間８０時間を超えるような場合については、健康管理も適切に行っております。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"ですから、そういう時間帯もある意味で増えるのではないかという期待も見えますので、私はいいのではないかと思います。その中で、また問題点があれば改善して、また考えて、運用していけばいいのではないかと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"石田（し）委員","kind":"質問","question":"弾力化を実施するということで、目的のところで、恒常的な業務が発生する職場等においてと書いてある。目的を見る限り、それはできないと感じてしまったのですが、その辺はどうなっているのか説明を求めました。","respondent":"黒田人事課長","answer":"個人の都合を広く認めると、都でフレックスタイムの試行はしたみたいなのですが、なかなか服務管理が難しいという課題もあります。この弾力化の中では、効果をどう見るかというところをしっかりこれから見ていくところです。","id":"exchange-045"},{"speaker":"石田（し）委員","kind":"提案","question":"ただ単に、そういった環境の人たちが働きやすい環境を行政にはしっかりとつくっていただきたいという意味で、時差出勤を提案しているわけです。これは要望で終わりますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"}]},{"id":"topic-06","title":"南大井文化センター他１施設外壁改修その他工事請負契約","agenda":"南大井文化センター他１施設外壁改修その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"工事内容を見たら、壁の塗り替えが入っていないのですが、外壁と床だけで、壁はそのままなのでしょうか。ちょっと気になったので説明を求めました。","respondent":"小林施設整備課長","answer":"１点目、築４３年です。防音は、今回、要求はなかったものですから、床のフローリングの張り替えだけです。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"築４３年ということですが、建物はしっかりしていて、耐震は大丈夫ということです。防音をやってほしいという声を私は聞いたのと、まあまあきれいだから、そのままでいいということなのか尋ねました。","respondent":"小林施設整備課長","answer":"外壁の改修というのが、いわゆる外壁の塗り替えです。耐震は済んでおりますので、構造的には大丈夫です。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ、セットになってきれいにならないのかが、私は不思議というか、壁だけ塗り替えないで残していくのはなぜかという疑問なのです。よほどの理由がない限り、セットで一緒にやっていただきたいという思いで質問をしております。","respondent":"小林施設整備課長","answer":"今回のフローリングの床の改修というのは、全部で３カ所程度やりますけれども、一つ一つ、その部屋の使用をとめて工事をします。利用を再開したいという一番の目的もありましたので、今回、そういう工事内容になっているということです。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"最後になりますけれども、館の判断もそうだと思いますけれども、所管のところにおいても、壁は今回、塗り直さなくてもいいのではないかという判断のもとに計画が立てられたという理解でよろしいのか尋ねました。","respondent":"小林施設整備課長","answer":"そのとおりです。","id":"exchange-050"},{"speaker":"石田（し）委員","kind":"意見","question":"差が出てしまって、飯沼委員が言ったみたいに逆に目立ってしまって、もったいないと思うのです。その時々に本当に必要なものなのかどうかという判断も、今後、１つの判断基準として持ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"吉田委員","kind":"意見","question":"今の壁については、まだ、そこまで至っていないという判断をされたということですが、一方で、建具については改修工事が３１カ所ということなのです。建具の３１カ所というのは、事例を挙げていただけるとイメージしやすいのですがとの意見を述べました。","respondent":"小林施設整備課長","answer":"こちらは、外壁に面しているアルミサッシなのですけれども、開閉にちょっと支障があるところが３１カ所ありましたので、そちらについては取り替えをする予定で、外壁と一緒に工事をするのがメリットが大きいものですから、今回入っているところです。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう柔軟な判断というのは、私としても、ぜひ今後、求めていきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２３区における採用実績例だけ見ていたのですが、もし、何か具体的に、こういう採用をした結果、こういうような成果が上げられたというような事例がわかれば、１つでも２つでも、教えていただけますか。","respondent":"黒田人事課長","answer":"報道等でも取り上げられて、広告代理店での知見を活かして、いろいろな広報戦略に取り組んでいると伺っております。それが直接、こういった方を採用することで報道等に取り上げられる側面はあると感じてあります。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"これはぜひ、このように進めてほしいと求めました。その辺だけ説明を求めました。","respondent":"黒田人事課長","answer":"都の実施状況を伺ったところでは、比較的、パソコンで簡単にできる業務だけに限ったものだと。この辺は、技術的に難しい面もありますし、職員１人が行う業務の成果も求められると思いますので、今後も研究が必要だと思っているところです。","id":"exchange-055"},{"speaker":"吉田委員","kind":"質問・要望","question":"４条の任期付職員のところでは、結果的にどうなのかとか、これからも丁寧にやってほしいと求めました。これは要望にとどめますが、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今は例えば安定を求めている方、そういう人気が担保できるかといったら、僕は微妙だと思うのです。積極的にこういうことに関しても検討を進めていってほしいと求めましたけれども、改めて、その辺についてもお考えを説明を求めました。","respondent":"黒田人事課長","answer":"それにつきましては、内容によっては、いろいろ対応の仕方があると考えていますので、課題解決のために制度の活用ができればと考えています。技術的に対応できるかという部分に加えて、今後、研究してまいりたいと考えています。","id":"exchange-057"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１つの企業の方のノウハウをと言いますが、電通のノウハウで物事が進んでいっているわけであって、それは一緒ではないですか。これは要望で終わりますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３のところに採用実績例があるのですが、品川区の場合は、このお２人だけということなのでしょうか。そこが大もとの基本であると思うのですが、まず、そこのところはいかがか尋ねました。","respondent":"黒田人事課長","answer":"どういった形で課題を解決していくかという中の、これもツールと申しましょうか、手法の１つではないかと考えています。さまざまな課題を解決するためにどうやった手法を活用するかという視点で、さまざまな工夫を図ることが必要ではないかと考えているものです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは要望ですけれども、規制緩和だからといって、短期間の職員を雇用して、首を切るようなことはあまりしていただきたくない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"あくつ副委員長","kind":"提案","question":"ＣＩＯ補佐官という、首長の補佐官みたいなものを杉並区は導入しているということで、提案をさせていただいたこともあります。法制度があるのですから、選択肢に入れてほしいと思うのですけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"１人の弁護士を雇用することがいいのか、同じ分野でも、さまざまな切り口があろうと思ってあります。例えば、こういった任期付職員の採用ということも検討したほうが課題解決の手段として有効になるかということも含めて、そういった観点で。","id":"exchange-061"},{"speaker":"須貝委員","kind":"意見","question":"その事業に協力してもらう、一緒にやっていくというのも、さまざまな手法があると思います。取り入れるのかどうか、場面で適切な判断をして、採用する云々を考えていけばいいのではないかと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858885?Template=document&Id=2088#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":67777,"voices":165}},{"id":"h29-20170927-14","meetingId":"h29-cm09","date":"2017年9月27日","dateIso":"2017-09-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時２４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"平成２９年請願第９号、羽田空港機能強化による新低空飛行ルート","agenda":"平成２９年請願第９号、羽田空港機能強化による新低空飛行ルート","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"しっかり出させるべきではないかと思うのですけれど、それは可能ということですか、というのが２点目。あるいは２０１９年１２月３１日までやるのかなと思っていたのですけれど、そこら辺はどうなのか、お伺いします。","respondent":"中村都市計画課長","answer":"ただ、いずれにしても騒音に対する対応はしっかりしていただきたいと考えております。一般的に考えるには、国のほうへ情報を提供してくださいと強く申し入れをしておりますけれども、いまだに示されていないです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"機種とか、天候とか、今は１本の線しか引いていませんが、これは十分に幅があるものだというふうに捉えたほうがいいのかどうか、伺いたいです。平成２９年の春ごろから帯が出ていまして、平成３０年の頭をちょっと超すぐらいまであるのですけれども、伺いたいと思います。","respondent":"中村都市計画課長","answer":"そして現在２７施設につきまして、国のほうで防音対応をする予定ということで、さらにその内容について詰めているところです。区としても、具体的に対応する場所については早急に示すよう、お願いしています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"後ろの気流の問題なのでしょうか、次の飛行機は全く同じところでなく、この直線下の人たちだけではない影響があるというところを確認したので。今どこを考えているのか教えていただきたいし、何回調査が行われているかということをお伺いしたので、全部教えていただきたいのですが。","respondent":"中村都市計画課長","answer":"法律上は対応の必要がないというところで、国のほうでは法の弾力的な運用の中で対応するというふうに言っているところです。調査したところが本当に飛行経路の中で影響があるところなのかどうか、まだ決定することができないということで、公表できないです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったのは区内のどこの施設で、何日から何日にかけて行ったのかということを伺ったので、しっかりとお答えほしいと求めました。いかがか尋ねました。","respondent":"中村都市計画課長","answer":"飛行経路が案という段階では、実際に調査はしたけれども、対応しないというところも発生する場合もあり得るということで、現在まだ公表できないです。いずれにしましてもこの案というものが決定しないと、なかなか難しいのかなというのは、区としても受けとめているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"伺います。どう見ても世界でも異常な計画なのですけれど、やはりやめるべきだと思うのですけれど、そのようにお感じにならないか尋ねました。","respondent":"中村都市計画課長","answer":"やはり墜落したり、落下物が起きたときの被害に対する対応もしっかりやっていかなければいけないという前提で、飛行するです。ですので、区といたしましては事後の対応も大切ですけれども、この案を提案していただきたいというふうに考えているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"午前８時前、右のエンジンから火のようなものが出たのを後ろにいた全日空機が確認したため、離陸を中止したということもあります。ですから、これまで海上ルートでやってきたわけですから、もう一度お伺いしたいと思います。","respondent":"中村都市計画課長","answer":"いずれにしましても未然に防げているところが多いというのは、やはり日ごろの取り組みの成果だというふうには考えております。あらゆる事態に対する未然防止に生かしてもらうという、ここら辺は厳重に国に実施していただくよう、求めていきたいと考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後にお伺いしたいのは、丁寧な説明を求めていくのだとこれまでも品川区はおっしゃっていましたが、お伺いしたいと思います。","respondent":"中村都市計画課長","answer":"現在、事故のほうは原因究明中ということで、それに対する対応をしっかり、二度と起こさないような措置、対応をしっかり構築していただくように、区として願っておりますし、またそれを求めてまいります。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"この資料に沿ってお伺いしたのですが、大阪市のような事例は防げるのかということをお伺いしたので、ご答弁お願いします。","respondent":"中村都市計画課長","answer":"さまざまな角度から、未然防止策を徹底していただくという意味で、このチャネルを通じた未然防止策を徹底するということだと考えます。区としても、これは同じ考えです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"全然答えになっていないので、やめられないのですが。落下物が車を直撃してしまった大阪市のような事例を防げると考えるのですか、というふうに聞いているので、ぜひお答えほしいと求めました。","respondent":"中村都市計画課長","answer":"今回のこの事例につきましては、原因が究明されれば、その未然防止策が施されるというふうに考えております。区のほうでは判断できませんけれども、しっかりと起こらないようにしていただくよう、国に求めていくしかないと考えています。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"航路ですからこれから何回も通るということになるのですけれども、そうした落下物の事故の可能性は非常に高まると考えられます。も国土交通省は本当に飛行する気なのですかということを、品川区としても国土交通省に確認していただきたいのですけれども、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"区としてもしっかり対応していただくようお願いをするという過程の中で、国際空港の機能強化に取り組んでいくというところで、進めていくというような考えを聞いているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としても本当にこのままでいいのかということを、頻繁に確認していったほうがいいと思うのです。国土交通省の意思確認、ぜひとも意向を確認していっていただきたいのですけれども、その点については区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"区といたしましても、区民の皆様からいただいた声ですとか、あるいは区として必要な情報提供、こういったものを求めていく中で、国のほうではその辺の声をしっかり受けとめて、必要な措置を全力で講じていくというところで、回答してもらっているところです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも区としてもそうしたことを受けとめて、国土交通省に撤回の余地はないのかということを、確認していっていただきたいと考えております。それと、２７施設は大井町より東側のものなのか、それとも品川区全域なのかということを確認したいと思います。","respondent":"中村都市計画課長","answer":"大井町から東側です。福祉施設、高齢者施設、こういったところです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"最も騒音被害が予想される品川区ですから、住宅の防音工事、対策をやっていただきたいと考えております。ぜひとも国土交通省に対して、そのように要請していただきたいと考えておりますけれども、区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"今、影響がある経路の全建物についてやっていただきたいというのは、国のほうにかねてから申し入れていたところです。ただ住宅といったところは、引き続き最大限の対応がなされるように、国に求めていきたいと考えております。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"この請願第９号は、確認のためお伺いしたいのですけれど、とりわけ昨年の意見書には「教室型を含む多様な説明会」ということで求めておりまして。もし要望をかけていらっしゃるということであれば、どのような形で要望をかけていただいているのかというところを、教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"これは、区もこの説明会、第１フェーズを国が行うと言っていた当時から、教室型説明会を求めているところです。これについては引き続き、求めてまいります。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"多様な形での説明会を求めていくということで、今後もそれは続けていくということで、よろしいという認識なのか。今一度そこだけ説明を求めました。","respondent":"中村都市計画課長","answer":"このオープンハウス型だけでなく、教室型説明会も常に、これからも継続して求めてまいります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この請願でも教室型説明会というのを求められているわけですけれども、それでもやはり今回示されている第４フェーズは、オープンハウス型説明会と。伺いたいと思います。","respondent":"中村都市計画課長","answer":"現に今、大阪市で起きた事故に対しまして、当然不安の払拭にはならないと、逆に不安が大きくなると考えております。区としてもこの事故だけでなく、いかなる事象の事故についても起きないよう、国に強く引き続き求めてまいります。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"万が一あったらどうですかでなく、今、ゼロなのですから、このままゼロで行っていただかないと困るのです。それでぜひ、やはり反対表明を一緒にしていきたいと思うのですけれど、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"直接部品が落下して、民間の車に落ちるというようなことにつきましては、特に重要なことだと認識しております。区としてはこういった取り組みをずっと継続していっていただかなければいけないので、その点について強く申し入れをしていきたいと考えております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"求めても、求め続けていることが実現されない中で、住民も本当に強く求めているのに一向に実現されないというところでは。これを実現してくださいということなので、実現させていくめどというのは、見通しというのはあるのか尋ねました。","respondent":"中村都市計画課長","answer":"最善な周知の方法はどういったものかという検討がなされた中で、広く皆様にお知らせすることができるという、そんな中で決定した説明会です。区としましても、オープンハウス型説明会をやってはいけないということではなくて、さまざまな説明の方法があっていいと考えております。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"教室型を含む多様な手法での説明をしていただくよう求めましたので、区としても要望していっていただきたいと考えております。土日、休日の開催をぜひとも行っていただきたいと考えておりますが、区としてはどのようにお考えか尋ねました。","respondent":"中村都市計画課長","answer":"したがいまして、これが最後ということではなく、この後も継続して説明していただくことになると考えております。１９時までということで、今回は平日ですが、こういった曜日の設定についても国にお願いしてまいりたいと考えております。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"今回、第４フェーズで、最終直線部分の飛行高度を約２０メートル引き上げといった、新しい、比較的重要な情報が出てきていますので、ぜひとも１１月２９日だけと言わず、もう１日程度、土日、休日開催をぜひとも国土交通省にお願いしていただければと思うのですけれど、その点いかがか尋ねました。","respondent":"中村都市計画課長","answer":"１日でも多い開催を、国のほうへ求めてまいります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"品川区の各地域での「教室型」説明会開催に関する請願ということで、きめ細かく教室型説明会を開くようということでの請願です。一点確認させていただきたいのですけれども、どういう考えのもとに国交省に対して教室型説明会を求めているのか、確認させてください。","respondent":"中村都市計画課長","answer":"国のほうで行っているオープンハウス型の説明会、一日でも多い説明会を、そして教室型説明会につきましても開催していただきたい。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから国に情報提供や対策を施すよう求めていくのだという話ですけれども、その対策を求めていくというのでなく、区のやるべきことではないですか。現状は姿勢として私は間違っていると思うのですが、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"しっかりと説明をする義務が国にあると思いますし、また今回こういった１１月に説明会も行われますので、国が区民あるいは国民に対して説明をするということについて。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"求め続けてもそうした対策が出ない、もともとあり得ないわけですから出ないと思うのですけれど、飛行機が飛んだ後でも求め続けるということですか。それは中止を求めないということになると思うのですけれど、飛んだ後でも求め続ける、そういうお答えか尋ねました。","respondent":"中村都市計画課長","answer":"今、国のほうではあくまで案ということで、まだ決定ではないです。仮にという話でございましたら、やはり不安の払拭あるいは必要な情報提供、こういったものは常に求めていく必要があると考えております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"Ｄ滑走路が供用直前の２００９年９月には、突然国が深夜早朝の飛行を提案してきて、事実の証明だと思うのです。自治体の長が反対すれば、計画はとめられるという認識はお持ちかどうか、伺いたいと思いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"もう設置されております滑走路を利用して、便数を増やす運用ができるかという検討の中で、国としてはさまざまな検討をしたという説明です。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"これは重大な問題ですから質問しているのですけれど、変な言葉で言うと、大田区と品川区はプツンとなったわけです。だから今の答弁は、全く私は今回の計画に反対しない理由にならないと思いますけど、いかがか尋ねました。","respondent":"中村都市計画課長","answer":"今現在４つの滑走路があると、こういった条件の中での検討の結果だですので、国がこういった検討をしましたという資料も示されておりますけれども。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"ですから、国はさまざまなリスクがある中で提案してきているのだと、経済成長とか機能強化に取り組むために提案しているのだということで。お伺いしたいのは、濱野区長はどうなのですかということを、私はお伺いしたいと思いますとの意見を述べました。","respondent":"中村都市計画課長","answer":"それを一番最初に考えるべきだと考えております。区としても必要な情報を、引き続き求めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"国に求めているのはわかりますけれど、国の責任ですから、しかし品川区としてできることをやっているのですかということですよね。区民の皆さん２年後どうなるかわかっていますか、どうお考えですかという立場で、区民への周知についての抜本的強化についてはいかがか尋ねました。","respondent":"中村都市計画課長","answer":"現段階においては、国からの説明がまだ十分具体的なものとなっていないというふうに、区としては考えております。そういった意味からいたしまして、オープンハウス型の説明会とともに教室型の説明会を、今まで求めてきたところです。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"国の情報がまだ不十分だから、出せる情報もないということですか。ですから今出ている情報を使って、広報を、この問題を知らしめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"皆さんからのご意見は終わりということなので、委員長の私から１点だけ確認させていただきたいのですけれど、よろしいでしょうか。教室型の説明会を求める請願ですけれども、教室型説明会をやるかどうかについての相談というのはあったかどうか、確認をお願いしたいと思います。","respondent":"中村都市計画課長","answer":"今回のオープンハウス型の説明会に対しまして、その中で国交省としても品川区はやはり影響が大きい自治体であるということは認識しているという中で。今回１１月は１回の開催ですけれども、よい方法がないかどうか、今検討しているといった説明はございました。","id":"exchange-029"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほども確認させていただきました教室型説明会を求めて、区もずっと求め続けているということで、これは私どもの考え方とは異なります。それと、国土交通省に強く要望し、実現してくださいというのも、実現するのは品川区ではございませんので、今回の請願については不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"多様な手法、具体的な説明を引き続き尽くしてもらいたいというふうに、主張をまずさせてほしいと求めました。したがいまして本請願については、意見書を提出した立場から、不採択でいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会としましても区が求め続けているということもありますので、国の態度を改めていただくためにも、採択をすべきだと思います。それは相手が決めることですから、議会としてどういう要請をしていくかということと思いますので、私は矛盾はしないのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"大倉委員","kind":"質問・要望","question":"説明をきめ細かくしていただきたい、できるだけ多い日数で開催していただきたいというふうに国のほうに求めているというご説明もいただきましたので。さらには実現してくださいという部分では、実現するのは国でありますので、この請願については不採択でお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"採択、賛成です。教室型を含む説明会を開くよう求める意見書を採択して、ぜひとも教室型説明会を開いていただきたいという考えのもと、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-02","title":"金沢市児童相談所の視察","agenda":"金沢市児童相談所の視察","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"職員も５０名ほど必要になってくるとおっしゃっていたので、こうした児童福祉司や児童心理司という方がどれぐらい必要になってくるのかということ。心理職も採用したというふうに書いてあったのですけれども、その心理職の方は、今現在、品川区のどこにいらっしゃるのか、伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"虐待の件数なども加算要素ということになってまいりますので、今申し上げたのが最低基準になってくるかと思います。そして３点目、子ども家庭支援センターの機能を担うところに心理職を配置するほか、教育の意味も含めまして配置しています。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"一時保護所というのも設置していくという考えだと思うのですけれど、どちらも区の職員で運営されるものと考えているのかということ。児童福祉司や児童心理司の配置の基準は、一時保護所の方にもあるのかどうか、伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"職員の配置の考え方ですけれども、児童相談所に附帯する機能というふうになっておりまして、切り離すことができないという法令上の解釈です。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"現在の品川区の虐待とか相談の件数というのは、どのぐらいになっているのか。一時保護が必要になった品川の子というのはどこに行くのか、伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"２点目の北品川は、委員ご案内のとおり相談機能しか持ち合わせておりません。前回の事務事業概要の中で少し説明させていただきましたが、特別区内には４つの一時保護所がございまして、保護をするという形になります。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問","question":"金沢市でどのようなところが参考になったのか、今どのように考えていらっしゃるのかということをお聞きしたいと思います。もう１点、今、現時点でどのように捉えているかというところをお願いいたします。","respondent":"高山児童相談所移管担当課長","answer":"放課後対策など先進的な取り組みをしているということで、品川区の強みであり、特性であると考えております。お話伺ったことを精査しながら、品川区に取り込めるものはできるだけ多く、取り込んでいきたいと考えております。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"今、次の質問と絡めてお答えいただければと思うのですが、品川区はどのように考えていらっしゃるのかというところをお聞かせほしいと求めました。区はこちらの金沢市の視察を行って、どのように感じられたのか、ハード面の部分教えてほしいと求めました。","respondent":"高山児童相談所移管担当課長","answer":"２点目としまして、子どもと家庭への支援は一番生活が営まれている、果敢に取り組むことができるのではないかと考えております。その上で、なおのこと事前の調査を綿密に行いまして、盛り込めるものについては当初の段階から進めていきたいと考えております。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"これは要望だけでと思っているのですが、内装面を重視していただいて、これからご検討を進めていただきたいというところをお願いできればと思います。そのあたりも適宜、臨機応変に対応できるような形で、検討のほうを進めていただきたいというのも要望させてほしいと求めました。","respondent":"高山児童相談所移管担当課長","answer":"少しご説明しています児童福祉司、そして児童心理司という、これまで特別区が持ち合わせていない特別な専門職が必要となってまいります。ただ、単に専門性を持ち合わせているだけではレベルの高いケース管理はできませんので、そのような配慮が必要だと考えているところです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"質問したいのですけれど、開設まで３年のタイムラグが金沢市の場合あったということですが、どのような課題があったのかお伺いしたいのと。先ほど虐待の件数を伺ったのですけれども、一時保護件数というのをお伺いしたいのと、お伺いします。","respondent":"高山児童相談所移管担当課長","answer":"先ほどご説明の中で不十分だったかもしれませんが、そして施設建設後、その部分でタイムラグが生じたというふうにお伺いしております。個室も視野に、そういった保護などのケースにも対応できるような、そういった居室設定が必要になっていくかと思います。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"もともと県に２カ所あって、結果的に県を３つのエリアで分けるということだったのですが、改めてわかる範囲で教えていただきたいのが１点です。本当に人が大事だと思っているのですけれども、そこら辺ぜひお願いしたいのですが、いかがか尋ねました。","respondent":"高山児童相談所移管担当課長","answer":"昨年度の一時保護の件数を４２件と申しましたが、申しわけありません、４７件の誤りでした。２３区共通の専門性にかかわる研修につきましては、現在検討を進めてもらっているところですので、育成を図ってまいりたいと考えております。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/502896?Template=document&Id=6036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":40133,"voices":100}},{"id":"h29-20170928-18","meetingId":"h29-cm09","date":"2017年9月28日","dateIso":"2017-09-28","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ３時３０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"やはり品川区のことをよく知っているのは品川区民だと思いますし、どういう位置づけで、例えばボランティアのユニフォームというのですか。どういうかかわり方をしていくのかというのを１点お伺いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２３区共通にいろいろ関わり方がありますので、東京都と連携をして、ボランティアについてのＰＴも立ち上がったところです。青写真も示されていないところですので、区は区として、気運醸成に向けて取り組んでいこうと考えているところです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川区もいち早く招致をやってきたわけですから、東京都に呼びかけをして、連携をとってほしいと求めました。もちろんオリンピック・パラリンピック準備課との連携も必要であろうかと思いますので、その辺を課としてどう考えているか、説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"商店街の数ですが、１２の商店街にやっていただきました。今後は、さらに、観光協会などとも連携して、うまくそういうことをできればなというふうに、今進んでいるところです。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"語学ボランティアの講座なのですけれども、ここで品川区として９月３日現在で４６３名ですか。それをしっかりやっていただきたいのですが、その辺どうお考えなのかを説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"今後も商店街連合会とかを通じまして、引き続き気運醸成に努めさせていただければと考えています。やるものによって、大会ボランティアや組織ボランティアとは違うような形でうまく参加できるような形にできればなというふうには思っております。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"普通に道の案内をすればいいだけですから。やはりリオ行ったときも、一番期待されるのは東京オリンピックだと言っていたわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最終的に今の話で、人数的なものもおわかりだったら教えていただきたい。この何点かお伺いしたけれども、まずそれを説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"２０％は外国人で、アメリカ、イギリス、ロシア、中国、アルゼンチン等の各国から来ていたというふうにうかがいました。このボランティアの戦略にも出ておりますが、はっきりと書かれておりますが、宿泊に関する情報提供について検討をするというふうに書かれてあります。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"東京は治安もいいし、目指して１０倍ぐらいの人が来るのではないですかと言ったら、そこでもう１０万人になってしまうわけではないですか。そういうことを仕掛けていくならあと３年しかないから、そういう提案を受けて、今からこういう事業も実施してはどうかとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区の施設を使うのか。そういったことで、区としても十分認識しておりますので、今後とも検討してまいりたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"私はもう来年度それを準備して、区としてこういうところがあって、こういう提案をしてください。いろいろな提案をしてもらうというのは、私は来年にはそういう部分の行動は起こすべきだと思っているので、それはぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこをしっかり構築していただきたいと思うのですけれどもいかがですかというのが１つです。まだスキームがはっきりしないからそこは示せないのかについてもお伺いしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区が実施するオリンピック・パラリンピックに向けた気運醸成のイベントであるということははっきり打ち出した上でご協力をいただいているところ…これは当然今後もいろいろな区のイベント等に活躍していただきたいと思っているところです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"３年ですから、今から示していくことが必要だと思うのですけれども、その辺についても改めて伺いたいと思います。こうした区と関係の強い法人や団体や組織との連携というのも、あわせて必要だと思いますけれども、いかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"あくまでも区の２０２０年に向けた気運醸成の取り組みのイベントにご協力をしてくださいということで、協力をしていただいているところです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうはいっても、また日本の文化や観光も楽しみに来るわけですから、品川区としてボランティアの募集や周知をしっかりしていく必要があると思います。何かガイドだったり「近くの銭湯はどこですか」とか、例えば「大阪に行きたいのですが新幹線はどうやって乗ったらいいのですか」とか。","respondent":"鈴木文化観光課長","answer":"区のほうでも、今、観光に関するところでは、語学のボランティア。区内のどこででもオリンピックの観戦者でも旅行の方でもいろいろな方に対応できるような区内の状況というのは、整備を進めているです。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"当然会場は品川区ではないのですが、こういったところを２０２０年を充実させるために品川区が率先して２０１９年のラグビーに参画をしていく。ただ、それが一番２０２０年をスムーズに迎えるためのプレになるのではないかなと思うのですが、どういうお考えか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"東京都組織委員会のほうでも、まずラグビーワールドカップ２０１９での経験を大会につなげたいという思いがあるようです。具体的にはもう少し待ってくれというようなお話がありますので、そういった経緯を見つつ、品川区としても動いていきたいというふうに考えてあります。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"２０２０年と２０１９年、品川区が担う役割というのは、イメージとしてはどんな感じなのでしょうか。同じようなイメージなのか、その辺の臨むに当たってのイメージというか、戦略というか、教えていただければと思うのですが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"観戦客の動きも大会のときとは違うのだろうというふうに考えてあります。委員ご指摘のとおり積極的に手を挙げるなどして、２０２０年に備えて少しでも経験則としてつなげられるように工夫をしてまいりたいと考えています。","id":"exchange-012"},{"speaker":"本多委員","kind":"質問・要望","question":"質問の内容は、要するに２０２０年を充実させるためのプレをやってくれということなのです。イメージを教えていただきたいのです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然会場周辺の観光客、観戦客へのご案内と、都市ボランティアが編成されて活躍するものだというふうに考えてあります。今回の東京都の考え方ですので、どういったことで区民の方たちが携われるのかというのは、今後推移を見て考えていきたいと思います。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だけれども、全国自治体に会場があるわけであって、そうすると、組織委員会に対して物事を言っていく必要があるのではないでしょうか。何か１つの共通の基準を持って募集していくなり、複数の区、そういうことをしていくことのほうが私はいいと思うのですがいかがか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば都市ボランティア、会場周辺の案内員につきましては、少なくとも品川区民がご案内できるのが一番望ましい形であろうか考えてあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"意見","question":"だから、お願いしたいのはこういう他の地方自治体との連携をしながら、やはりこのことについては共通の課題だと思うのです。お願いいたしますとの意見を述べました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"東京都と組織委員会は競技会場を有する自治体をはじめとする関係団体と十分に連携し、大会の成功を日本全体で実現できるよう一体的な取り組みの推進を検討していくというふうにはっきり書かれてありますので、はっきりともの申してまいりたいと考えています。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですが、このボランティア戦略の中の２番の戦略の主な内容の(2)の多様な参加者の活動促進で、小学生については体験できる仕組みを検討と。その辺がもしわかれば教えてもらいたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大会ボランティア、都市ボランティアの募集要項はこういった年齢ですので、あくまで別枠だと考えます。東京都、競技運営をサポートしてもらうとかいうようなことを現在考えているようではありますが、戦略ではここまでしか表現されてございません。","id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。それを将来に活かしていただきたいという思いがありますので、ぜひそういう要望をもしできる場がありましたら、要望してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"観光先に来られるかどうかというのは、特にホームステイなども直前でやってもどう対応していいかわからないということもあると思うのです。１９６４年のときもそうだったと思うのですが、具体的に取り組み始めて４年の中で、そこの部分を説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"品川区では、会場ではなくなってしまいましたが、今現在ブライドサッカーを応援しています。大会が終わった後も、また障害者スポーツの振興がさらに発展するということ、今現在はそういった手応えを感じているところです。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問・要望","question":"そういった部分の見方の感触というところで先ほど伺ったわけですけれども、品川区で一生懸命、それはそれで寂しさが残る部分があるかと思うのです。大会は盛り上がらないわけですから、そういう視点も含めた全体の気運醸成だとかということを今後検討してほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"研修の部分につきましては、大会ボランティア、都市ボランティアにおいてそれぞれの研修等がございまして、そうした部分でやっていくです。研修につきましては、まだこれからいろいろ国や関係機関と連携をとりながら検討していくというふうに書かれてあります。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"先ほど、こういう品川区で一生懸命つくり上げた物だけれども、何か連携させる仕組みというのが今後可能性としてあるということですよね。そういう細かい内容は当然これからなのだけれども、そういう可能性があるかということか尋ねました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"競技会場を有する自治体との連携という部分につきまして、接遇や大会情報などの研修の一部を共有化するなどが書かれてあります。ボランティアによる案内の質的向上を目指していくというような指摘がありますので、そうした情報を区としては率先して捉えていきたいと思います。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけいいですか。最後にそれだけお聞きしたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"当然組織委員会から示されておりますそういったガイドラインというものは、各自治体にもう既に送られてありますので、そういった資料につきましては許す限りご提供していきたいと考えています。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これはボランティアだけではなくて、２年前にこういう動きがあるということは、ホスピタリティハウスしかり、先ほど言ったボランティアの施設ですか。あそこも１年半前に美術館をもう押さえていたというぐらいですから、少し遅かったとかそのようなことがないように動いてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長、木村委員長","answer":"今年度予算で調査委託等もついているようなことでございまして、さまざまなノウハウを使って動いているところです。まだ明確なことは言えませんけれども、さまざまなところで動いているということだけご理解いただければと思います。 現時点において、東京都より要望項目に関して回答を得られていないことを鑑み、重複した項目で要望書を提出することを問題ないと考えております。ご意見等につきまして、ご発言を願います。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問","question":"少し外れてしまうかもしれないのですけれども、西側にある公園は、あそこは大井ふ頭中央海浜公園ではなかったのでしょうか。全部か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あえて言うならば３番のその他になるかと思うのですが、もちろん品川区でできる、ぜひ東京都でも考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"提案","question":"何を求めんとされているのかなと。ただこの表現だと、例えば誰でもトイレの複数設置にその内容を込めていくとか、もう少し文言を整理したらいいのではないでしょうかという提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"ＬＧＢＴの施設整備についてですが、ずばり言うと、トイレですよね。もちろんトイレ限定ではないでしょうから、トイレなどの施設整備という感じにすると趣旨が伝わるのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"公園の整備関係で追加というか、当然当たり前のように東京都の港湾局なのか公園関係の部署なのか。アルゼンチンアリなどさまざまなそういった虫もいるので、感染症対策をしっかりやっていただきたいという表現をお願いしたいと思います。","respondent":"木村委員長","answer":"次回東京都オリンピック・パラリンピック準備局にて意見交換などを実施する予定でございまして、どうぞよろしくお願いをいたします。以上で、特定事件調査を終了いたします。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931440?Template=document&Id=6522#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":27307,"voices":71}},{"id":"h29-20170929-5","meetingId":"h29-cm09","date":"2017年9月29日","dateIso":"2017-09-29","committee":"総務委員会","time":"午後 １時２１分～午後 １時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"今まで３区だけだったのが、２つの開票作業がどうしても生じてしまう中で、どのように開票されるのか。特に期日前投票は全ての投票所で投票が可能だと思うので、その辺の変更する部分はどのようになっているのか説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"チラシについても今回の７区についての説明、そちらのほうにも、なるべく周知ができるような形で作成するということを予定しておりまして。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問","question":"３区の人は基本的に変わらないので、７区部分の人たちに、そういうものは封入できないですか。その辺だけ最後説明を求めました。","respondent":"安井選挙管理委員会事務局長","answer":"７区の方については、７区は今までの３区から移行しましたというチラシを入れるような形でお送りする予定です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どの辺で予算が増えているのか教えていただきたいのと、都議会議員選挙の投票率の内訳を教えていただいて、いかがか尋ねました。","respondent":"安井選挙管理委員会事務局長","answer":"とにかくその方たちが２０代、まずは１８歳の方たちからということで、ちょっと長めのスパンで見ていかなければいけないところがあります。特にそこだけというのはなかなか難しいところが現実です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"というのは、ぱっと開けて、行こうかといつもの場所に行ってしまうではないですか。ただ、日数ももうないので何とも言えないのですが、一応その日に開けるという人がいるということを気にかけてやってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"これは投票だから仕方ないという形でやられるのでしょうか。その辺はいかがか尋ねました。","respondent":"安井選挙管理委員会事務局長","answer":"基本的には国から委託されてやるものなので、その辺は補償等はできないということになります。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"意見","question":"１つだけ。何か事前にそこを知らせる、今回アトレはありませんというところ、そこは何か工夫されるのかとの意見を述べました。","respondent":"安井選挙管理委員会事務局長","answer":"今回急遽こういうことだったので、後々の関係を友好にやっていかないと困ると思いまして、その辺も働きかけをしていきたいと思っています。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858885?Template=document&Id=2090#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6721,"voices":32}},{"id":"h29-20170929-10","meetingId":"h29-cm09","date":"2017年9月29日","dateIso":"2017-09-29","committee":"議会運営委員会","time":"午後 ２時０５分～午後 ２時０９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837996?Template=document&Id=5242#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":1563,"voices":12}}]);
